<?php
/**
 * SQLite store for mkultra.monster ActivityPub sink.
 * Path is outside the web root. Never stores remote media bytes.
 */
declare(strict_types=1);

/**
 * Runtime feature switches. Values come from the process environment so an
 * expensive enrichment path can be disabled without changing database data.
 * Names are normalized to VAAK_FEATURE_<NAME>.
 */
function ap_feature_enabled(string $name, bool $default = true): bool
{
    $key = 'VAAK_FEATURE_' . strtoupper(preg_replace('/[^A-Z0-9]+/i', '_', trim($name)) ?: 'UNKNOWN');
    $raw = getenv($key);
    if ($raw === false || trim((string) $raw) === '') {
        return $default;
    }
    return !in_array(strtolower(trim((string) $raw)), ['0', 'false', 'off', 'no'], true);
}

const AP_DB_PATH = '/var/lib/mkultra/ap/ap.sqlite';

/**
 * PostgreSQL is opt-in during the migration. An unset value deliberately keeps
 * the production application on its established SQLite store.
 */
function ap_db_postgres_dsn(): ?string
{
    $dsn = getenv('AP_DB_DSN');
    if (!is_string($dsn) || $dsn === '') {
        return null;
    }
    if (!str_starts_with($dsn, 'pgsql:')) {
        throw new RuntimeException('AP_DB_DSN must use a pgsql: DSN');
    }
    return $dsn;
}

function ap_db_driver(?PDO $db = null): string
{
    if ($db === null) {
        $db = ap_db();
    }
    return strtolower((string) $db->getAttribute(PDO::ATTR_DRIVER_NAME));
}

/** Return the ID generated by the preceding insert on either supported driver. */
function ap_db_last_insert_id(string $table, string $column = 'id', ?PDO $db = null): int
{
    $db ??= ap_db();
    if (ap_db_driver($db) !== 'pgsql') {
        return (int) $db->lastInsertId();
    }
    $st = $db->prepare('SELECT pg_get_serial_sequence(?, ?)');
    $st->execute([$table, $column]);
    $sequence = $st->fetchColumn();
    if (!is_string($sequence) || $sequence === '') {
        throw new RuntimeException("No PostgreSQL sequence for {$table}.{$column}");
    }
    return (int) $db->lastInsertId($sequence);
}

/** Fallback avatar for remote actors before their icon is cached (not cmdr_nova's personal art). */
const AP_REMOTE_AVATAR_FALLBACK = 'https://mkultra.monster/img/avatar/default.webp';

/** Default avatar for local users who have not set a custom icon (instance mark). */
const AP_LOCAL_AVATAR_FALLBACK = 'https://mkultra.monster/img/avatar/local-default.webp';

/** Custom avatar for Wafrn pending-approval DM peer (VAAK registration alerts). */
const AP_WAFRN_APPROVALS_AVATAR = 'https://mkultra.monster/img/avatar/wafrn-approvals.webp';

/**
 * Optional avatar override for synthetic / notification peers.
 * Used so Wafrn (and similar) alert DMs show a chosen icon in VAAK + Ice Cubes.
 */
function ap_peer_avatar_override(string $actorId): ?string
{
    static $map = null;
    if ($map === null) {
        $wafrn = defined('AP_WAFRN_APPROVALS_AVATAR')
            ? AP_WAFRN_APPROVALS_AVATAR
            : 'https://mkultra.monster/img/avatar/wafrn-approvals.webp';
        $map = [
            'https://waffles.baeddel.social/fediverse/blog/admin' => $wafrn,
            'https://app.wafrn.net/fediverse/blog/admin' => $wafrn,
        ];
    }
    $actorId = rtrim(trim($actorId), '/');
    return $map[$actorId] ?? null;
}

/** Resolve a local profile icon URL, falling back to the instance default mark. */
function ap_local_avatar_url(?string $iconUrl = null): string
{
    $clean = function_exists('ap_profile_sanitize_https_url')
        ? ap_profile_sanitize_https_url($iconUrl)
        : (is_string($iconUrl) && str_starts_with($iconUrl, 'https://') ? $iconUrl : null);
    if ($clean !== null && $clean !== '') {
        return $clean;
    }
    return defined('AP_LOCAL_AVATAR_FALLBACK')
        ? AP_LOCAL_AVATAR_FALLBACK
        : 'https://mkultra.monster/img/avatar/local-default.webp';
}

function ap_db(): PDO
{
    static $pdo = null;
    if ($pdo instanceof PDO) {
        return $pdo;
    }
    $postgresDsn = ap_db_postgres_dsn();
    if ($postgresDsn !== null) {
        if (!in_array('pgsql', PDO::getAvailableDrivers(), true)) {
            throw new RuntimeException('AP_DB_DSN is configured but pdo_pgsql is unavailable');
        }
        $user = getenv('AP_DB_USER');
        $password = getenv('AP_DB_PASSWORD');
        $pdo = new PDO($postgresDsn, $user !== false && $user !== '' ? $user : null, $password !== false && $password !== '' ? $password : null, [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES => false,
        ]);
        $pdo->exec("SET lock_timeout = '3s'");
        $pdo->exec("SET statement_timeout = '30s'");
        ap_db_migrate_postgres($pdo);
        return $pdo;
    }

    $dir = dirname(AP_DB_PATH);
    if (!is_dir($dir)) {
        mkdir($dir, 0750, true);
    }
    $pdo = new PDO('sqlite:' . AP_DB_PATH, null, null, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_TIMEOUT => 30,
    ]);
    $pdo->exec('PRAGMA journal_mode = WAL');
    $pdo->exec('PRAGMA synchronous = NORMAL');
    // Wait for writers (inbox / workers). 5s was still too short under php-fpm fan-out
    // and caused admin mid-render fatals (black Remote profile / truncated Notifications).
    // Keep short: admin Federated was waiting the full 30s on relay write locks.
    $pdo->exec('PRAGMA busy_timeout = 3000');
    $pdo->exec('PRAGMA foreign_keys = ON');
    // Timeline/read-heavy: larger page cache + mmap cuts repeated events scans.
    $pdo->exec('PRAGMA cache_size = -65536'); // ~64MB
    $pdo->exec('PRAGMA temp_store = MEMORY');
    $pdo->exec('PRAGMA mmap_size = 268435456'); // 256MB
    ap_db_migrate($pdo);
    return $pdo;
}

/**
 * Staging-only PostgreSQL bootstrap. The full schema is currently imported
 * from SQLite by pgloader, then checked here before PHP is permitted to use it.
 * This prevents a typo in AP_DB_DSN from booting the app against an empty DB.
 */
function ap_db_migrate_postgres(PDO $db): void
{
    // Local-only operator notices shown inside the authenticated VAAK shell.
    // They are intentionally not ActivityPub objects or federation content.
    $noticeTablesReady = false;
    try {
        $noticeTablesReady = (bool) $db->query(
            "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_notices')
                    AND EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_notice_replies')"
        )->fetchColumn();
    } catch (Throwable $e) {
        error_log('[ap-db] notice table probe failed: ' . $e->getMessage());
    }
    if (!$noticeTablesReady) {
        try {
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_notices (
    id BIGSERIAL PRIMARY KEY,
    title TEXT NOT NULL DEFAULT '',
    body TEXT NOT NULL DEFAULT '',
    published INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
)
SQL);
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_notice_replies (
    id BIGSERIAL PRIMARY KEY,
    notice_id BIGINT NOT NULL,
    owner_user_id BIGINT NOT NULL,
    body TEXT NOT NULL,
    created_at TEXT NOT NULL
)
SQL);
        $db->exec('CREATE INDEX IF NOT EXISTS idx_ap_notices_published ON ap_notices(published, updated_at DESC)');
        $db->exec('CREATE INDEX IF NOT EXISTS idx_ap_notice_replies_notice ON ap_notice_replies(notice_id, created_at ASC, id ASC)');
      } catch (Throwable $e) {
        // Production PHP roles may have DML but not public-schema DDL.
        // The required-table check below still fails safely if provisioning is incomplete.
        error_log('[ap-db] notice tables not provisioned by runtime role: ' . $e->getMessage());
        }
    }

    $discussTablesReady = false;
    try {
        $discussTablesReady = (bool) $db->query(
            "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_discuss_categories')
                    AND EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_discuss_topics')
                    AND EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_discuss_posts')
                    AND EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = 'ap_discuss_reads')"
        )->fetchColumn();
    } catch (Throwable $e) {
        error_log('[ap-db] discussion table probe failed: ' . $e->getMessage());
    }
    if (!$discussTablesReady) {
      try {
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_discuss_categories (
    id BIGSERIAL PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    position INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
)
SQL);
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_discuss_topics (
    id BIGSERIAL PRIMARY KEY,
    category_id BIGINT NOT NULL,
    owner_user_id BIGINT NOT NULL,
    title TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    locked INTEGER NOT NULL DEFAULT 0
)
SQL);
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_discuss_posts (
    id BIGSERIAL PRIMARY KEY,
    topic_id BIGINT NOT NULL,
    owner_user_id BIGINT NOT NULL,
    body TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
)
SQL);
        $db->exec('CREATE INDEX IF NOT EXISTS idx_ap_discuss_topics_category ON ap_discuss_topics(category_id, updated_at DESC, id DESC)');
        $db->exec('CREATE INDEX IF NOT EXISTS idx_ap_discuss_posts_topic ON ap_discuss_posts(topic_id, created_at ASC, id ASC)');
        $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS ap_discuss_reads (
    owner_user_id BIGINT NOT NULL,
    topic_id BIGINT NOT NULL,
    last_read_at TEXT NOT NULL,
    PRIMARY KEY (owner_user_id, topic_id)
)
SQL);
        $db->exec('CREATE INDEX IF NOT EXISTS idx_ap_discuss_reads_topic ON ap_discuss_reads(topic_id, last_read_at)');
        $db->exec("INSERT INTO ap_discuss_categories (slug, name, description, position, created_at, updated_at) VALUES
            ('general', 'General', 'Open discussion for local VAAK users.', 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
            ('help', 'Help & support', 'Questions, troubleshooting, and practical help.', 20, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
            ('fediverse', 'Fediverse', 'ActivityPub, apps, federation, and the wider network.', 30, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
            ('virtual-worlds', 'Virtual worlds', 'OpenSim, Second Life, and related projects.', 40, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
            ON CONFLICT (slug) DO NOTHING");
      } catch (Throwable $e) {
        error_log('[ap-db] discussion tables not provisioned by runtime role: ' . $e->getMessage());
      }
    }
    $requiredTables = [
        'account_aliases', 'actor_profile', 'ap_account_move', 'ap_anti_ai_actors',
        'ap_anti_ai_hits', 'ap_bites', 'ap_blocks', 'ap_collection_items',
        'ap_collection_memberships', 'ap_collections', 'ap_drafts', 'ap_featured_accounts',
        'ap_instance_docs', 'ap_instance_rules', 'ap_invite_codes', 'ap_muted_words',
        'ap_mutes', 'ap_post_queue', 'ap_post_subscriptions', 'ap_queue_settings',
        'ap_relays', 'ap_reports', 'ap_search_docs', 'ap_search_meta', 'ap_sl_challenges',
        'ap_sl_links', 'ap_user_blocks', 'ap_users', 'app_auth', 'direct_messages',
        'events', 'followers', 'following', 'ap_follow_requests', 'link_preview_cards', 'masto_account_actors',
        'masto_bookmarks', 'masto_favourites', 'masto_followed_tags', 'masto_list_accounts',
        'masto_lists', 'masto_markers', 'masto_media', 'masto_pins', 'masto_polls',
        'masto_reblogs', 'masto_statuses', 'masto_suggestion_dismissals', 'mentions',
        'oauth_apps', 'oauth_codes', 'oauth_tokens', 'outbox_notes', 'push_subscriptions', 'ap_notices', 'ap_notice_replies',
        'ap_discuss_categories', 'ap_discuss_topics', 'ap_discuss_posts', 'ap_discuss_reads',
        'quote_authorizations', 'remote_actors', 'remote_custom_emojis', 'remote_emoji_host_meta',
        'remote_media_cache', 'site_syndications',
    ];
    $st = $db->query("SELECT tablename FROM pg_tables WHERE schemaname = current_schema()");
    $present = array_fill_keys(array_map('strval', $st->fetchAll(PDO::FETCH_COLUMN)), true);
    $missing = array_values(array_filter($requiredTables, static fn(string $table): bool => !isset($present[$table])));
    if ($missing) {
        throw new RuntimeException('PostgreSQL staging schema is incomplete: ' . implode(', ', $missing));
    }

    $searchReady = (bool) $db->query(
        "SELECT EXISTS (
             SELECT 1 FROM information_schema.columns
             WHERE table_schema = current_schema()
               AND table_name = 'ap_search_docs'
               AND column_name = 'body_tsv'
         )
         AND to_regclass('idx_ap_search_docs_body_tsv') IS NOT NULL"
    )->fetchColumn();
    if (!$searchReady) {
        throw new RuntimeException('PostgreSQL search schema is incomplete; run the staging bootstrap first');
    }

    // Timeline queries constrain actor/type/action and then sort by recency.
    // Keep this best-effort because the PHP-FPM role may not own indexes.
    try {
        $idx = $db->query("SELECT indexname FROM pg_indexes WHERE schemaname = current_schema() AND indexname IN ('idx_events_actor_type_action_created', 'idx_events_type_action_created', 'idx_events_timeline_actor_created', 'idx_events_timeline_created')")->fetchAll(PDO::FETCH_COLUMN);
        $idx = array_fill_keys(array_map('strval', $idx), true);
        if (empty($idx['idx_events_actor_type_action_created'])) {
            $db->exec('CREATE INDEX IF NOT EXISTS idx_events_actor_type_action_created ON events(actor_id, type, action_taken, created_at DESC, id DESC)');
        }
        if (empty($idx['idx_events_type_action_created'])) {
            $db->exec('CREATE INDEX IF NOT EXISTS idx_events_type_action_created ON events(type, action_taken, created_at DESC, id DESC)');
        }
        if (empty($idx['idx_events_timeline_actor_created'])) {
            $db->exec("CREATE INDEX IF NOT EXISTS idx_events_timeline_actor_created ON events(actor_id, created_at DESC, id DESC) WHERE type IN ('Create','Announce') AND action_taken IN ('log','local_observe')");
        }
        if (empty($idx['idx_events_timeline_created'])) {
            $db->exec("CREATE INDEX IF NOT EXISTS idx_events_timeline_created ON events(created_at DESC, id DESC) WHERE type IN ('Create','Announce') AND action_taken IN ('log','local_observe')");
        }
    } catch (Throwable $e) {
        error_log('[ap-db] timeline indexes not provisioned: ' . $e->getMessage());
    }
    // Notification feeds filter by account and soft-delete state, then page by id.
    try {
        $hasNotifIndex = (bool) $db->query(
            "SELECT 1 FROM pg_indexes WHERE schemaname = current_schema() AND indexname = 'idx_mentions_owner_deleted_id'"
        )->fetchColumn();
        if (!$hasNotifIndex) {
            $db->exec('CREATE INDEX IF NOT EXISTS idx_mentions_owner_deleted_id ON mentions(owner_user_id, deleted_at, id DESC)');
        }
    } catch (Throwable $e) {
        error_log('[ap-db] notification index not provisioned: ' . $e->getMessage());
    }
    try {
        $hasColumn = (bool) $db->query("SELECT 1 FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'actor_profile' AND column_name = 'auto_unblur_sensitive'")->fetchColumn();
        if (!$hasColumn) {
            $db->exec('ALTER TABLE actor_profile ADD COLUMN auto_unblur_sensitive INTEGER NOT NULL DEFAULT 0');
        }
    } catch (Throwable $e) {
        error_log('[ap-db] auto-unblur profile column not provisioned: ' . $e->getMessage());
    }
    try {
        $hasColumn = (bool) $db->query("SELECT 1 FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = 'actor_profile' AND column_name = 'auto_delete_posts_7d'")->fetchColumn();
        if (!$hasColumn) {
            $db->exec('ALTER TABLE actor_profile ADD COLUMN auto_delete_posts_7d INTEGER NOT NULL DEFAULT 0');
        }
    } catch (Throwable $e) {
        error_log('[ap-db] retention profile column not provisioned: ' . $e->getMessage());
    }

    // pgloader preserves SQLite primary-key columns but may not create the
    // serial/identity default that inserts rely on. Personal blocks omit id
    // deliberately, so ensure PostgreSQL can generate it after the cutover.
    try {
        $idDefault = $db->query(
            "SELECT column_default FROM information_schema.columns
             WHERE table_schema = current_schema() AND table_name = 'ap_user_blocks' AND column_name = 'id'"
        )->fetchColumn();
        if (!is_string($idDefault) || !str_contains($idDefault, 'ap_user_blocks_id_seq')) {
            $db->exec('CREATE SEQUENCE IF NOT EXISTS ap_user_blocks_id_seq');
            $db->exec("SELECT setval('ap_user_blocks_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM ap_user_blocks), 0) + 1, 1), false)");
            $db->exec("ALTER SEQUENCE ap_user_blocks_id_seq OWNED BY ap_user_blocks.id");
            $db->exec("ALTER TABLE ap_user_blocks ALTER COLUMN id SET DEFAULT nextval('ap_user_blocks_id_seq')");
        }
    } catch (Throwable $e) {
        // The application role may not have DDL privileges; provisioning can
        // apply this one-time sequence guard separately as the DB owner.
        error_log('[ap-db] personal-block id sequence not provisioned: ' . $e->getMessage());
    }
}

/**
 * True when a PDO/SQLite exception is a transient lock contention.
 */
function ap_db_is_locked_exception(Throwable $e): bool
{
    $msg = $e->getMessage();
    return str_contains($msg, 'database is locked')
        || str_contains($msg, 'SQLITE_BUSY')
        || str_contains($msg, 'SQLSTATE[HY000]: General error: 5');
}

/**
 * Prepare+execute with retries on SQLite busy/locked.
 * Re-prepares each attempt — reusing a statement after a busy failure can
 * yield SQLITE_MISUSE (error 21) on PDO SQLite.
 * Returns false if still locked after retries (does not throw for lock).
 *
 * @return PDOStatement|false statement after successful execute, or false on lock
 */
function ap_db_execute_retry(string $sql, array $params = [], int $tries = 8): PDOStatement|false
{
    $delayUs = 25000; // 25ms
    $last = null;
    for ($i = 0; $i < $tries; $i++) {
        try {
            $st = ap_db()->prepare($sql);
            $st->execute($params);
            return $st;
        } catch (Throwable $e) {
            $last = $e;
            $retryable = ap_db_is_locked_exception($e)
                || str_contains($e->getMessage(), 'General error: 21');
            if (!$retryable || $i === $tries - 1) {
                if (ap_db_is_locked_exception($e) || str_contains($e->getMessage(), 'General error: 21')) {
                    error_log('[ap-db] still locked/misuse after retries: ' . $e->getMessage());
                    return false;
                }
                throw $e;
            }
            usleep($delayUs);
            $delayUs = min(500000, (int) ($delayUs * 1.7));
        }
    }
    if ($last) {
        error_log('[ap-db] execute_retry gave up: ' . $last->getMessage());
    }
    return false;
}

function ap_db_migrate(PDO $db): void
{
    $db->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    type TEXT NOT NULL,
    actor_id TEXT,
    object_id TEXT,
    target_actor TEXT,
    host TEXT,
    bytes INTEGER DEFAULT 0,
    action_taken TEXT,
    summary TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_created ON events(created_at);
CREATE INDEX IF NOT EXISTS idx_events_type ON events(type);
CREATE INDEX IF NOT EXISTS idx_events_host ON events(host);

CREATE TABLE IF NOT EXISTS ap_follow_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_actor_id TEXT NOT NULL,
    actor_id TEXT NOT NULL,
    inbox TEXT,
    shared_inbox TEXT,
    username TEXT,
    follow_activity_id TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(owner_actor_id, actor_id)
);
CREATE INDEX IF NOT EXISTS idx_ap_follow_requests_owner_status
    ON ap_follow_requests(owner_actor_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS followers (
    actor_id TEXT PRIMARY KEY,
    inbox TEXT,
    shared_inbox TEXT,
    followed_at TEXT NOT NULL,
    last_seen TEXT NOT NULL,
    username TEXT,
    host TEXT
);

CREATE TABLE IF NOT EXISTS following (
    actor_id TEXT PRIMARY KEY,
    followed_at TEXT NOT NULL,
    host TEXT
);

CREATE TABLE IF NOT EXISTS mentions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    activity_id TEXT,
    object_id TEXT,
    actor_id TEXT,
    type TEXT,
    content TEXT,
    in_reply_to TEXT,
    deleted_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_mentions_created ON mentions(created_at);
-- Legacy single-user unique on object_id alone breaks multi-user notifications;
-- ownership is UNIQUE(owner_user_id, object_id) after Slice F.

CREATE TABLE IF NOT EXISTS outbox_notes (
    id TEXT PRIMARY KEY,
    create_id TEXT NOT NULL,
    published TEXT NOT NULL,
    content TEXT NOT NULL,
    in_reply_to TEXT,
    to_json TEXT,
    cc_json TEXT,
    raw_create_json TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_outbox_published ON outbox_notes(published);

CREATE TABLE IF NOT EXISTS actor_profile (
    actor_key TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    summary TEXT NOT NULL,
    attachment_json TEXT NOT NULL DEFAULT '[]',
    icon_url TEXT,
    image_url TEXT,
    manually_approves INTEGER NOT NULL DEFAULT 0,
    discoverable INTEGER NOT NULL DEFAULT 1,
    auto_unblur_sensitive INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL
);
SQL);

    // Additive column for display-only remote media URLs (never bytes)
    $mentionCols = $db->query('PRAGMA table_info(mentions)')->fetchAll();
    $mentionNames = array_column($mentionCols, 'name');
    if (!in_array('media_urls', $mentionNames, true)) {
        $db->exec('ALTER TABLE mentions ADD COLUMN media_urls TEXT');
    }
    if (!in_array('activity_type', $mentionNames, true)) {
        $db->exec('ALTER TABLE mentions ADD COLUMN activity_type TEXT');
    }

    // Collections consent (FEP-7aa9 canFeature) — separate from general discoverable
    $profileCols = $db->query('PRAGMA table_info(actor_profile)')->fetchAll();
    $profileNames = array_column($profileCols, 'name');
    if (!in_array('collection_consent', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN collection_consent INTEGER NOT NULL DEFAULT 1');
    }
    // Mastodon/AS2 indexable — public posts eligible for fediverse / search indexing
    if (!in_array('indexable', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN indexable INTEGER NOT NULL DEFAULT 1');
    }
    // Vanity “verified” checkmark (local fun — not real platform verification)
    if (!in_array('vanity_verified', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN vanity_verified INTEGER NOT NULL DEFAULT 0');
    }
    // Opt-in auto follow-back when someone Follows you (default off for all accounts)
    if (!in_array('auto_follow_back', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN auto_follow_back INTEGER NOT NULL DEFAULT 0');
    }
    // Viewer preference: highlight anti-AI posters (slop/clanker heuristic) in timelines
    if (!in_array('anti_ai_marker', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN anti_ai_marker INTEGER NOT NULL DEFAULT 0');
    }
    if (!in_array('auto_unblur_sensitive', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN auto_unblur_sensitive INTEGER NOT NULL DEFAULT 0');
    }
    if (!in_array('auto_delete_posts_7d', $profileNames, true)) {
        $db->exec('ALTER TABLE actor_profile ADD COLUMN auto_delete_posts_7d INTEGER NOT NULL DEFAULT 0');
    }

    // Persistent anti-AI actor marks from cached post heuristics (survives events prune)
