-- Private Mastodon-style Lists (Library → Lists). Not the same as Collections.
CREATE TABLE IF NOT EXISTS masto_lists (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    replies_policy TEXT NOT NULL DEFAULT 'list',
    exclusive INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_masto_lists_updated ON masto_lists(updated_at DESC);

CREATE TABLE IF NOT EXISTS masto_list_accounts (
    list_id INTEGER NOT NULL,
    actor_id TEXT NOT NULL,
    added_at TEXT NOT NULL,
    PRIMARY KEY (list_id, actor_id),
    FOREIGN KEY (list_id) REFERENCES masto_lists(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_masto_list_accounts_actor ON masto_list_accounts(actor_id);

-- Account aliases (alsoKnownAs) + Move state
CREATE TABLE IF NOT EXISTS account_aliases (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    actor_key TEXT NOT NULL DEFAULT 'cmdr_nova',
    alias_actor_id TEXT NOT NULL,
    alias_acct TEXT,
    direction TEXT NOT NULL,
    verified_at TEXT,
    created_at TEXT NOT NULL,
    UNIQUE(actor_key, alias_actor_id, direction)
);
CREATE INDEX IF NOT EXISTS idx_account_aliases_key ON account_aliases(actor_key, direction);

CREATE TABLE IF NOT EXISTS ap_account_move (
    actor_key TEXT PRIMARY KEY,
    moved_to_actor_id TEXT,
    moved_to_acct TEXT,
    moved_at TEXT,
    cleared_at TEXT
);

-- Wafrn-compatible bites (https://ns.mia.jetzt/as#Bite)
CREATE TABLE IF NOT EXISTS ap_bites (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    activity_id TEXT NOT NULL UNIQUE,
    direction TEXT NOT NULL,
    biter_actor_id TEXT NOT NULL,
    target_kind TEXT NOT NULL,
    target_id TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ap_bites_created ON ap_bites(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ap_bites_biter ON ap_bites(biter_actor_id);

-- Federated reports (ActivityPub Flag) — inbound + outbound
CREATE TABLE IF NOT EXISTS ap_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    activity_id TEXT NOT NULL UNIQUE,
    direction TEXT NOT NULL,
    reporter_actor_id TEXT NOT NULL,
    target_actor_id TEXT,
    status_uris_json TEXT,
    comment TEXT,
    about_us INTEGER NOT NULL DEFAULT 0,
    state TEXT NOT NULL DEFAULT 'open',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ap_reports_state ON ap_reports(direction, state, id DESC);
CREATE INDEX IF NOT EXISTS idx_ap_reports_about ON ap_reports(about_us, state);

-- Mastodon-compatible ActivityPub relays (Follow as:Public → Accept)
CREATE TABLE IF NOT EXISTS ap_relays (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    inbox_url TEXT NOT NULL UNIQUE,
    state TEXT NOT NULL DEFAULT 'idle',
    follow_activity_id TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ap_relays_state ON ap_relays(state);

-- Opt-in notifications for another actor's Creates (VAAK "Notify me of posts")
CREATE TABLE IF NOT EXISTS ap_post_subscriptions (
    owner_user_id INTEGER NOT NULL,
    target_actor_id TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (owner_user_id, target_actor_id)
);
CREATE INDEX IF NOT EXISTS idx_ap_post_subscriptions_owner
    ON ap_post_subscriptions(owner_user_id, created_at DESC);

-- Second Life avatar ↔ VAAK account links (Primfeed-style IM verification)
CREATE TABLE IF NOT EXISTS ap_sl_links (
    owner_user_id INTEGER NOT NULL UNIQUE,
    sl_username TEXT NOT NULL,
    sl_agent_id TEXT NOT NULL,
    sl_display_name TEXT,
    sl_profile_image_url TEXT,
    verified_at TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ap_sl_links_agent ON ap_sl_links(sl_agent_id);
CREATE TABLE IF NOT EXISTS ap_sl_challenges (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_user_id INTEGER NOT NULL,
    sl_username TEXT NOT NULL,
    sl_agent_id TEXT NOT NULL,
    code_hash TEXT NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ap_sl_challenges_owner ON ap_sl_challenges(owner_user_id, expires_at);

-- Mastodon-style featured accounts (endorsements) on local profiles
CREATE TABLE IF NOT EXISTS ap_featured_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_user_id INTEGER NOT NULL,
    target_actor_id TEXT NOT NULL,
    position INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    UNIQUE(owner_user_id, target_actor_id)
);
CREATE INDEX IF NOT EXISTS idx_ap_featured_owner
    ON ap_featured_accounts(owner_user_id, position ASC, id ASC);
SQL);

