    require_once __DIR__ . '/ap-search-fts.php';
    ap_search_fts_migrate($db);
}

/**
 * Default editable fields for a local actor.
 * Bridgy / cmplxdecay blurb is only for cmdr_nova; other keys get a neutral bio.
 */
function ap_profile_defaults(string $actorKey = 'cmdr_nova'): array
{
    $actorKey = strtolower(trim($actorKey));
    $actorKey = preg_replace('/[^a-z0-9_]/', '', $actorKey) ?: 'cmdr_nova';
    $isCmdr = ($actorKey === 'cmdr_nova');
    if ($isCmdr) {
        $summary = '<p>Local ActivityPub presence for mkultra.monster.</p><p>VAAK profile: <a href="https://mkultra.monster/users/cmdr_nova" rel="nofollow noopener noreferrer">@cmdr_nova@mkultra.monster</a>. Site bridge handle: <code>@val3r1e@mkultra.monster</code> (Bridgy Fed).</p>';
        $attachment = [
            [
                'type' => 'PropertyValue',
                'name' => 'Also',
                'value' => '<a href="https://mkultra.monster/users/cmdr_nova" rel="me">@cmdr_nova@mkultra.monster</a>',
            ],
            [
                'type' => 'PropertyValue',
                'name' => 'Site',
                'value' => '<a href="https://mkultra.monster/" rel="me">mkultra.monster</a>',
            ],
        ];
    } else {
        $summary = '<p>On mkultra.monster.</p>';
        $attachment = [
            [
                'type' => 'PropertyValue',
                'name' => 'Site',
                'value' => '<a href="https://mkultra.monster/" rel="me">mkultra.monster</a>',
            ],
        ];
    }
    return [
        'actor_key' => $actorKey,
        'name' => $actorKey,
        'summary' => $summary,
        'attachment' => $attachment,
        'icon_url' => null,
        'image_url' => null,
        'manually_approves' => false,
        'discoverable' => true,
        'indexable' => true,
        'collection_consent' => true,
        'vanity_verified' => false,
        'auto_follow_back' => false,
        'anti_ai_marker' => false,
        'auto_unblur_sensitive' => false,
        'auto_delete_posts_7d' => false,
        'updated_at' => null,
    ];
}

function ap_profile_ensure_default(PDO $db): void
{
    $stmt = $db->prepare('SELECT actor_key FROM actor_profile WHERE actor_key = ?');
    $stmt->execute(['cmdr_nova']);
    if ($stmt->fetch()) {
        return;
    }
    $d = ap_profile_defaults('cmdr_nova');
    $ins = $db->prepare(
        'INSERT INTO actor_profile (actor_key, name, summary, attachment_json, icon_url, image_url, manually_approves, discoverable, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)'
    );
    $ins->execute([
        'cmdr_nova',
        $d['name'],
        $d['summary'],
        json_encode($d['attachment'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
        null,
        null,
        0,
        1,
        ap_db_now(),
    ]);
}

function ap_profile_get(string $actorKey = 'cmdr_nova'): array
{
    $stmt = ap_db()->prepare('SELECT * FROM actor_profile WHERE actor_key = ?');
    $stmt->execute([$actorKey]);
    $row = $stmt->fetch();
    $d = ap_profile_defaults($actorKey);
    if (!$row) {
        return $d;
    }
    $atts = json_decode((string) ($row['attachment_json'] ?? '[]'), true);
    if (!is_array($atts)) {
        $atts = $d['attachment'];
    }
    return [
        'actor_key' => (string) $row['actor_key'],
        'name' => ap_fix_utf8((string) $row['name']),
        'summary' => ap_fix_utf8((string) $row['summary']),
        'attachment' => $atts,
        'icon_url' => $row['icon_url'] !== null && $row['icon_url'] !== '' ? (string) $row['icon_url'] : null,
        'image_url' => $row['image_url'] !== null && $row['image_url'] !== '' ? (string) $row['image_url'] : null,
        'manually_approves' => !empty($row['manually_approves']),
        'discoverable' => !empty($row['discoverable']),
        'indexable' => array_key_exists('indexable', $row)
            ? !empty($row['indexable'])
            : true,
        // Default yes if column missing on very old rows mid-migrate
        'collection_consent' => array_key_exists('collection_consent', $row)
            ? !empty($row['collection_consent'])
            : true,
        'vanity_verified' => array_key_exists('vanity_verified', $row)
            ? !empty($row['vanity_verified'])
            : false,
        'auto_follow_back' => array_key_exists('auto_follow_back', $row)
            ? !empty($row['auto_follow_back'])
            : false,
        'anti_ai_marker' => array_key_exists('anti_ai_marker', $row)
            ? !empty($row['anti_ai_marker'])
            : false,
        'auto_unblur_sensitive' => array_key_exists('auto_unblur_sensitive', $row)
            ? !empty($row['auto_unblur_sensitive'])
            : false,
        'auto_delete_posts_7d' => array_key_exists('auto_delete_posts_7d', $row)
            ? !empty($row['auto_delete_posts_7d'])
            : false,
        'updated_at' => $row['updated_at'] ?? null,
    ];
}

/** Display name for clients (optional vanity ✓ when enabled). */
function ap_profile_display_name(string $actorKey = 'cmdr_nova', bool $withVanity = true): string
{
    $p = ap_profile_get($actorKey);
    $name = trim((string) ($p['name'] ?? ''));
    if ($name === '') {
        $name = $actorKey !== '' ? $actorKey : 'cmdr_nova';
    }
    if ($withVanity && !empty($p['vanity_verified'])) {
        // Ice Cubes / Mastodon show this in the name string (no native account badge)
        $name .= ' ✓';
    }
    return $name;
}

/** Whether others may feature @cmdr_nova in Collections / starter packs. */
function ap_profile_collection_consent(string $actorKey = 'cmdr_nova'): bool
{
    $p = ap_profile_get($actorKey);
    return !empty($p['collection_consent']);
}

/**
 * Collapse runaway blank lines in profile bio HTML.
 * Mastodon/HTML treat stacks of &lt;br&gt; as huge gaps; keep at most one blank line
 * (i.e. two &lt;br&gt;) between blocks.
 */
function ap_profile_normalize_summary_html(string $html): string
{
    $html = trim(ap_fix_utf8($html));
    if ($html === '') {
        return '';
    }
    // Unify break tags
    $html = preg_replace('#<br\s*/?>#i', '<br>', $html) ?? $html;
    // </p><br><p> → adjacent paragraphs
    $html = preg_replace('#</p>\s*(?:<br>\s*)+</p>#i', '</p>', $html) ?? $html;
    $html = preg_replace('#</p>\s*(?:<br>\s*)+<p\b#i', '</p><p', $html) ?? $html;
    // 3+ consecutive <br> (with optional whitespace/newlines) → exactly 2 (one visual blank line)
    $html = preg_replace('#(?:<br>\s*){3,}#i', "<br>\n<br>\n", $html) ?? $html;
    // Soften paragraph margins for remotes: don't leave empty <p></p>
    $html = preg_replace('#<p>\s*(?:<br>\s*)*</p>#i', '', $html) ?? $html;
    return trim($html);
}

/**
 * Plain-text bio → HTML with at most one blank line between blocks.
 * Blank lines become paragraph breaks (&lt;p&gt;…&lt;/p&gt;); single newlines → &lt;br&gt;.
 */
function ap_profile_plain_bio_to_html(string $plain): string
{
    $plain = str_replace(["\r\n", "\r"], "\n", ap_fix_utf8($plain));
    // Collapse 3+ newlines to a single paragraph break
    $plain = preg_replace("/\n{3,}/u", "\n\n", $plain) ?? $plain;
    $plain = trim($plain);
    if ($plain === '') {
        return '';
    }
    $parts = preg_split("/\n{2,}/u", $plain);
    if (!is_array($parts) || $parts === []) {
        $parts = [$plain];
    }
    $blocks = [];
    foreach ($parts as $part) {
        $part = trim($part);
        if ($part === '') {
            continue;
        }
        $escaped = htmlspecialchars($part, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $escaped = nl2br($escaped, false);
        $blocks[] = '<p>' . $escaped . '</p>';
    }
    return $blocks !== [] ? implode("\n", $blocks) : '';
}

/**
 * Persist profile fields. Returns ['ok'=>true] or ['ok'=>false,'error'=>...].
 *
 * @param array{name?:string,summary?:string,attachment?:array,icon_url?:?string,image_url?:?string,manually_approves?:bool,discoverable?:bool,indexable?:bool,collection_consent?:bool,vanity_verified?:bool,auto_follow_back?:bool,anti_ai_marker?:bool,auto_delete_posts_7d?:bool} $fields
 */
function ap_profile_save(array $fields, string $actorKey = 'cmdr_nova'): array
{
    $name = trim(ap_fix_utf8((string) ($fields['name'] ?? '')));
    if ($name === '' || mb_strlen($name) > 100) {
        return ['ok' => false, 'error' => 'Display name required (max 100 chars).'];
    }

    $summaryIn = trim(ap_fix_utf8((string) ($fields['summary'] ?? '')));
    if ($summaryIn === '') {
        return ['ok' => false, 'error' => 'Bio / summary required.'];
    }
    if (mb_strlen(strip_tags($summaryIn)) > 2000) {
        return ['ok' => false, 'error' => 'Bio too long (max ~2000 chars of text).'];
    }
    // Allow a small HTML subset; wrap plain text
    if (!str_contains($summaryIn, '<')) {
        $summary = ap_profile_plain_bio_to_html($summaryIn);
    } else {
        $summary = strip_tags($summaryIn, '<p><br><br/><a><code><strong><em><b><i><ul><ol><li>');
        // Force safe link attrs
        $summary = preg_replace_callback(
            '/<a\s+([^>]*?)>/i',
            static function (array $m): string {
                $attrs = $m[1];
                $href = '';
                if (preg_match('/href\s*=\s*([\'"])(https?:\/\/[^\'"]+)\1/i', $attrs, $hm)) {
                    $href = $hm[2];
                }
                if ($href === '' || !str_starts_with($href, 'https://')) {
                    return '<a>';
                }
                return '<a href="' . htmlspecialchars($href, ENT_QUOTES, 'UTF-8') . '" rel="nofollow noopener noreferrer">';
            },
            $summary
        ) ?? $summary;
        $summary = ap_profile_normalize_summary_html($summary);
    }
    if ($summary === '') {
        return ['ok' => false, 'error' => 'Bio / summary required.'];
    }

    $attachment = [];
    $rawAtt = $fields['attachment'] ?? [];
    if (is_array($rawAtt)) {
        foreach (array_slice($rawAtt, 0, 4) as $item) {
            if (!is_array($item)) {
                continue;
            }
            $label = trim(ap_fix_utf8((string) ($item['name'] ?? '')));
            $value = trim(ap_fix_utf8((string) ($item['value'] ?? '')));
            if ($label === '' || $value === '') {
                continue;
            }
            if (mb_strlen($label) > 64 || mb_strlen($value) > 500) {
                continue;
            }
            // Bare domain / path → https URL; wrap links with rel=me (Mastodon outbound)
            $asUrl = ap_profile_coerce_https_url($value);
            if ($asUrl !== null && !str_contains($value, '<')) {
                $value = $asUrl;
            }
            if (preg_match('#^https://[^\s<]+$#', $value)) {
                $safe = htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                $valueHtml = '<a href="' . $safe . '" rel="me">' . $safe . '</a>';
            } elseif (str_contains($value, '<a ')) {
                $valueHtml = strip_tags($value, '<a>');
                $valueHtml = preg_replace_callback(
                    '/<a\s+([^>]*?)>/i',
                    static function (array $m): string {
                        $attrs = $m[1];
                        $href = '';
                        if (preg_match('/href\s*=\s*([\'"])(https?:\/\/[^\'"]+)\1/i', $attrs, $hm)) {
                            $href = $hm[2];
                        }
                        if ($href === '' || !str_starts_with($href, 'https://')) {
                            return '<a>';
                        }
                        return '<a href="' . htmlspecialchars($href, ENT_QUOTES, 'UTF-8') . '" rel="me">';
                    },
                    $valueHtml
                ) ?? htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            } else {
                $valueHtml = htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            }
            $attachment[] = [
                'type' => 'PropertyValue',
                'name' => $label,
                'value' => $valueHtml,
            ];
        }
    }

    // Verify HTTPS profile fields via rel=me backlink (sets verified_at)
    $attachment = ap_profile_verify_attachments($attachment, true);

    $iconUrl = ap_profile_sanitize_https_url($fields['icon_url'] ?? null);
    $imageUrl = ap_profile_sanitize_https_url($fields['image_url'] ?? null);
    if (($fields['icon_url'] ?? '') !== '' && $fields['icon_url'] !== null && $iconUrl === null) {
        return ['ok' => false, 'error' => 'Avatar URL must be https://'];
    }
    if (($fields['image_url'] ?? '') !== '' && $fields['image_url'] !== null && $imageUrl === null) {
        return ['ok' => false, 'error' => 'Header URL must be https://'];
    }

    $manually = !empty($fields['manually_approves']) ? 1 : 0;
    $discoverable = array_key_exists('discoverable', $fields) ? (!empty($fields['discoverable']) ? 1 : 0) : 1;
    $indexable = array_key_exists('indexable', $fields) ? (!empty($fields['indexable']) ? 1 : 0) : 1;
    $collectionConsent = array_key_exists('collection_consent', $fields)
        ? (!empty($fields['collection_consent']) ? 1 : 0)
        : 1;
    $existingProfile = ap_profile_get($actorKey);
    if (array_key_exists('vanity_verified', $fields)) {
        $vanityVerified = !empty($fields['vanity_verified']) ? 1 : 0;
    } else {
        // Preserve when other save paths omit the flag
        $vanityVerified = !empty($existingProfile['vanity_verified']) ? 1 : 0;
    }
    if (array_key_exists('auto_follow_back', $fields)) {
        $autoFollowBack = !empty($fields['auto_follow_back']) ? 1 : 0;
    } else {
        $autoFollowBack = !empty($existingProfile['auto_follow_back']) ? 1 : 0;
    }
    if (array_key_exists('anti_ai_marker', $fields)) {
        $antiAiMarker = !empty($fields['anti_ai_marker']) ? 1 : 0;
    } else {
        $antiAiMarker = !empty($existingProfile['anti_ai_marker']) ? 1 : 0;
    }
    $autoUnblurSensitive = array_key_exists('auto_unblur_sensitive', $fields)
        ? (!empty($fields['auto_unblur_sensitive']) ? 1 : 0)
        : (!empty($existingProfile['auto_unblur_sensitive']) ? 1 : 0);
    $autoDeletePosts7d = array_key_exists('auto_delete_posts_7d', $fields)
        ? (!empty($fields['auto_delete_posts_7d']) ? 1 : 0)
        : (!empty($existingProfile['auto_delete_posts_7d']) ? 1 : 0);

    $stmt = ap_db()->prepare(
        'INSERT INTO actor_profile (actor_key, name, summary, attachment_json, icon_url, image_url, manually_approves, discoverable, indexable, collection_consent, vanity_verified, auto_follow_back, anti_ai_marker, auto_unblur_sensitive, auto_delete_posts_7d, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(actor_key) DO UPDATE SET
           name = excluded.name,
           summary = excluded.summary,
           attachment_json = excluded.attachment_json,
           icon_url = excluded.icon_url,
           image_url = excluded.image_url,
           manually_approves = excluded.manually_approves,
           discoverable = excluded.discoverable,
           indexable = excluded.indexable,
           collection_consent = excluded.collection_consent,
           vanity_verified = excluded.vanity_verified,
           auto_follow_back = excluded.auto_follow_back,
           anti_ai_marker = excluded.anti_ai_marker,
           auto_unblur_sensitive = excluded.auto_unblur_sensitive,
           auto_delete_posts_7d = excluded.auto_delete_posts_7d,
           updated_at = excluded.updated_at'
    );
    $stmt->execute([
        $actorKey,
        $name,
        $summary,
        json_encode($attachment, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
        $iconUrl,
        $imageUrl,
        $manually,
        $discoverable,
        $indexable,
        $collectionConsent,
        $vanityVerified,
        $autoFollowBack,
        $antiAiMarker,
        $autoUnblurSensitive,
        $autoDeletePosts7d,
        ap_db_now(),
    ]);

    // Public JSON snapshot for homepage bake / clients (best-effort).
    ap_profile_export_public_cache($actorKey);

    return ['ok' => true];
}

/** Canonical local profile URL used for rel=me verification. */
function ap_profile_actor_url(string $actorKey = 'cmdr_nova'): string
{
    return 'https://mkultra.monster/users/' . rawurlencode($actorKey);
}

/**
 * Turn a profile field value into an https URL, or null if it isn't link-like.
 * Accepts bare domains (mkultra.monster), paths, HTML anchors, or full https URLs.
 */
function ap_profile_coerce_https_url(string $value): ?string
{
    $raw = trim($value);
    if ($raw === '') {
        return null;
    }
    if (preg_match('/href\s*=\s*([\'"])(https:\/\/[^\'"]+)\1/i', $raw, $hm)) {
        return ap_profile_normalize_verify_url($hm[2]);
    }
    $plain = trim(html_entity_decode(strip_tags($raw), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
    if ($plain === '') {
        return null;
    }
    if (preg_match('#^https://[^\s<>"\']+$#i', $plain)) {
        return ap_profile_normalize_verify_url($plain);
    }
    // Bare domain or domain/path (not @handles, not emails)
    if (str_contains($plain, '@') || str_contains($plain, ' ')) {
        return null;
    }
    if (preg_match('#^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(/[^\s]*)?$#i', $plain)) {
        return ap_profile_normalize_verify_url('https://' . $plain);
    }
    return null;
}

function ap_profile_normalize_verify_url(string $url): string
{
    $url = trim($url);
    $url = rtrim($url, '.,);]!?\'"');
    $parts = parse_url($url);
    if (!is_array($parts) || empty($parts['scheme']) || empty($parts['host'])) {
        return $url;
    }
    $scheme = strtolower((string) $parts['scheme']);
    if ($scheme !== 'https') {
        return $url;
    }
    $host = strtolower((string) $parts['host']);
    $path = (string) ($parts['path'] ?? '');
    $query = isset($parts['query']) && is_string($parts['query']) && $parts['query'] !== ''
        ? '?' . $parts['query']
        : '';
    // Keep trailing slash only for bare origins (Mastodon compares flexibly via our helper)
    return $scheme . '://' . $host . $path . $query;
}

/** Compare profile / rel=me URLs loosely (host case, trailing slash, optional www). */
function ap_profile_urls_match(string $a, string $b): bool
{
    $norm = static function (string $u): string {
        $u = strtolower(trim($u));
        $parts = parse_url($u);
        if (!is_array($parts) || empty($parts['host'])) {
            return rtrim($u, '/');
        }
        $host = (string) $parts['host'];
        if (str_starts_with($host, 'www.')) {
            $host = substr($host, 4);
        }
        $path = (string) ($parts['path'] ?? '');
        if ($path === '' || $path === '/') {
            $path = '';
        } else {
            $path = rtrim($path, '/');
        }
        $query = isset($parts['query']) && is_string($parts['query']) && $parts['query'] !== ''
            ? '?' . $parts['query']
            : '';
        return $host . $path . $query;
    };
    return $norm($a) === $norm($b);
}

/**
 * Does HTML contain an <a> or <link> with rel including "me" pointing at $profileUrl?
 */
function ap_profile_html_has_rel_me(string $html, string $profileUrl): bool
{
    if ($html === '' || $profileUrl === '') {
        return false;
    }
    if (!preg_match_all('/<(a|link)\b([^>]*)>/i', $html, $matches, PREG_SET_ORDER)) {
        return false;
    }
    foreach ($matches as $m) {
        $attrs = $m[2];
        if (!preg_match('/\brel\s*=\s*([\'"])([^\'"]*)\1/i', $attrs, $rm)) {
            continue;
        }
        $rels = preg_split('/\s+/', strtolower(trim($rm[2]))) ?: [];
        if (!in_array('me', $rels, true)) {
            continue;
        }
        if (!preg_match('/\bhref\s*=\s*([\'"])([^\'"]+)\1/i', $attrs, $hm)) {
            continue;
        }
        $href = html_entity_decode(trim($hm[2]), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        if ($href === '') {
            continue;
        }
        // Relative → ignore (must be absolute https for verification)
        if (!str_starts_with(strtolower($href), 'https://')) {
            continue;
        }
        if (ap_profile_urls_match($href, $profileUrl)) {
            return true;
        }
        // Mastodon also accepts rel=me that redirects to the profile URL
        if (ap_profile_url_redirects_to($href, $profileUrl)) {
            return true;
        }
    }
    return false;
}

/** One-hop HTTPS redirect check (Location header). */
function ap_profile_url_redirects_to(string $url, string $target): bool
{
    if (!function_exists('curl_init')) {
        return false;
    }
    if (!function_exists('ap_link_preview_url_allowed')) {
        require_once __DIR__ . '/ap-link-preview.php';
    }
    if (!ap_link_preview_url_allowed($url)) {
        return false;
    }
    $ch = curl_init($url);
    if ($ch === false) {
        return false;
    }
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_HEADER => true,
        CURLOPT_NOBODY => true,
        CURLOPT_FOLLOWLOCATION => false,
        CURLOPT_TIMEOUT => 4,
        CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_USERAGENT => 'mkultra.monster-rel-me-verify/1.0 (+https://mkultra.monster)',
        CURLOPT_PROTOCOLS => CURLPROTO_HTTPS,
        CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTPS,
    ]);
    $raw = (string) curl_exec($ch);
    curl_close($ch);
    if ($raw === '' || !preg_match('/^Location:\s*(\S+)/mi', $raw, $lm)) {
        return false;
    }
    $loc = trim($lm[1]);
    if ($loc === '' || !str_starts_with(strtolower($loc), 'https://')) {
        return false;
    }
    return ap_profile_urls_match($loc, $target);
}

/**
 * Fetch a page and verify it links back to our actor with rel=me.
 * @return string|null ISO8601 verified_at on success
 */
function ap_profile_verify_rel_me_url(string $pageUrl, ?string $profileUrl = null): ?string
{
    $pageUrl = ap_profile_coerce_https_url($pageUrl) ?? '';
    if ($pageUrl === '') {
        return null;
    }
    $profileUrl = $profileUrl ?: ap_profile_actor_url();
    if (!function_exists('ap_link_preview_http_get')) {
        require_once __DIR__ . '/ap-link-preview.php';
    }
    if (!ap_link_preview_url_allowed($pageUrl)) {
        return null;
    }
    $html = ap_link_preview_http_get($pageUrl, 5, 524288);
    if (!is_string($html) || $html === '') {
        return null;
    }
    if (!ap_profile_html_has_rel_me($html, $profileUrl)) {
        return null;
    }
    return gmdate('Y-m-d\TH:i:s.000\Z');
}

/**
 * Verify all HTTPS attachments; sets/clears verified_at on each item.
 *
 * @param list<array<string,mixed>> $attachments
 * @return list<array<string,mixed>>
 */
function ap_profile_verify_attachments(array $attachments, bool $doFetch = true): array
{
    $out = [];
    foreach (array_slice($attachments, 0, 4) as $item) {
        if (!is_array($item)) {
            continue;
        }
        $url = ap_profile_coerce_https_url((string) ($item['value'] ?? ''));
        if ($url === null || !$doFetch) {
            if ($url === null) {
                unset($item['verified_at']);
            }
            $out[] = $item;
            continue;
        }
        $verifiedAt = ap_profile_verify_rel_me_url($url);
        if ($verifiedAt !== null) {
            $item['verified_at'] = $verifiedAt;
        } else {
            unset($item['verified_at']);
        }
        $out[] = $item;
    }
    return $out;
}

/**
 * Re-run rel=me checks and persist verified_at on the stored profile.
 *
 * @return array{ok:bool,verified:int,checked:int,error?:string}
 */
function ap_profile_reverify_fields(string $actorKey = 'cmdr_nova'): array
{
    $p = ap_profile_get($actorKey);
    $atts = is_array($p['attachment'] ?? null) ? $p['attachment'] : [];
    // Normalize bare domains → https <a rel=me> before checking
    $normalized = [];
    $checked = 0;
    foreach (array_slice($atts, 0, 4) as $item) {
        if (!is_array($item)) {
            continue;
        }
        $name = trim((string) ($item['name'] ?? ''));
        $value = (string) ($item['value'] ?? '');
        if ($name === '' || trim(strip_tags($value)) === '') {
            continue;
        }
        $url = ap_profile_coerce_https_url($value);
        if ($url !== null) {
            $checked++;
            $safe = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $value = '<a href="' . $safe . '" rel="me">' . $safe . '</a>';
        }
        $normalized[] = [
            'type' => 'PropertyValue',
            'name' => $name,
            'value' => $value,
        ];
    }
    $verifiedAtts = ap_profile_verify_attachments($normalized, true);
    $verified = 0;
    foreach ($verifiedAtts as $item) {
        if (!empty($item['verified_at'])) {
            $verified++;
        }
    }
    try {
        $st = ap_db()->prepare(
            'UPDATE actor_profile SET attachment_json = ?, updated_at = ? WHERE actor_key = ?'
        );
        $st->execute([
            json_encode($verifiedAtts, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
            ap_db_now(),
            $actorKey,
        ]);
    } catch (Throwable $e) {
        return ['ok' => false, 'verified' => 0, 'checked' => $checked, 'error' => $e->getMessage()];
    }
    ap_profile_export_public_cache($actorKey);
    return ['ok' => true, 'verified' => $verified, 'checked' => $checked];
}

/**
 * Mastodon Account.fields / source.fields from stored profile attachments.
 *
 * @return list<array{name:string,value:string,verified_at:?string}>
 */
function ap_profile_masto_fields(bool $forSource = false, string $actorKey = 'cmdr_nova'): array
{
    $p = ap_profile_get($actorKey);
    $atts = is_array($p['attachment'] ?? null) ? $p['attachment'] : [];
    $out = [];
    foreach (array_slice($atts, 0, 4) as $item) {
        if (!is_array($item)) {
            continue;
        }
        $name = trim((string) ($item['name'] ?? ''));
        $valueRaw = (string) ($item['value'] ?? '');
        if ($name === '' || trim(strip_tags($valueRaw)) === '') {
            continue;
        }
        $url = ap_profile_coerce_https_url($valueRaw);
        $verifiedAt = null;
        if (!empty($item['verified_at']) && is_string($item['verified_at'])) {
            $verifiedAt = $item['verified_at'];
        }
        if ($forSource) {
            $plain = $url ?? trim(html_entity_decode(strip_tags($valueRaw), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
            $out[] = [
                'name' => $name,
                'value' => $plain,
                'verified_at' => $verifiedAt,
            ];
            continue;
        }
        if ($url !== null) {
            $safe = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            // Mastodon-style link with rel=me when verified (clients show the checkmark via verified_at)
            $rel = $verifiedAt !== null
                ? 'me nofollow noopener noreferrer'
                : 'nofollow noopener noreferrer';
            $parts = parse_url($url) ?: [];
            $host = (string) ($parts['host'] ?? $url);
            $path = (string) ($parts['path'] ?? '');
            if ($path === '/') {
                $path = '';
            }
            $query = !empty($parts['query']) ? ('?' . $parts['query']) : '';
            $visible = $host . $path . $query;
            $valueHtml = '<a href="' . $safe . '" rel="' . $rel . '" target="_blank">'
                . '<span class="invisible">https://</span>'
                . '<span class="">' . htmlspecialchars($visible, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</span>'
                . '<span class="invisible"></span>'
                . '</a>';
        } else {
            $valueHtml = $valueRaw;
            if (!str_contains($valueHtml, '<')) {
                $valueHtml = htmlspecialchars($valueHtml, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            }
        }
        $out[] = [
            'name' => $name,
            'value' => $valueHtml,
            'verified_at' => $verifiedAt,
        ];
    }
    return $out;
}

/** Write /assets/data/ap-cmdr-nova.json next to the static site (best-effort). */
function ap_profile_export_public_cache(string $actorKey = 'cmdr_nova'): void
{
    try {
        $p = ap_profile_get($actorKey);
        $payload = [
            'name' => $p['name'],
            'summary' => $p['summary'],
            'icon_url' => $p['icon_url'],
            'image_url' => $p['image_url'],
            'url' => 'https://mkultra.monster/users/' . $actorKey,
            'preferredUsername' => $actorKey,
            'updated_at' => $p['updated_at'] ?? ap_db_now(),
        ];
        $dir = dirname(__DIR__) . '/assets/data';
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        $path = $dir . '/ap-cmdr-nova.json';
        @file_put_contents(
            $path,
            json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT) . "\n"
        );
    } catch (Throwable $e) {
        error_log('[ap-db] profile export: ' . $e->getMessage());
    }
}

/**
 * Convert plain compose text to Mastodon-style HTML.
 * Blank lines become separate &lt;p&gt; blocks; single newlines become &lt;br&gt;.
 * Do NOT insert &lt;br&gt; between &lt;p&gt; tags — Mastodon/Ice Cubes already
 * margin paragraphs, so &lt;/p&gt;&lt;br&gt;&lt;p&gt; renders as a huge gap.
 */
function ap_plain_text_to_html(string $text): string
{
    $text = str_replace(["\r\n", "\r"], "\n", ap_fix_utf8($text));
    $text = trim($text);
    if ($text === '') {
        return '';
    }
    $parts = preg_split("/\n{2,}/", $text);
    if (!is_array($parts) || !$parts) {
        $parts = [$text];
    }
    $html = [];
    foreach ($parts as $part) {
        $part = trim($part);
        if ($part === '') {
            continue;
        }
        $escaped = htmlspecialchars($part, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        // Auto-link bare https URLs (after escape so we only match safe text)
        $escaped = preg_replace_callback(
            '#https://[^\s<>"\']+#u',
            static function (array $m): string {
                $url = rtrim($m[0], '.,);]!?\'"');
                $trail = substr($m[0], strlen($url));
                $href = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                return '<a href="' . $href . '" target="_blank" rel="nofollow noopener noreferrer">' . $href . '</a>' . $trail;
            },
            $escaped
        ) ?? $escaped;
        // Single newlines inside a paragraph
        $escaped = nl2br($escaped, false);
        $html[] = '<p>' . $escaped . '</p>';
    }
    return implode("\n", $html);
}

/**
 * Strip legacy &lt;/p&gt;&lt;br&gt;&lt;p&gt; spacers from stored/federated HTML.
 * Safe to run on already-clean Mastodon-style adjacent paragraphs.
 */
function ap_normalize_status_html(string $html): string
{
    $html = trim($html);
    if ($html === '') {
        return '';
    }
    // </p><br><p>, </p><br/><p>, </p><br>\n<p>, optional whitespace
    $html = preg_replace('#</p>\s*<br\s*/?>\s*<p#i', '</p><p', $html) ?? $html;
    // Double (or more) <br> inside a paragraph → real paragraph break.
    // Legacy compose did nl2br on blank lines → <br><br> which Mastodon shows as huge gaps.
    $html = preg_replace('#<br\s*/?>\s*(?:<br\s*/?>\s*)+#i', '</p><p>', $html) ?? $html;
    // Empty spacer paragraphs some clients emit
    $html = preg_replace('#<p>\s*(?:<br\s*/?>\s*)*</p>#i', '', $html) ?? $html;
    // Clean up accidental nested/empty leftovers after br→p conversion
    $html = preg_replace('#<p>\s*</p>#i', '', $html) ?? $html;
    return trim($html);
}

function ap_profile_sanitize_https_url(mixed $url): ?string
{
    if ($url === null) {
        return null;
    }
    $url = trim((string) $url);
    if ($url === '') {
        return null;
    }
    if (!str_starts_with($url, 'https://') || strlen($url) > 800) {
        return null;
    }
    // Reject credentials-in-URL and control chars
    if (str_contains($url, '@') && preg_match('#^https://[^/]*@#', $url)) {
        return null;
    }
    if (preg_match('/[\x00-\x1f\x7f]/', $url)) {
        return null;
    }
    $parts = parse_url($url);
    if (!is_array($parts) || empty($parts['host'])) {
        return null;
    }
    if (!empty($parts['user']) || !empty($parts['pass'])) {
        return null;
    }
    $host = strtolower((string) $parts['host']);
    if ($host === 'localhost' || $host === '127.0.0.1' || $host === '::1' || $host === '[::1]') {
        return null;
    }
    // Block literal private / link-local / metadata IPs in media/profile URLs
    if (filter_var($host, FILTER_VALIDATE_IP)) {
        if (!filter_var($host, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE)) {
            return null;
        }
    }
    return $url;
}

/**
 * Infer AS2 / HTTP mediaType from a profile image URL path extension.
 */
function ap_profile_media_type_from_url(?string $url): ?string
{
    if ($url === null || $url === '') {
        return null;
    }
    $path = parse_url($url, PHP_URL_PATH);
    if (!is_string($path) || $path === '') {
        return null;
    }
    $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
    return match ($ext) {
        'jpg', 'jpeg' => 'image/jpeg',
        'png' => 'image/png',
        'webp' => 'image/webp',
        'gif' => 'image/gif',
        default => null,
    };
}

/**
 * Absolute filesystem path for admin-uploaded profile media (server-only; rsync-excluded).
 */
function ap_profile_media_dir(): string
{
    return dirname(__DIR__) . '/img/profile';
}

/**
 * Store an admin-uploaded avatar/header under /img/profile/ and return a public https URL.
 * Converts static JPEG/PNG/WebP to WebP via GD when possible; GIF is stored as-is.
 *
 * @param array{name?:string,type?:string,tmp_name?:string,error?:int,size?:int} $file One $_FILES entry
 * @param 'avatar'|'header' $kind
 * @return array{ok:bool,error?:string,url?:string,media_type?:string,path?:string}
 */
function ap_profile_store_uploaded_image(array $file, string $kind): array
{
    $kind = $kind === 'header' ? 'header' : 'avatar';
    $maxBytes = $kind === 'header' ? 5 * 1024 * 1024 : 2 * 1024 * 1024;

    $err = (int) ($file['error'] ?? UPLOAD_ERR_NO_FILE);
    if ($err === UPLOAD_ERR_NO_FILE) {
        return ['ok' => false, 'error' => 'No file uploaded.'];
    }
    if ($err !== UPLOAD_ERR_OK) {
        return ['ok' => false, 'error' => 'Upload failed (PHP error ' . $err . ').'];
    }

    $tmp = (string) ($file['tmp_name'] ?? '');
    $size = (int) ($file['size'] ?? 0);
    if ($tmp === '' || !is_uploaded_file($tmp)) {
        return ['ok' => false, 'error' => 'Invalid upload.'];
    }
    if ($size <= 0 || $size > $maxBytes) {
        $mb = $kind === 'header' ? '5' : '2';
        return ['ok' => false, 'error' => ucfirst($kind) . ' must be between 1 byte and ' . $mb . ' MB.'];
    }

    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime = (string) ($finfo->file($tmp) ?: '');
    $allowed = [
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
        'image/webp' => 'webp',
        'image/gif' => 'gif',
    ];
    if (!isset($allowed[$mime])) {
        return ['ok' => false, 'error' => 'Only JPEG, PNG, WebP, or GIF allowed.'];
    }

    $info = @getimagesize($tmp);
    if (!is_array($info) || empty($info[0]) || empty($info[1])) {
        return ['ok' => false, 'error' => 'File is not a readable image.'];
    }
    $w = (int) $info[0];
    $h = (int) $info[1];
    if ($w < 1 || $h < 1 || $w > 8000 || $h > 8000) {
        return ['ok' => false, 'error' => 'Image dimensions out of range.'];
    }

    $dir = ap_profile_media_dir();
    if (!is_dir($dir) && !@mkdir($dir, 0775, true)) {
        return ['ok' => false, 'error' => 'Profile media directory missing.'];
    }
    if (!is_writable($dir)) {
        return ['ok' => false, 'error' => 'Profile media directory not writable.'];
    }

    $stamp = gmdate('YmdHis');
    $rand = bin2hex(random_bytes(4));
    $outName = null;
    $outMime = $mime;
    $outPath = null;

    // Convert static raster to WebP when GD supports it (skip GIF to preserve animation).
    $canWebp = function_exists('imagewebp') && $mime !== 'image/gif';
    if ($canWebp) {
        $im = null;
        if ($mime === 'image/jpeg' && function_exists('imagecreatefromjpeg')) {
            $im = @imagecreatefromjpeg($tmp);
        } elseif ($mime === 'image/png' && function_exists('imagecreatefrompng')) {
            $im = @imagecreatefrompng($tmp);
        } elseif ($mime === 'image/webp' && function_exists('imagecreatefromwebp')) {
            $im = @imagecreatefromwebp($tmp);
        }
        if ($im instanceof GdImage) {
            if (function_exists('imagepalettetotruecolor')) {
                @imagepalettetotruecolor($im);
            }
            if (function_exists('imagealphablending') && function_exists('imagesavealpha')) {
                @imagealphablending($im, true);
                @imagesavealpha($im, true);
            }
            $outName = $kind . '-' . $stamp . '-' . $rand . '.webp';
            $outPath = $dir . '/' . $outName;
            $ok = @imagewebp($im, $outPath, 85);
            imagedestroy($im);
            if (!$ok || !is_file($outPath)) {
                @unlink($outPath);
                $outPath = null;
                $outName = null;
            } else {
                $outMime = 'image/webp';
                @chmod($outPath, 0644);
            }
        }
    }

    if ($outPath === null) {
        $ext = $allowed[$mime];
        $outName = $kind . '-' . $stamp . '-' . $rand . '.' . $ext;
        $outPath = $dir . '/' . $outName;
        if (!@move_uploaded_file($tmp, $outPath)) {
            return ['ok' => false, 'error' => 'Could not store uploaded file.'];
        }
        @chmod($outPath, 0644);
    } else {
        @unlink($tmp);
    }

    ap_profile_prune_media_files($kind, 3);

    $url = 'https://mkultra.monster/img/profile/' . $outName;
    return [
        'ok' => true,
        'url' => $url,
        'media_type' => $outMime,
        'path' => $outPath,
    ];
}

/**
 * Keep the newest $keep files per kind under img/profile/; delete older ones.
 */
function ap_profile_prune_media_files(string $kind, int $keep = 3): void
{
    $kind = $kind === 'header' ? 'header' : 'avatar';
    $keep = max(1, min(10, $keep));
    $dir = ap_profile_media_dir();
    if (!is_dir($dir)) {
        return;
    }
    $files = glob($dir . '/' . $kind . '-*') ?: [];
    $files = array_values(array_filter($files, 'is_file'));
    if (count($files) <= $keep) {
        return;
    }
    usort($files, static function (string $a, string $b): int {
        return (filemtime($b) ?: 0) <=> (filemtime($a) ?: 0);
    });
    foreach (array_slice($files, $keep) as $old) {
        @unlink($old);
    }
}

/**
 * Profile metadata fields for the AS2 Person actor.
 *
 * Privacy / Code of Conduct / Contact stay on the HTML profile footer and
 * instance API — they must NOT be PropertyValue attachments (Mastodon shows
 * those as profile fields and they crowded out personal metadata).
 *
 * @param list<array<string,mixed>> $attachments
 * @return list<array<string,mixed>>
 */
function ap_cmdr_actor_attachments_with_policies(array $attachments): array
{
    $blocked = [
        'privacy policy' => true,
        'disclaimer' => true,
        'contact' => true,
        'terms of service' => true,
        'code of conduct' => true,
        'privacy' => true,
    ];
    $out = [];
    foreach ($attachments as $item) {
        if (!is_array($item)) {
            continue;
        }
        $n = strtolower(trim((string) ($item['name'] ?? '')));
        if ($n !== '' && isset($blocked[$n])) {
            continue;
        }
        // Federate only AS2 PropertyValue fields (verified_at is local Mastodon cache)
        $out[] = [
            'type' => 'PropertyValue',
            'name' => (string) ($item['name'] ?? ''),
            'value' => (string) ($item['value'] ?? ''),
        ];
    }
    return array_values($out);
}

/**
 * Plain text for ActivityPub actor/note fields.
 * Keeps supplementary-plane characters (e.g. 𐕣 in the display name) so Mastodon /
 * Wafrn / etc. can render them. Only strips C0/C1 controls.
 *
 * Note: we used to drop non-BMP for Threads/Meta 500s; as of 2026-08 we federate
 * the real name — Meta may still be unhappy, but the wider fedi should show it.
 */
function ap_as2_federation_plaintext(string $text): string
{
    $text = ap_fix_utf8($text);
    $text = preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/u', '', $text) ?? $text;
    $text = trim(preg_replace('/\s+/u', ' ', $text) ?? $text);
    return $text;
}

/**
 * AS2 Person document for any local actor_key (profile + public PEM).
 */
function ap_actor_as2_document(string $actorKey, string $publicKeyPem, bool $rich = true): array
{
    $actorKey = strtolower(trim($actorKey));
    $p = ap_profile_get($actorKey);
    $id = 'https://mkultra.monster/users/' . rawurlencode($actorKey);
    $displayName = ap_as2_federation_plaintext((string) ($p['name'] ?? ''));
    if ($displayName === '') {
        $displayName = $actorKey;
    }
    $ctxExtra = [
        'discoverable' => 'https://joinmastodon.org/ns#discoverable',
        'featured' => [
            '@id' => 'http://joinmastodon.org/ns#featured',
            '@type' => '@id',
        ],
    ];
    if ($rich) {
        $ctxExtra['featuredCollections'] = [
            '@id' => 'https://w3id.org/fep/7aa9#featuredCollections',
            '@type' => '@id',
        ];
        $ctxExtra['FeaturedCollection'] = 'https://w3id.org/fep/7aa9#FeaturedCollection';
        $ctxExtra['canFeature'] = 'https://w3id.org/fep/7aa9#canFeature';
    }
    $actor = [
        '@context' => [
            'https://www.w3.org/ns/activitystreams',
            'https://w3id.org/security/v1',
            'https://gotosocial.org/ns',
            $ctxExtra,
        ],
        'id' => $id,
        'type' => 'Person',
        'preferredUsername' => $actorKey,
        'name' => $displayName,
        'summary' => $p['summary'] !== '' ? $p['summary'] : ('<p>@' . $actorKey . '@mkultra.monster</p>'),
        'url' => $id,
        'inbox' => $id . '/inbox',
        'outbox' => $id . '/outbox',
        'followers' => $id . '/followers',
        'following' => $id . '/following',
        'endpoints' => [
            'sharedInbox' => 'https://mkultra.monster/inbox',
        ],
        'manuallyApprovesFollowers' => (bool) $p['manually_approves'],
        'discoverable' => (bool) $p['discoverable'],
        'indexable' => !empty($p['indexable']),
        'interactionPolicy' => [
            'canFeature' => !empty($p['collection_consent'])
                ? [
                    'automaticApproval' => ['https://www.w3.org/ns/activitystreams#Public'],
                    'manualApproval' => [],
                ]
                : [
                    'automaticApproval' => [$id],
                    'manualApproval' => [],
                ],
        ],
        'published' => '2018-01-01T00:00:00Z',
        'attachment' => ap_cmdr_actor_attachments_with_policies(
            is_array($p['attachment'] ?? null) ? $p['attachment'] : []
        ),
        'publicKey' => [
            'id' => $id . '#main-key',
            'owner' => $id,
            'publicKeyPem' => $publicKeyPem,
        ],
    ];
    if ($rich) {
        $actor['featured'] = $id . '/collections/featured';
        $actor['featuredCollections'] = $id . '/featuredCollections';
    } else {
        $actor['featured'] = $id . '/collections/featured';
    }
    $updatedRaw = (string) ($p['updated_at'] ?? '');
    try {
        $actor['updated'] = $updatedRaw !== ''
            ? (new DateTimeImmutable($updatedRaw))->format('Y-m-d\TH:i:s\Z')
            : gmdate('Y-m-d\TH:i:s\Z');
    } catch (Throwable $e) {
        $actor['updated'] = gmdate('Y-m-d\TH:i:s\Z');
    }
    $iconUrl = function_exists('ap_local_avatar_url')
        ? ap_local_avatar_url($p['icon_url'] ?? null)
        : (string) ($p['icon_url'] ?? '');
    if ($iconUrl !== '') {
        $icon = [
            'type' => 'Image',
            'url' => $iconUrl,
        ];
        $mt = ap_profile_media_type_from_url($iconUrl);
        if ($mt !== null) {
            $icon['mediaType'] = $mt;
        } else {
            $icon['mediaType'] = 'image/webp';
        }
        $actor['icon'] = $icon;
    }
    if (!empty($p['image_url'])) {
        $image = [
            'type' => 'Image',
            'url' => $p['image_url'],
        ];
        $mt = ap_profile_media_type_from_url((string) $p['image_url']);
        if ($mt !== null) {
            $image['mediaType'] = $mt;
        }
        $actor['image'] = $image;
    }
    // Aliases / Move helpers live in ap-import-export.php (not always loaded by every front controller).
    if (!function_exists('ap_alias_also_known_as_urls')) {
        $ie = __DIR__ . '/ap-import-export.php';
        if (is_file($ie)) {
            require_once $ie;
        }
    }
    if (function_exists('ap_alias_also_known_as_urls')) {
        $aka = ap_alias_also_known_as_urls($actorKey);
        if ($aka !== []) {
            $actor['alsoKnownAs'] = array_values($aka);
        }
    }
    $movedTo = function_exists('ap_move_active_target') ? ap_move_active_target($actorKey) : null;
    if (is_string($movedTo) && $movedTo !== '') {
        $actor['movedTo'] = $movedTo;
    } else {
        unset($actor['movedTo']);
    }
    return $actor;
}

function ap_cmdr_actor_document(string $publicKeyPem): array
{
    return ap_actor_as2_document('cmdr_nova', $publicKeyPem, true);
}

/**
 * Shared inboxes for hosts we've already seen federating with us.
 * Used to push profile Updates (e.g. clear stale movedTo caches) beyond local followers.
 *
 * @return list<string>
 */
function ap_known_shared_inboxes(int $limit = 40): array
{
    $limit = max(1, min(80, $limit));
    $rows = ap_db()->query(
        'SELECT host, COUNT(*) AS c FROM events WHERE host IS NOT NULL AND host != \'\' GROUP BY host ORDER BY c DESC LIMIT 80'
    )->fetchAll();
    $inboxes = [];
    foreach ($rows as $row) {
        $host = strtolower((string) ($row['host'] ?? ''));
        if ($host === '' || $host === 'mkultra.monster') {
            continue;
        }
        // Skip obviously non-AP / broken /inbox guesses
        // app.wafrn.net /inbox returns 405; real inboxes are on the blog host
        // Bridgy Fed: https://bsky.brid.gy/inbox 404s — real shared inbox is /ap/sharedInbox
        if ($host === 'lemmy.ml' || $host === 'app.wafrn.net') {
            continue;
        }
        if (str_ends_with($host, 'brid.gy') || $host === 'brid.gy') {
            if ($host === 'bsky.brid.gy' || $host === 'ap.brid.gy' || $host === 'web.brid.gy' || $host === 'fed.brid.gy') {
                $inboxes['https://' . $host . '/ap/sharedInbox'] = true;
            }
            continue;
        }
        // Threads: https://threads.net/inbox → 301 to www; real sharedInbox is /ap/inbox/
        if ($host === 'threads.net' || $host === 'www.threads.net') {
            $inboxes['https://threads.net/ap/inbox/'] = true;
            continue;
        }
        // Relays often 405 POST /inbox from random Creates
        if ($host === 'relay.fedi.buzz') {
            continue;
        }
        $url = 'https://' . $host . '/inbox';
        $inboxes[$url] = true;
        if (count($inboxes) >= $limit) {
            break;
        }
    }
    return array_keys($inboxes);
}

/**
 * Pull https image/video URLs from an AS2 object for timeline preview — never downloads.
 * Accepts Image, Document, Video (Mastodon gifv is Document + video/mp4).
 *
 * @return list<string>
 */
function ap_extract_media_urls(mixed $object): array
{
    if (!is_array($object)) {
        return [];
    }
    $urls = [];
    $add = static function (?string $url) use (&$urls): void {
        if ($url === null || $url === '' || count($urls) >= 4) {
            return;
        }
        $clean = ap_profile_sanitize_https_url($url);
        if ($clean === null) {
            return;
        }
        if (!in_array($clean, $urls, true)) {
            $urls[] = $clean;
        }
    };
    /** Prefer original / full media over tiny preview Links when url is a list. */
    $hrefFrom = static function (mixed $node): ?string {
        if (is_string($node)) {
            return $node;
        }
        if (!is_array($node)) {
            return null;
        }
        if (isset($node['href']) && is_string($node['href'])) {
            return $node['href'];
        }
        if (!isset($node['url'])) {
            return null;
        }
        if (is_string($node['url'])) {
            return $node['url'];
        }
        if (!is_array($node['url'])) {
            return null;
        }
        // single Link
        if (isset($node['url']['href']) && is_string($node['url']['href'])) {
            return $node['url']['href'];
        }
        $candidates = [];
        foreach ($node['url'] as $u) {
            if (is_string($u) && str_starts_with($u, 'https://')) {
                $candidates[] = ['href' => $u, 'mediaType' => '', 'name' => ''];
                continue;
            }
            if (!is_array($u) || empty($u['href']) || !is_string($u['href'])) {
                continue;
            }
            $candidates[] = [
                'href' => $u['href'],
                'mediaType' => strtolower((string) ($u['mediaType'] ?? '')),
                'name' => strtolower((string) ($u['name'] ?? '')),
            ];
        }
        if ($candidates === []) {
            return null;
        }
        $score = static function (array $c): int {
            $s = 0;
            $mt = $c['mediaType'];
            $href = $c['href'];
            $name = $c['name'];
            if (str_contains($name, 'original') || str_contains($href, '/original/')) {
                $s += 50;
            }
            if (str_contains($name, 'small') || str_contains($href, '/small/') || str_contains($href, 'preview')) {
                $s -= 30;
            }
            if (str_starts_with($mt, 'video/')) {
                $s += 20; // gifv / video
            }
            if (str_starts_with($mt, 'image/gif') || preg_match('/\.gif(\?|#|$)/i', $href)) {
                $s += 25;
            }
            if (str_starts_with($mt, 'image/')) {
                $s += 10;
            }
            if (preg_match('/\.(mp4|webm|mov|m4v)(\?|#|$)/i', $href)) {
                $s += 15;
            }
            return $s;
        };
        usort($candidates, static fn(array $a, array $b): int => $score($b) <=> $score($a));
        return $candidates[0]['href'];
    };
    $looksMedia = static function (array $item, ?string $url): bool {
        $type = (string) ($item['type'] ?? '');
        $mt = strtolower((string) ($item['mediaType'] ?? ''));
        // Mastodon: Image; gifv/video often Document + video/mp4; some remotes use Video
        if (in_array($type, ['Image', 'Document', 'Video'], true)) {
            // Document without usable mediaType/url still OK if we have https url below
            if ($type === 'Document' && $mt !== '' && !str_starts_with($mt, 'image/') && !str_starts_with($mt, 'video/')) {
                // e.g. application/pdf — skip
                if (!is_string($url) || !preg_match('/\.(jpe?g|png|gif|webp|avif|mp4|webm|mov|m4v)(\?|#|$)/i', $url)) {
                    return false;
                }
            }
            return true;
        }
        if ($mt !== '' && (str_starts_with($mt, 'image/') || str_starts_with($mt, 'video/'))) {
            return true;
        }
        if (is_string($url) && preg_match('/\.(jpe?g|png|gif|webp|avif|mp4|webm|mov|m4v)(\?|#|$)/i', $url)) {
            return true;
        }
        return false;
    };
    $consider = static function (mixed $item) use ($add, $hrefFrom, $looksMedia): void {
        if (!is_array($item)) {
            return;
        }
        $url = $hrefFrom($item);
        if ($looksMedia($item, $url)) {
            $add($url);
        }
    };

    if (isset($object['attachment'])) {
        $atts = $object['attachment'];
        if (is_array($atts) && (isset($atts['type']) || isset($atts['url']) || isset($atts['href']))) {
            $atts = [$atts];
        }
        if (is_array($atts)) {
            foreach ($atts as $a) {
                $consider($a);
            }
        }
    }
    if (isset($object['image'])) {
        $imgs = $object['image'];
        if (is_array($imgs) && (isset($imgs['type']) || isset($imgs['url']))) {
            $imgs = [$imgs];
        }
        if (is_array($imgs)) {
            foreach ($imgs as $img) {
                if (is_array($img) && !isset($img['type'])) {
                    $img['type'] = 'Image';
                }
                $consider($img);
            }
        }
    }
    if (in_array((string) ($object['type'] ?? ''), ['Image', 'Video', 'Document'], true)) {
        $consider($object);
    }

    return $urls;
}


function ap_fix_utf8(?string $s): string
{
    if ($s === null || $s === '') {
        return '';
    }
    if (!mb_check_encoding($s, 'UTF-8')) {
        $conv = @mb_convert_encoding($s, 'UTF-8', 'UTF-8, Windows-1252, ISO-8859-1');
        if (is_string($conv)) {
            $s = $conv;
        }
    }
    // Repair UTF-8 bytes that were mis-decoded as Latin-1 then re-encoded (werenâ€™t)
    if (preg_match('/â.|Ã.|Â.|ðŸ/u', $s)) {
        $try = @mb_convert_encoding($s, 'ISO-8859-1', 'UTF-8');
        if (is_string($try) && $try !== '' && mb_check_encoding($try, 'UTF-8') && !preg_match('/â.|Ã./u', $try)) {
            $s = $try;
        } else {
            // Explicit common curly/smart punctuation mojibake
            $s = str_replace(
                ["\xC3\xA2\xE2\x82\xAC\xE2\x84\xA2", "â€™", "â€˜", "â€œ", "â€", "â€”", "â€“", "â€¦", "Â"],
                ["\xE2\x80\x99", "\xE2\x80\x99", "\xE2\x80\x98", "\xE2\x80\x9C", "\xE2\x80\x9D", "\xE2\x80\x94", "\xE2\x80\x93", "\xE2\x80\xA6", ""],
                $s
            );
        }
    }
    return $s;
}

/**
 * Convert ActivityPub / Mastodon HTML content to plain text without gluing
 * adjacent blocks (e.g. mention paragraph + body paragraph → "@userHello").
 */
/**
 * Turn a mention href (https://host/@user or /users/user) into user@host.
 */
function ap_acct_from_actor_href(string $href, ?string $fallbackUser = null): ?string
{
    $href = trim($href);
    if ($href === '' || !str_starts_with($href, 'https://')) {
        return null;
    }
    $host = strtolower((string) (parse_url($href, PHP_URL_HOST) ?: ''));
    if ($host === '') {
        return null;
    }
    $user = null;
    $path = (string) (parse_url($href, PHP_URL_PATH) ?? '');
    if (preg_match('#/@([^/]+)/?$#u', $path, $m) || preg_match('#/users/([^/]+)/?$#u', $path, $m)) {
        $user = rawurldecode($m[1]);
    } elseif (is_string($fallbackUser) && $fallbackUser !== '') {
        $user = ltrim($fallbackUser, '@');
        // Keep Bluesky-style handles intact (alice.bsky.social / custom.domain)
        // — do not truncate at the first '@' only when it's already user@host.
        if (substr_count($user, '@') === 1 && preg_match('/^[^@]+@[^@]+\.[^@]+$/', $user)) {
            // already a full acct — handled below
        } elseif (str_contains($user, '@')) {
            $user = explode('@', $user, 2)[0];
        }
    }
    if ($user === null || $user === '') {
        return null;
    }
    $user = ltrim($user, '@');
    if ($user === '') {
        return null;
    }
    // Bridgy Fed Bluesky: preferredUsername / mention label is already a handle
    // with dots (alice.bsky.social). Appending @bsky.brid.gy makes
    // @alice.bsky.social@bsky.brid.gy which breaks VAAK/Ice Cubes linkify.
    $isBridgy = $host === 'brid.gy' || str_ends_with($host, '.brid.gy');
    if ($isBridgy && str_contains($user, '.') && !str_starts_with(strtolower($user), 'did:')) {
        return $user;
    }
    return $user . '@' . $host;
}

/**
 * Normalize mangled Bridgy plain-text mentions for display/linkify.
 * "@alice.bsky.social@bsky.brid.gy" → "@alice.bsky.social"
 */
function ap_normalize_bridgy_plain_mentions(string $plain): string
{
    return preg_replace(
        '/@([A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,})@bsky\.brid\.gy\b/u',
        '@$1',
        $plain
    ) ?? $plain;
}

function ap_html_to_plain_text(string $html): string
{
    $html = ap_fix_utf8($html);
    if ($html === '') {
        return '';
    }
    // If it doesn't look like HTML, still normalize mention glue below
    if (str_contains($html, '<')) {
        // Expand mention <a href>…</a> to @user@host BEFORE strip_tags so we don't
        // lose the instance (Mastodon often shows only @user in the link text).
        $html = preg_replace_callback(
            '#<a\b([^>]*)>(.*?)</a>#isu',
            static function (array $m): string {
                $attrs = $m[1];
                $innerHtml = $m[2];
                $inner = trim(html_entity_decode(strip_tags($innerHtml), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
                if (!preg_match('/\bhref\s*=\s*["\']([^"\']+)["\']/i', $attrs, $hm)) {
                    return $inner !== '' ? $inner : '';
                }
                $href = html_entity_decode($hm[1], ENT_QUOTES | ENT_HTML5, 'UTF-8');
                $class = '';
                if (preg_match('/\bclass\s*=\s*["\']([^"\']*)["\']/i', $attrs, $cm)) {
                    $class = strtolower($cm[1]);
                }
                $rel = '';
                if (preg_match('/\brel\s*=\s*["\']([^"\']*)["\']/i', $attrs, $rm)) {
                    $rel = strtolower($rm[1]);
                }
                $path = strtolower((string) (parse_url($href, PHP_URL_PATH) ?: ''));
                // Hashtags often use class="mention hashtag" (Mastodon) — never rewrite those as @user@host
                $looksHashtag = str_contains($class, 'hashtag')
                    || str_contains($rel, 'tag')
                    || str_contains($path, '/tags/')
                    || str_starts_with($inner, '#');
                if ($looksHashtag) {
                    // Prefer a clean #tag label
                    if (preg_match('/#([\p{L}\p{N}_]+)/u', $inner, $tm)) {
                        return '#' . $tm[1];
                    }
                    return $inner !== '' ? $inner : $href;
                }
                $looksMention = str_contains($class, 'mention')
                    || str_starts_with($inner, '@')
                    || str_contains($class, 'u-url');
                if ($looksMention && str_starts_with($href, 'https://')) {
                    // Already a full acct in the visible text
                    if (preg_match('/^@[\w.-]+@[\w.-]+\.[\w.-]+$/u', $inner)) {
                        return $inner;
                    }
                    // Bridgy often labels mentions as @alice.bsky.social (already a handle)
                    if (preg_match('/^@[A-Za-z0-9][A-Za-z0-9.-]*\.[A-Za-z]{2,}$/u', $inner)
                        && function_exists('ap_is_bridgy_url') && ap_is_bridgy_url($href)) {
                        return $inner;
                    }
                    $fallbackUser = str_starts_with($inner, '@') ? substr($inner, 1) : $inner;
                    // Never use a hashtag-looking label as a username
                    if ($fallbackUser !== '' && str_starts_with($fallbackUser, '#')) {
                        $fallbackUser = null;
                    }
                    $acct = ap_acct_from_actor_href($href, $fallbackUser !== '' ? $fallbackUser : null);
                    if ($acct !== null && !str_starts_with($acct, '#')) {
                        return '@' . $acct;
                    }
                }
                // Non-mention links: keep visible label (URLs linkified later in UI)
                return $inner !== '' ? $inner : $href;
            },
            $html
        ) ?? $html;
        // Bridgy quote-inline: keep a break before RE: so commentary doesn't glue
        // ("that's my mutualRE: https://…")
        $html = preg_replace(
            '#<span\b[^>]*class="[^"]*\bquote-inline\b[^"]*"[^>]*>#i',
            "\n\n",
            $html
        ) ?? $html;
        // Block / break tags → newlines so strip_tags won't fuse "@user" + "Hello"
        $html = preg_replace('#<\s*br\s*/?\s*>#i', "\n", $html) ?? $html;
        // Paragraph / block end → blank line (one visual gap in pre-wrap timelines)
        $html = preg_replace('#<\s*/\s*(p|div|li|tr|h[1-6]|blockquote)\s*>#i', "\n\n", $html) ?? $html;
        $html = preg_replace('#<\s*(p|div|li|h[1-6]|blockquote)\b[^>]*>#i', '', $html) ?? $html;
        // Closing a mention link before more text: keep a word boundary
        $html = preg_replace('#</a>(\s*)(?=[A-Za-z0-9])#i', '</a> ', $html) ?? $html;
        $html = html_entity_decode(strip_tags($html), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    } else {
        $html = html_entity_decode($html, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    }
    // Collapse horizontal whitespace; keep a single blank line between paragraphs
    $html = preg_replace("/[ \t]+/u", ' ', $html) ?? $html;
    $html = preg_replace("/\n{3,}/u", "\n\n", $html) ?? $html;
    $html = trim($html);
    // Repair already-glued @user@hostWord / @UserWord (common in older rows)
    $html = ap_plain_unglue_mentions($html);
    // Repair "@#tag@host" if a hashtag link was ever mistaken for a mention
    if (function_exists('ap_masto_repair_at_hash_tags')) {
        $html = ap_masto_repair_at_hash_tags($html);
    } elseif (str_contains($html, '@#')) {
        $html = preg_replace('/@#([\p{L}\p{N}_]+)@(?:[a-z0-9.-]+\.[a-z]{2,})/iu', '#$1', $html) ?? $html;
        $html = preg_replace('/@#([\p{L}\p{N}_]+)/u', '#$1', $html) ?? $html;
    }
    return $html;
}

/**
 * Insert a space when an @mention runs directly into the next word
 * ("@ElizafoxIf" → "@Elizafox If", "@user@hostYes" → "@user@host Yes").
 * Avoids splitting camelCase handles like @CactuarJoe.
 *
 * @param list<string> $knownUsernames Extra bare usernames to unglue (e.g. reply parent)
 */
function ap_plain_unglue_mentions(string $text, array $knownUsernames = []): string
{
    if ($text === '') {
        return $text;
    }
    // @user@host glued to the NEXT word ("@alice@example.comHello").
    // Only split when the following char is uppercase or a digit — never when it is
    // more lowercase letters (that just truncates real TLDs: exchange → exchang e).
    $text = preg_replace(
        '/(^|[^\w@])(@[\w]+@(?:[a-z0-9-]+\.)+[a-z]{2,})(?=[\p{Lu}\p{N}])/u',
        '$1$2 ',
        $text
    ) ?? $text;

    // Known bare usernames first (longest first). Same rule: only unglue camelCase / digit tails.
    $known = [];
    foreach ($knownUsernames as $user) {
        $user = trim((string) $user);
        if ($user !== '' && preg_match('/^[\w]+$/u', $user)) {
            $known[strtolower($user)] = $user;
        }
    }
    uksort($known, static fn ($a, $b) => strlen($b) <=> strlen($a));
    foreach ($known as $user) {
        $text = preg_replace(
            '/(^|[^\w@])@(' . preg_quote($user, '/') . ')(?=[\p{Lu}\p{N}])/u',
            '$1@$2 ',
            $text
        ) ?? $text;
    }

    return $text;
}

function ap_db_now(): string
{
    return gmdate('c');
}

function ap_metrics_record(
    string $type,
    ?string $actorId,
    ?string $objectId,
    ?string $targetActor,
    int $bytes,
    string $actionTaken,
    ?string $summary = null,
    ?array $mediaUrls = null,
    ?string $createdAt = null,
    ?string $inReplyTo = null,
    string $spoilerText = '',
    bool $sensitive = false,
    string $visibility = 'public'
): void {
    try {
        $host = null;
        if ($actorId) {
            $h = parse_url($actorId, PHP_URL_HOST);
            $host = is_string($h) ? strtolower($h) : null;
        }
        // Keep more text for the admin federation feed (was 500 — cut off long posts)
        if ($summary !== null) {
            // Preserve spaces/newlines between mention blocks and body (</p><p> glue fix)
            $summary = ap_html_to_plain_text($summary);
            $summary = mb_substr($summary, 0, 4000);
            if ($summary === '') {
                $summary = null;
            }
        }
        $spoilerText = mb_substr(trim(ap_fix_utf8($spoilerText)), 0, 500);
        if ($spoilerText !== '') {
            $sensitive = true;
        }
        $visibility = ap_normalize_visibility($visibility);
        $mediaJson = null;
        if (is_array($mediaUrls) && $mediaUrls) {
            $clean = [];
            foreach ($mediaUrls as $u) {
                $s = ap_profile_sanitize_https_url($u);
                if ($s !== null) {
                    $clean[] = $s;
                }
                if (count($clean) >= 4) {
                    break;
                }
            }
            if ($clean) {
                $mediaJson = json_encode($clean, JSON_UNESCAPED_SLASHES);
            }
        }
        $replyTo = null;
        if (is_string($inReplyTo)) {
            $inReplyTo = trim($inReplyTo);
            if (str_starts_with($inReplyTo, 'https://') && strlen($inReplyTo) <= 800) {
                $replyTo = rtrim($inReplyTo, '/');
            }
        }
        // Idempotent firehose: shared-inbox retries / multi-relay fan-in otherwise
        // duplicate the same Create and Ice Cubes shows it twice.
        if (
            $objectId
            && in_array($type, ['Create', 'Announce', 'Update'], true)
            && in_array($actionTaken, ['log', 'local_observe'], true)
        ) {
            $dup = ap_db()->prepare(
                'SELECT id, spoiler_text, sensitive, visibility FROM events WHERE type = ? AND object_id = ? LIMIT 1'
            );
            $dup->execute([$type, $objectId]);
            $existing = $dup->fetch();
            if ($existing) {
                // Backfill reply pointer / CW / visibility if we learned them later
                if ($replyTo !== null) {
                    ap_db()->prepare(
                        'UPDATE events SET in_reply_to = COALESCE(NULLIF(in_reply_to, \'\'), ?) WHERE id = ?'
                    )->execute([$replyTo, (int) $existing['id']]);
                }
                if ($spoilerText !== '' && trim((string) ($existing['spoiler_text'] ?? '')) === '') {
                    ap_db()->prepare(
                        'UPDATE events SET spoiler_text = ?, sensitive = 1 WHERE id = ?'
                    )->execute([$spoilerText, (int) $existing['id']]);
                } elseif ($sensitive && empty($existing['sensitive'])) {
                    ap_db()->prepare('UPDATE events SET sensitive = 1 WHERE id = ?')
                        ->execute([(int) $existing['id']]);
                }
                $oldVis = ap_normalize_visibility($existing['visibility'] ?? 'public');
                // Prefer more restrictive label when we learn it (public → unlisted/private)
                if ($visibility !== 'public' && $oldVis === 'public') {
                    try {
                        ap_db()->prepare('UPDATE events SET visibility = ? WHERE id = ?')
                            ->execute([$visibility, (int) $existing['id']]);
                    } catch (Throwable $e) {
                        // column may be mid-migrate
                    }
                }
                return;
            }
        }
        $when = ap_db_now();
        if ($createdAt !== null && $createdAt !== '') {
            try {
                $when = (new DateTimeImmutable($createdAt))->format('c');
            } catch (Throwable $e) {
                // keep now
            }
        }
        $insertedId = 0;
        try {
            $stmt = ap_db()->prepare(
                'INSERT INTO events (created_at, type, actor_id, object_id, target_actor, host, bytes, action_taken, summary, media_urls, in_reply_to, spoiler_text, sensitive, visibility)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            );
            $stmt->execute([
                $when,
                $type,
                $actorId,
                $objectId,
                $targetActor,
                $host,
                $bytes,
                $actionTaken,
                $summary,
                $mediaJson,
                $replyTo,
                $spoilerText,
                $sensitive ? 1 : 0,
                $visibility,
            ]);
            $insertedId = ap_db_last_insert_id('events');
        } catch (Throwable $e) {
            // Fallback if visibility column not migrated yet
            $stmt = ap_db()->prepare(
                'INSERT INTO events (created_at, type, actor_id, object_id, target_actor, host, bytes, action_taken, summary, media_urls, in_reply_to, spoiler_text, sensitive)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            );
            $stmt->execute([
                $when,
                $type,
                $actorId,
                $objectId,
                $targetActor,
                $host,
                $bytes,
                $actionTaken,
                $summary,
                $mediaJson,
                $replyTo,
                $spoilerText,
                $sensitive ? 1 : 0,
            ]);
            $insertedId = ap_db_last_insert_id('events');
        }
        if ($insertedId > 0 && function_exists('ap_search_fts_index_event_row')) {
            ap_search_fts_index_event_row([
                'id' => $insertedId,
                'type' => $type,
                'action_taken' => $actionTaken,
                'summary' => $summary,
                'spoiler_text' => $spoilerText,
                'object_id' => $objectId,
                'created_at' => $when,
            ]);
        }
    } catch (Throwable $e) {
        error_log('[ap-db] metrics_record: ' . $e->getMessage());
    }
}

/**
 * Hide firehose Create/Announce/Update/Quote rows for a deleted object.
 * Timelines only show action_taken IN (log, local_observe), so 'deleted' removes them.
 *
 * @return int rows marked
 */
function ap_events_mark_object_deleted(string $objectId): int
{
    $objectId = rtrim(trim($objectId), '/');
    if ($objectId === '' || !str_starts_with($objectId, 'https://')) {
        return 0;
    }
    try {
        $st = ap_db()->prepare(
            "UPDATE events SET action_taken = 'deleted'
             WHERE (object_id = ? OR object_id = ?)
               AND type IN ('Create', 'Announce', 'Update', 'Quote', 'QuotePost')
               AND action_taken IN ('log', 'local_observe', 'local_fav_update', 'compose')"
        );
        $st->execute([$objectId, $objectId . '/']);
        $n = (int) $st->rowCount();
        if ($n > 0 && function_exists('ap_search_fts_delete_object')) {
            ap_search_fts_delete_object($objectId);
        }
        return $n;
    } catch (Throwable $e) {
        error_log('[ap-db] events_mark_object_deleted: ' . $e->getMessage());
        return 0;
    }
}

/**
 * Hide a firehose interaction when its author sends Undo(Announce/Quote).
 * Interaction rows use the original target object as object_id, while some
 * implementations send the Undo object as the activity URL, so accept both
 * the target and activity identifiers when available.
 */
function ap_events_mark_interaction_undone(
    string $type,
    string $actorId,
    ?string $objectId = null,
    ?string $activityId = null
): int {
    $types = match ($type) {
        'Announce' => ['Announce'],
        'Quote', 'QuotePost' => ['Quote', 'QuotePost'],
        default => [],
    };
    $actorId = rtrim(trim($actorId), '/');
    $objectId = $objectId !== null ? rtrim(trim($objectId), '/') : '';
    $activityId = $activityId !== null ? rtrim(trim($activityId), '/') : '';
    if ($types === [] || $actorId === '' || ($objectId === '' && $activityId === '')) {
        return 0;
    }
    try {
        $typePh = implode(',', array_fill(0, count($types), '?'));
        $where = ["type IN ($typePh)", 'rtrim(actor_id, \'/\') = ?'];
        $params = $types;
        $params[] = $actorId;
        $target = [];
        if ($objectId !== '') {
            $target[] = '(rtrim(object_id, \'/\') = ?)';
            $params[] = $objectId;
        }
        if ($activityId !== '') {
            $target[] = '(rtrim(object_id, \'/\') = ?)';
            $params[] = $activityId;
        }
        $where[] = '(' . implode(' OR ', $target) . ')';
        $st = ap_db()->prepare(
            "UPDATE events SET action_taken = 'deleted'
             WHERE " . implode(' AND ', $where) . "
               AND action_taken IN ('log', 'local_observe', 'local_fav_update')"
        );
        $st->execute($params);
        return (int) $st->rowCount();
    } catch (Throwable $e) {
        error_log('[ap-db] events_mark_interaction_undone: ' . $e->getMessage());
        return 0;
    }
}

/**
 * Apply an inbound Update onto the existing Create row so timelines show new text/media/CW.
 *
 * @param list<string>|null $mediaUrls
 * @return bool true if a Create row was updated
 */
function ap_events_refresh_create_from_update(
    string $objectId,
    ?string $summary,
    ?array $mediaUrls = null,
    ?string $inReplyTo = null,
    string $spoilerText = '',
    bool $sensitive = false,
    string $visibility = 'public'
): bool {
    $objectId = rtrim(trim($objectId), '/');
    if ($objectId === '' || !str_starts_with($objectId, 'https://')) {
        return false;
    }
    $visibility = ap_normalize_visibility($visibility);
    $spoilerText = mb_substr(trim(ap_fix_utf8($spoilerText)), 0, 500);
    if ($spoilerText !== '') {
        $sensitive = true;
    }
    $plain = null;
    if ($summary !== null && $summary !== '') {
        $plain = ap_html_to_plain_text($summary);
        $plain = mb_substr($plain, 0, 4000);
        if ($plain === '') {
            $plain = null;
        }
    }
    $mediaJson = null;
    if (is_array($mediaUrls) && $mediaUrls) {
        $clean = [];
        foreach ($mediaUrls as $u) {
            $s = ap_profile_sanitize_https_url($u);
            if ($s !== null) {
                $clean[] = $s;
            }
            if (count($clean) >= 4) {
                break;
            }
        }
        if ($clean) {
            $mediaJson = json_encode($clean, JSON_UNESCAPED_SLASHES);
        }
    }
    $replyTo = null;
    if (is_string($inReplyTo)) {
        $inReplyTo = trim($inReplyTo);
        if (str_starts_with($inReplyTo, 'https://') && strlen($inReplyTo) <= 800) {
            $replyTo = rtrim($inReplyTo, '/');
        }
    }
    try {
        // Prefer live Create that is still on the timeline (incl. local compose rows)
        $st = ap_db()->prepare(
            "SELECT id FROM events
             WHERE (object_id = ? OR object_id = ?)
               AND type = 'Create'
               AND action_taken IN ('log', 'local_observe', 'compose')
             ORDER BY id DESC LIMIT 1"
        );
        $st->execute([$objectId, $objectId . '/']);
        $id = (int) ($st->fetchColumn() ?: 0);
        if ($id <= 0) {
            return false;
        }
        ap_db()->prepare(
            "UPDATE events SET
                summary = COALESCE(?, summary),
                media_urls = COALESCE(?, media_urls),
                in_reply_to = COALESCE(?, in_reply_to),
                spoiler_text = CASE WHEN ? != '' THEN ? ELSE spoiler_text END,
                sensitive = CASE WHEN ? THEN 1 ELSE sensitive END,
                visibility = ?
             WHERE id = ?"
        )->execute([
            $plain,
            $mediaJson,
            $replyTo,
            $spoilerText,
            $spoilerText,
            $sensitive ? 1 : 0,
            $visibility,
            $id,
        ]);
        if (function_exists('ap_search_fts_index_event_row')) {
            $fresh = ap_db()->prepare('SELECT * FROM events WHERE id = ?');
            $fresh->execute([$id]);
            $row = $fresh->fetch();
            if (is_array($row)) {
                ap_search_fts_index_event_row($row);
            }
        }
        return true;
    } catch (Throwable $e) {
        error_log('[ap-db] events_refresh_create_from_update: ' . $e->getMessage());
        return false;
    }
}

/** One-shot: mark Creates deleted when a Delete event already exists for the same object. */
function ap_events_backfill_deleted_from_deletes(): int
{
    try {
        $st = ap_db()->prepare(
            "UPDATE events SET action_taken = 'deleted'
             WHERE type IN ('Create', 'Announce', 'Update', 'Quote', 'QuotePost')
               AND action_taken IN ('log', 'local_observe', 'local_fav_update')
               AND object_id IS NOT NULL AND object_id != ''
               AND EXISTS (
                 SELECT 1 FROM events d
                 WHERE d.type = 'Delete'
                   AND (d.object_id = events.object_id OR d.object_id = events.object_id || '/')
               )"
        );
        $st->execute();
        return (int) $st->rowCount();
    } catch (Throwable $e) {
        error_log('[ap-db] events_backfill_deleted: ' . $e->getMessage());
        return 0;
    }
}

/** Look up a firehose event by ActivityPub object URL. */
function ap_event_by_object_id(string $objectId): ?array
{
    $objectId = rtrim(trim($objectId), '/');
    if ($objectId === '' || !str_starts_with($objectId, 'https://')) {
        return null;
    }
    // Prefer the Note itself (Create/Update) over later Announces/Likes that
    // share the same object_id. Otherwise Open/thread views bind the boost row
    // and render an empty focused post (reblog wrapper with content='').
    // Skip soft-deleted firehose rows.
    $st = ap_db()->prepare(
        "SELECT * FROM events WHERE (object_id = ? OR object_id = ?)
           AND COALESCE(action_taken, '') != 'deleted'
         ORDER BY CASE type
           WHEN 'Create' THEN 0
           WHEN 'Update' THEN 1
           WHEN 'Announce' THEN 10
           WHEN 'Like' THEN 11
           ELSE 5
         END ASC, id DESC
         LIMIT 1"
    );
    $st->execute([$objectId, $objectId . '/']);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_follower_upsert(
    string $actorId,
    ?string $inbox,
    ?string $sharedInbox,
    ?string $username = null,
    ?string $ownerActorId = null
): void {
    $owner = rtrim($ownerActorId ?? ap_local_actor_id(), '/');
    $actorId = rtrim($actorId, '/');
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : null;
    $now = ap_db_now();
    $db = ap_db();
    $existing = $db->prepare(
        'SELECT actor_id FROM followers WHERE owner_actor_id = ? AND (actor_id = ? OR actor_id = ?) LIMIT 1'
    );
    $existing->execute([$owner, $actorId, $actorId . '/']);
    if ($existing->fetch()) {
        $stmt = $db->prepare(
            'UPDATE followers SET inbox = COALESCE(?, inbox), shared_inbox = COALESCE(?, shared_inbox),
             last_seen = ?, username = COALESCE(?, username), host = COALESCE(?, host), actor_id = ?
             WHERE owner_actor_id = ? AND (actor_id = ? OR actor_id = ?)'
        );
        $stmt->execute([$inbox, $sharedInbox, $now, $username, $host, $actorId, $owner, $actorId, $actorId . '/']);
    } else {
        $stmt = $db->prepare(
            'INSERT INTO followers (owner_actor_id, actor_id, inbox, shared_inbox, followed_at, last_seen, username, host)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
        );
        $stmt->execute([$owner, $actorId, $inbox, $sharedInbox, $now, $now, $username, $host]);
    }
    ap_follow_lists_reset_memo();
}

function ap_follower_remove(string $actorId, ?string $ownerActorId = null): void
{
    $owner = rtrim($ownerActorId ?? ap_local_actor_id(), '/');
    $actorId = rtrim($actorId, '/');
    ap_db()->prepare(
        'DELETE FROM followers WHERE owner_actor_id = ? AND (actor_id = ? OR actor_id = ?)'
    )->execute([$owner, $actorId, $actorId . '/']);
    ap_follow_lists_reset_memo();
}

/** Store an inbound Follow until the local account approves or rejects it. */
function ap_follow_request_upsert(
    string $ownerActorId,
    string $actorId,
    ?string $inbox,
    ?string $sharedInbox,
    ?string $username,
    ?string $followActivityId
): bool {
    $ownerActorId = rtrim(trim($ownerActorId), '/');
    $actorId = rtrim(trim($actorId), '/');
    if ($ownerActorId === '' || $actorId === '') {
        return false;
    }
    try {
        $now = ap_db_now();
        ap_db()->prepare(
            'INSERT INTO ap_follow_requests
               (owner_actor_id, actor_id, inbox, shared_inbox, username, follow_activity_id, status, created_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, \'pending\', ?, ?)
             ON CONFLICT(owner_actor_id, actor_id) DO UPDATE SET
               inbox = excluded.inbox,
               shared_inbox = excluded.shared_inbox,
               username = COALESCE(excluded.username, ap_follow_requests.username),
               follow_activity_id = excluded.follow_activity_id,
               status = \'pending\',
               updated_at = excluded.updated_at'
        )->execute([$ownerActorId, $actorId, $inbox, $sharedInbox, $username, $followActivityId, $now, $now]);
        return true;
    } catch (Throwable $e) {
        error_log('[ap-db] follow_request_upsert: ' . $e->getMessage());
        return false;
    }
}

/** @return list<array<string,mixed>> */
function ap_follow_requests_list(string $ownerActorId): array
{
    try {
        $st = ap_db()->prepare(
            "SELECT * FROM ap_follow_requests WHERE owner_actor_id = ? AND status = 'pending'
             ORDER BY created_at ASC, id ASC"
        );
        $st->execute([rtrim($ownerActorId, '/')]);
        return $st->fetchAll() ?: [];
    } catch (Throwable $e) {
        error_log('[ap-db] follow_requests_list: ' . $e->getMessage());
        return [];
    }
}

function ap_follow_request_get(int $id, string $ownerActorId): ?array
{
    if ($id < 1) {
        return null;
    }
    try {
        $st = ap_db()->prepare(
            "SELECT * FROM ap_follow_requests
             WHERE id = ? AND owner_actor_id = ? AND status = 'pending' LIMIT 1"
        );
        $st->execute([$id, rtrim($ownerActorId, '/')]);
        $row = $st->fetch();
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        return null;
    }
}

function ap_follow_request_set_status(int $id, string $ownerActorId, string $status): bool
{
    $status = in_array($status, ['accepted', 'rejected'], true) ? $status : 'pending';
    try {
        $st = ap_db()->prepare(
            'UPDATE ap_follow_requests SET status = ?, updated_at = ? WHERE id = ? AND owner_actor_id = ?'
        );
        $st->execute([$status, ap_db_now(), $id, rtrim($ownerActorId, '/')]);
        return $st->rowCount() > 0;
    } catch (Throwable $e) {
        error_log('[ap-db] follow_request_status: ' . $e->getMessage());
        return false;
    }
}

function ap_following_upsert(string $actorId, ?string $ownerActorId = null): void
{
    $owner = rtrim($ownerActorId ?? ap_local_actor_id(), '/');
    $actorId = rtrim($actorId, '/');
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : null;
    $db = ap_db();
    $stmt = $db->prepare(
        'INSERT INTO following (owner_actor_id, actor_id, followed_at, host) VALUES (?, ?, ?, ?)
         ON CONFLICT(owner_actor_id, actor_id) DO NOTHING'
    );
    $stmt->execute([$owner, $actorId, ap_db_now(), $host]);
    ap_follow_lists_reset_memo();
}

function ap_following_remove(string $actorId, ?string $ownerActorId = null): void
{
    $owner = rtrim($ownerActorId ?? ap_local_actor_id(), '/');
    $actorId = rtrim($actorId, '/');
    $db = ap_db();
    $db->prepare(
        'DELETE FROM following WHERE owner_actor_id = ? AND (actor_id = ? OR actor_id = ?)'
    )->execute([$owner, $actorId, $actorId . '/']);
    ap_follow_lists_reset_memo();
}

/** True if the owner follows this actor (trailing-slash tolerant). */
function ap_actor_is_followed(string $actorId, ?string $ownerActorId = null): bool
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://')) {
        return false;
    }
    foreach (ap_following_list($ownerActorId) as $row) {
        if (rtrim((string) ($row['actor_id'] ?? ''), '/') === $actorId) {
            return true;
        }
    }
    return false;
}

function ap_mention_store(array $row): void
{
    // Text + optional remote media URLs (https only). Never stores media bytes.
    $content = isset($row['content']) ? mb_substr(strip_tags(ap_fix_utf8((string) $row['content'])), 0, 2000) : null;
    $objectId = $row['object_id'] ?? null;
    if (!$objectId) {
        return;
    }
    $ownerUserId = (int) ($row['owner_user_id'] ?? 0);
    if ($ownerUserId < 1) {
        $ownerHint = (string) ($row['owner_actor_id'] ?? $row['target_actor'] ?? '');
        if ($ownerHint === '' && function_exists('ap_local_actor_id')) {
            $ownerHint = ap_local_actor_id();
        }
        $ownerUserId = $ownerHint !== ''
            ? ap_db_owner_user_id_for_actor($ownerHint)
            : ap_db_default_owner_user_id();
    }
    $ownerActorId = rtrim((string) ($row['owner_actor_id'] ?? ''), '/');
    if ($ownerActorId === '') {
        $ownerActorId = ap_db_owner_actor_id_for_user_id($ownerUserId);
    }
    $spoilerText = mb_substr(trim(ap_fix_utf8((string) ($row['spoiler_text'] ?? ''))), 0, 500);
    $sensitive = !empty($row['sensitive']) || $spoilerText !== '';
    $mediaUrls = null;
    if (!empty($row['media_urls']) && is_array($row['media_urls'])) {
        $clean = [];
        foreach ($row['media_urls'] as $u) {
            $s = ap_profile_sanitize_https_url($u);
            if ($s !== null) {
                $clean[] = $s;
            }
            if (count($clean) >= 4) {
                break;
            }
        }
        if ($clean) {
            $mediaUrls = json_encode($clean, JSON_UNESCAPED_SLASHES);
        }
    }
    $activityType = isset($row['activity_type']) ? mb_substr(trim((string) $row['activity_type']), 0, 40) : null;
    if ($activityType === '') {
        $activityType = null;
    }
    $db = ap_db();
    $stmt = $db->prepare(
        'INSERT INTO mentions (owner_user_id, owner_actor_id, created_at, activity_id, object_id, actor_id, type, content, in_reply_to, deleted_at, media_urls, activity_type, spoiler_text, sensitive)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?)
         ON CONFLICT(owner_user_id, object_id) DO UPDATE SET
           owner_actor_id = COALESCE(excluded.owner_actor_id, mentions.owner_actor_id),
           created_at = excluded.created_at,
           activity_id = excluded.activity_id,
           actor_id = COALESCE(excluded.actor_id, mentions.actor_id),
           content = excluded.content,
           media_urls = COALESCE(excluded.media_urls, mentions.media_urls),
           activity_type = COALESCE(excluded.activity_type, mentions.activity_type),
           spoiler_text = CASE
             WHEN excluded.spoiler_text != \'\' THEN excluded.spoiler_text
             ELSE mentions.spoiler_text END,
           sensitive = CASE
             WHEN excluded.sensitive = 1 THEN 1
             ELSE mentions.sensitive END,
           deleted_at = NULL'
    );
    $createdAt = ap_db_now();
    $stmt->execute([
        $ownerUserId,
        $ownerActorId,
        $createdAt,
        $row['activity_id'] ?? null,
        $objectId,
        $row['actor_id'] ?? null,
        $row['type'] ?? null,
        $content,
        $row['in_reply_to'] ?? null,
        $mediaUrls,
        $activityType,
        $spoilerText,
        $sensitive ? 1 : 0,
    ]);
    if (function_exists('ap_search_fts_index_mention_row')) {
        $mid = 0;
        try {
            $lookup = $db->prepare(
                'SELECT id FROM mentions WHERE owner_user_id = ? AND object_id = ? LIMIT 1'
            );
            $lookup->execute([$ownerUserId, $objectId]);
            $mid = (int) ($lookup->fetchColumn() ?: 0);
        } catch (Throwable $e) {
            $mid = 0;
        }
        if ($mid > 0) {
            ap_search_fts_index_mention_row([
                'id' => $mid,
                'object_id' => $objectId,
                'content' => $content,
                'spoiler_text' => $spoilerText,
                'activity_type' => $activityType,
                'type' => $row['type'] ?? null,
                'created_at' => $createdAt,
                'deleted_at' => null,
            ]);
        }
    }
}

/**
 * Mentions for one local account (newest first).
 *
 * @return list<array<string,mixed>>
 */
function ap_mentions_list(int $limit = 120, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        return [];
    }
    $limit = max(1, min(250, $limit));
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM mentions WHERE owner_user_id = ? AND deleted_at IS NULL
             ORDER BY id DESC LIMIT ?'
        );
        $st->execute([$ownerUserId, $limit]);
        return $st->fetchAll() ?: [];
    } catch (Throwable $e) {
        return [];
    }
}

/**
 * Soft-delete a mention by exact object_id, and any suffix rows (e.g. #quote- / #like-).
 *
 * @return int number of rows soft-deleted
 */
function ap_mention_soft_delete(string $objectId): int
{
    $objectId = rtrim($objectId, '/');
    if ($objectId === '') {
        return 0;
    }
    $now = ap_db_now();
    $st = ap_db()->prepare(
        'UPDATE mentions SET deleted_at = ?
         WHERE deleted_at IS NULL AND (
           object_id = ? OR object_id = ? OR object_id LIKE ?
         )'
    );
    $st->execute([$now, $objectId, $objectId . '/', $objectId . '#%']);
    $n = (int) $st->rowCount();
    if ($n > 0 && function_exists('ap_search_fts_delete_object')) {
        ap_search_fts_delete_object($objectId);
    }
    return $n;
}

/**
 * Stable mention object_id for like/reblog/quote so undo+redo collapses to one row.
 * kind: like | reblog | quote | update
 */
function ap_mention_interaction_object_id(string $targetObjectId, string $actorId, string $kind): string
{
    $target = rtrim($targetObjectId, '/');
    $actor = rtrim($actorId, '/');
    $kind = strtolower($kind);
    if (!in_array($kind, ['like', 'reblog', 'quote', 'update', 'bite'], true)) {
        $kind = 'like';
    }
    $hash = substr(hash('sha256', $actor . '|' . $target . '|' . $kind), 0, 12);
    return $target . '#' . $kind . '-' . $hash;
}

/**
 * Soft-delete like/reblog/quote notification(s) for an actor + target object.
 * Also matches by activity_id when provided (Undo of a specific Like activity).
 *
 * @return int rows touched
 */
function ap_mention_soft_delete_interaction(string $actorId, string $targetObjectId, string $kind, ?string $activityId = null): int
{
    $actorId = rtrim($actorId, '/');
    $targetObjectId = rtrim($targetObjectId, '/');
    $kind = strtolower($kind);
    $now = ap_db_now();
    $touched = 0;
    $db = ap_db();

    if ($activityId !== null && $activityId !== '') {
        $st = $db->prepare(
            'UPDATE mentions SET deleted_at = ?
             WHERE deleted_at IS NULL AND activity_id = ?'
        );
        $st->execute([$now, $activityId]);
        $touched += $st->rowCount();
    }

    if ($actorId !== '' && $targetObjectId !== '' && in_array($kind, ['like', 'reblog', 'quote', 'update'], true)) {
        $stableId = ap_mention_interaction_object_id($targetObjectId, $actorId, $kind);
        $likePattern = $targetObjectId . '#' . $kind . '-%';
        // Stable key + any legacy activity-id-keyed rows for same actor/target/kind
        $st = $db->prepare(
            'UPDATE mentions SET deleted_at = ?
             WHERE deleted_at IS NULL AND (
               object_id = ?
               OR ((actor_id = ? OR actor_id = ?) AND object_id LIKE ?)
             )'
        );
        $st->execute([$now, $stableId, $actorId, $actorId . '/', $likePattern]);
        $touched += $st->rowCount();
    }

    return $touched;
}

/** Normalize compose audience: public | unlisted | private. */
function ap_normalize_visibility(mixed $visibility): string
{
    $v = strtolower(trim((string) $visibility));
    if ($v === 'unlisted' || $v === 'silent' || $v === 'silent_public') {
        return 'unlisted';
    }
    if ($v === 'private' || $v === 'followers' || $v === 'followers_only') {
        return 'private';
    }
    return 'public';
}

/** HTML profile / public discovery: only fully public posts. */
function ap_visibility_on_html_profile(string $visibility): bool
{
    return ap_normalize_visibility($visibility) === 'public';
}

/** ActivityPub outbox collection: public + unlisted (Mastodon-compatible). */
function ap_visibility_in_ap_outbox(string $visibility): bool
{
    $v = ap_normalize_visibility($visibility);
    return $v === 'public' || $v === 'unlisted';
}

function ap_outbox_store(array $note): void
{
    $kind = (string) ($note['kind'] ?? 'compose');
    if (!in_array($kind, ['compose', 'blog', 'note', 'quote', 'poll'], true)) {
        $kind = 'compose';
    }
    $visibility = ap_normalize_visibility($note['visibility'] ?? 'public');
    // Safety: never persist Create.object with nested @context (Bridgy Fed breakage)
    $raw = (string) ($note['raw_create_json'] ?? '');
    $decoded = $raw !== '' ? json_decode($raw, true) : null;
    if (is_array($decoded)) {
        $raw = json_encode(ap_create_finalize($decoded), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) ?: $raw;
    }
    $stmt = ap_db()->prepare(
        'INSERT INTO outbox_notes (id, create_id, published, content, in_reply_to, to_json, cc_json, raw_create_json, kind, visibility)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
    );
    $stmt->execute([
        $note['id'],
        $note['create_id'],
        $note['published'],
        $note['content'],
        $note['in_reply_to'] ?? null,
        json_encode($note['to'] ?? [], JSON_UNESCAPED_SLASHES),
        json_encode($note['cc'] ?? [], JSON_UNESCAPED_SLASHES),
        $raw,
        $kind,
        $visibility,
    ]);
}

/** Latest public outbox notes, optionally excluding kinds (e.g. blog shares). */
function ap_outbox_list_public(int $limit = 20, array $excludeKinds = ['blog'], string $actorKey = 'cmdr_nova'): array
{
    $limit = max(1, min(50, $limit));
    $rows = ap_outbox_list(80, $actorKey);
    $out = [];
    foreach ($rows as $row) {
        $kind = (string) ($row['kind'] ?? 'compose');
        // Back-compat: detect blog shares by content marker
        if ($kind === 'compose' && is_string($row['content'] ?? null)
            && (str_contains($row['content'], 'Read on mkultra.monster') || str_contains($row['content'], 'Today on NovaLandia:'))) {
            $kind = 'blog';
        }
        if (in_array($kind, $excludeKinds, true)) {
            continue;
        }
        $out[] = $row;
        if (count($out) >= $limit) {
            break;
        }
    }
    return $out;
}

function ap_outbox_list(int $limit = 50, ?string $actorKey = null): array
{
    $limit = max(1, min(200, $limit));
    if ($actorKey !== null && $actorKey !== '') {
        $actorKey = strtolower(trim($actorKey));
        $prefix = 'https://mkultra.monster/users/' . rawurlencode($actorKey) . '/';
        $stmt = ap_db()->prepare(
            'SELECT * FROM outbox_notes WHERE id LIKE ? ORDER BY published DESC LIMIT ?'
        );
        $stmt->execute([$prefix . '%', $limit]);
        return $stmt->fetchAll() ?: [];
    }
    $stmt = ap_db()->prepare('SELECT * FROM outbox_notes ORDER BY published DESC LIMIT ?');
    $stmt->execute([$limit]);
    return $stmt->fetchAll() ?: [];
}

function ap_follow_lists_cache_gen(bool $bump = false): int
{
    static $gen = 0;
    if ($bump) {
        $gen++;
    }
    return $gen;
}

/** Default owner for legacy single-user callers. */
function ap_default_owner_actor_id(): string
{
    return 'https://mkultra.monster/users/cmdr_nova';
}

/**
 * Request-local social actor (personal inbox / Accept Follow as invitee).
 * Falls back to LOCAL_ACTOR / cmdr_nova.
 */
function ap_request_actor_set(?string $actorKey): void
{
    if ($actorKey === null || $actorKey === '') {
        unset($GLOBALS['ap_req_actor']);
        // Reset cached private key so next load uses default path
        $GLOBALS['ap_local_priv_key_cache'] = false;
        return;
    }
    $actorKey = strtolower(trim($actorKey));
    $actorKey = preg_replace('/[^a-z0-9_]/', '', $actorKey) ?? '';
    if ($actorKey === '') {
        unset($GLOBALS['ap_req_actor']);
        return;
    }
    $id = 'https://mkultra.monster/users/' . rawurlencode($actorKey);
    $priv = '/etc/mkultra/ap-inbox/' . $actorKey . '_private.pem';
    if (function_exists('ap_actor_key_paths')) {
        $paths = ap_actor_key_paths($actorKey);
        $priv = $paths['private'];
    }
    $GLOBALS['ap_req_actor'] = [
        'key' => $actorKey,
        'id' => $id,
        'priv' => $priv,
        'key_id' => $id . '#main-key',
    ];
    $GLOBALS['ap_local_priv_key_cache'] = false;
}

/** @return array{key:string,id:string,priv:string,key_id:string}|null */
function ap_request_actor_get(): ?array
{
    $a = $GLOBALS['ap_req_actor'] ?? null;
    return is_array($a) ? $a : null;
}

function ap_local_actor_id(): string
{
    // VAAK / OAuth session actor wins — never substitute cmdr_nova for another user.
    if (!empty($GLOBALS['vaak_actor_id'])) {
        $g = rtrim((string) $GLOBALS['vaak_actor_id'], '/');
        if ($g !== '' && str_starts_with($g, 'https://')) {
            return $g;
        }
    }
    if (!empty($GLOBALS['vaak_user']['actor_id'])) {
        $g = rtrim((string) $GLOBALS['vaak_user']['actor_id'], '/');
        if ($g !== '' && str_starts_with($g, 'https://')) {
            return $g;
        }
    }
    if (!empty($GLOBALS['vaak_actor_key'])) {
        $key = strtolower(trim((string) $GLOBALS['vaak_actor_key']));
        $key = preg_replace('/[^a-z0-9_]/', '', $key) ?? '';
        if ($key !== '') {
            return 'https://mkultra.monster/users/' . $key;
        }
    }
    if (ap_db_session_bound()) {
        error_log('[ap-db] session bound but local actor id missing — refusing cmdr_nova fallback');
        return '';
    }
    $req = ap_request_actor_get();
    if ($req !== null && !empty($req['id'])) {
        return (string) $req['id'];
    }
    if (defined('LOCAL_ACTOR')) {
        return (string) LOCAL_ACTOR;
    }
    return ap_default_owner_actor_id();
}

function ap_local_priv_path(): string
{
    $req = ap_request_actor_get();
    if ($req !== null && !empty($req['priv'])) {
        return (string) $req['priv'];
    }
    if (defined('LOCAL_PRIV')) {
        return (string) LOCAL_PRIV;
    }
    return '/etc/mkultra/ap-inbox/cmdr_nova_private.pem';
}

function ap_local_key_id(): string
{
    $req = ap_request_actor_get();
    if ($req !== null && !empty($req['key_id'])) {
        return (string) $req['key_id'];
    }
    if (defined('LOCAL_KEY_ID')) {
        return (string) LOCAL_KEY_ID;
    }
    return ap_default_owner_actor_id() . '#main-key';
}

/**
 * Resolve a local ap_users row by actor URL (not disabled).
 *
 * @return array<string,mixed>|null
 */
function ap_local_user_by_actor_id(string $actorId): ?array
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://mkultra.monster/users/')) {
        return null;
    }
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM ap_users
             WHERE disabled_at IS NULL AND (actor_id = ? OR actor_id = ? OR lower(actor_key) = lower(?))
             LIMIT 1'
        );
        $key = rawurldecode(basename(parse_url($actorId, PHP_URL_PATH) ?: ''));
        $st->execute([$actorId, $actorId . '/', $key]);
        $row = $st->fetch();
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        return null;
    }
}

/**
 * @return array<string,mixed>|null
 */
function ap_local_user_by_username(string $username): ?array
{
    $username = strtolower(trim($username));
    if ($username === '' || !preg_match('/^[a-z][a-z0-9_]{1,29}$/', $username)) {
        return null;
    }
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM ap_users WHERE lower(username) = ? AND disabled_at IS NULL LIMIT 1'
        );
        $st->execute([$username]);
        $row = $st->fetch();
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        return null;
    }
}

function ap_followers_list(?string $ownerActorId = null): array
{
    $owner = rtrim((string) ($ownerActorId ?? ''), '/');
    if ($owner === '') {
        $owner = rtrim(ap_local_actor_id(), '/');
    }
    if ($owner === '') {
        $owner = rtrim(ap_default_owner_actor_id(), '/');
    }
    static $memo = [];
    static $memoGen = -1;
    $gen = ap_follow_lists_cache_gen();
    if ($memoGen !== $gen) {
        $memo = [];
        $memoGen = $gen;
    }
    if (isset($memo[$owner])) {
        return $memo[$owner];
    }
    $st = ap_db()->prepare(
        'SELECT * FROM followers WHERE owner_actor_id = ? OR owner_actor_id = ? ORDER BY followed_at DESC'
    );
    $st->execute([$owner, $owner . '/']);
    return $memo[$owner] = ($st->fetchAll() ?: []);
}

function ap_following_list(?string $ownerActorId = null): array
{
    $owner = rtrim((string) ($ownerActorId ?? ''), '/');
    if ($owner === '') {
        $owner = rtrim(ap_local_actor_id(), '/');
    }
    if ($owner === '') {
        $owner = rtrim(ap_default_owner_actor_id(), '/');
    }
    static $memo = [];
    static $memoGen = -1;
    $gen = ap_follow_lists_cache_gen();
    if ($memoGen !== $gen) {
        $memo = [];
        $memoGen = $gen;
    }
    if (isset($memo[$owner])) {
        return $memo[$owner];
    }
    $st = ap_db()->prepare(
        'SELECT * FROM following WHERE owner_actor_id = ? OR owner_actor_id = ? ORDER BY followed_at DESC'
    );
    $st->execute([$owner, $owner . '/']);
    return $memo[$owner] = ($st->fetchAll() ?: []);
}

/** Invalidate request-local follow graph memos after follow/unfollow mutations. */
function ap_follow_lists_reset_memo(): void
{
    ap_follow_lists_cache_gen(true);
}

function ap_outbound_follow_count_recent(int $withinSeconds = 3600): int
{
    $owner = rtrim(ap_local_actor_id(), '/');
    if ($owner === '') {
        $owner = rtrim(ap_default_owner_actor_id(), '/');
    }
    $since = gmdate('c', time() - $withinSeconds);
    $stmt = ap_db()->prepare(
        'SELECT COUNT(*) AS c FROM following
         WHERE followed_at >= ? AND (owner_actor_id = ? OR owner_actor_id = ?)'
    );
    $stmt->execute([$since, $owner, $owner . '/']);
    return (int) ($stmt->fetch()['c'] ?? 0);
}

/* ----------------- blocks / suspend ----------------- */

/**
 * @return list<array<string,mixed>>
 */
function ap_block_list(): array
{
    try {
        return ap_db()->query('SELECT * FROM ap_blocks ORDER BY created_at DESC')->fetchAll();
    } catch (Throwable $e) {
        error_log('[ap-db] block_list: ' . $e->getMessage());
        return [];
    }
}

/**
 * Cached block list for hot paths (inbox). Call ap_block_cache_clear() after mutations.
 *
 * @return list<array<string,mixed>>
 */
function ap_block_list_cached(bool $refresh = false): array
{
    static $cache = null;
    if ($refresh || $cache === null) {
        $cache = ap_block_list();
    }
    return $cache;
}

function ap_block_cache_clear(): void
{
    ap_block_list_cached(true);
}

function ap_block_normalize_domain(string $raw): ?string
{
    $raw = strtolower(trim($raw));
    $raw = preg_replace('#^https?://#', '', $raw) ?? $raw;
    $raw = rtrim($raw, '/');
    // strip path if pasted as URL
    if (str_contains($raw, '/')) {
        $raw = explode('/', $raw, 2)[0];
    }
    if ($raw === '' || strlen($raw) > 253) {
        return null;
    }
    if (!preg_match('/^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$/i', $raw)) {
        return null;
    }
    if (!str_contains($raw, '.')) {
        return null;
    }
    // Never allow blocking our own host
    if ($raw === 'mkultra.monster' || str_ends_with($raw, '.mkultra.monster')) {
        return null;
    }
    return $raw;
}

function ap_block_normalize_actor(string $raw): ?string
{
    $raw = trim($raw);
    if ($raw === '') {
        return null;
    }
    if (str_starts_with($raw, 'https://')) {
        $url = ap_profile_sanitize_https_url($raw);
        if ($url === null) {
            return null;
        }
        $host = parse_url($url, PHP_URL_HOST);
        if (!is_string($host) || $host === '') {
            return null;
        }
        $host = strtolower($host);
        if ($host === 'mkultra.monster' || str_ends_with($host, '.mkultra.monster')) {
            return null;
        }
        return rtrim($url, '/');
    }
    return null;
}

/**
 * @return array{ok:bool,error?:string,id?:int,scope?:string,value?:string,side_effects?:array}
 */
function ap_block_upsert(string $scope, string $value, string $kind = 'block', ?string $reason = null): array
{
    $scope = $scope === 'domain' ? 'domain' : 'actor';
    $kind = in_array($kind, ['block', 'suspend', 'mute'], true) ? $kind : 'block';
    if ($scope === 'domain') {
        $norm = ap_block_normalize_domain($value);
        if ($norm === null) {
            return ['ok' => false, 'error' => 'Invalid domain (use example.com — not mkultra.monster).'];
        }
        $value = $norm;
    } else {
        $norm = ap_block_normalize_actor($value);
        if ($norm === null) {
            return ['ok' => false, 'error' => 'Invalid actor URL (https://… only; resolve handles before calling).'];
        }
        $value = $norm;
    }
    $reason = $reason !== null ? mb_substr(trim(ap_fix_utf8($reason)), 0, 500) : null;
    if ($reason === '') {
        $reason = null;
    }
    $now = ap_db_now();
    $db = ap_db();
    $stmt = $db->prepare(
        'INSERT INTO ap_blocks (created_at, updated_at, scope, value, kind, reason, created_by)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(scope, value) DO UPDATE SET
           kind = excluded.kind,
           reason = excluded.reason,
           updated_at = excluded.updated_at'
    );
    $stmt->execute([$now, $now, $scope, $value, $kind, $reason, 'admin']);
    ap_block_cache_clear();
    $side = ap_block_apply_side_effects($scope, $value, $kind);
    $idRow = $db->prepare('SELECT id FROM ap_blocks WHERE scope = ? AND value = ?');
    $idRow->execute([$scope, $value]);
    $id = (int) ($idRow->fetch()['id'] ?? 0);
    return ['ok' => true, 'id' => $id, 'scope' => $scope, 'value' => $value, 'side_effects' => $side];
}

/**
 * Remove a block by id. Restores soft-deleted mentions from that domain/actor;
 * follow relationships are not recreated (re-follow manually if desired).
 *
 * @return array{ok:bool,error?:string,scope?:string,value?:string,mentions_restored?:int}
 */
function ap_block_remove(int $id): array
{
    if ($id <= 0) {
        return ['ok' => false, 'error' => 'Missing block id'];
    }
    $db = ap_db();
    $st = $db->prepare('SELECT * FROM ap_blocks WHERE id = ?');
    $st->execute([$id]);
    $row = $st->fetch();
    if (!is_array($row)) {
        return ['ok' => false, 'error' => 'Block not found'];
    }
    $scope = (string) ($row['scope'] ?? '');
    $value = (string) ($row['value'] ?? '');
    $del = $db->prepare('DELETE FROM ap_blocks WHERE id = ?');
    $del->execute([$id]);
    if ($del->rowCount() < 1) {
        return ['ok' => false, 'error' => 'Block not found'];
    }
    ap_block_cache_clear();
    $restored = ap_block_undo_side_effects($scope, $value);
    return [
        'ok' => true,
        'scope' => $scope,
        'value' => $value,
        'mentions_restored' => (int) ($restored['mentions_restored'] ?? 0),
    ];
}

/**
 * True if $host is exactly a blocked domain, or a subdomain of one
 * (blocking bae.st also blocks www.bae.st / foo.bae.st).
 */
function ap_is_blocked_host(?string $host): bool
{
    if ($host === null || $host === '') {
        return false;
    }
    $host = strtolower($host);
    foreach (ap_block_list_cached() as $b) {
        if (($b['scope'] ?? '') !== 'domain' || ($b['kind'] ?? 'block') === 'mute') {
            continue;
        }
        $blocked = strtolower((string) ($b['value'] ?? ''));
        if ($blocked === '') {
            continue;
        }
        if ($host === $blocked || str_ends_with($host, '.' . $blocked)) {
            return true;
        }
    }
    return false;
}

function ap_is_blocked_actor(?string $actorId): bool
{
    if ($actorId === null || $actorId === '') {
        return false;
    }
    $actorId = rtrim($actorId, '/');
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : null;
    if ($host && ap_is_blocked_host($host)) {
        return true;
    }
    foreach (ap_block_list_cached() as $b) {
        if (($b['scope'] ?? '') !== 'actor' || ($b['kind'] ?? 'block') === 'mute') {
            continue;
        }
        if (rtrim((string) $b['value'], '/') === $actorId) {
            return true;
        }
    }
    return false;
}

/** True when an actor/domain is hidden from all local timelines, but still federates. */
function ap_is_globally_muted_actor(?string $actorId, ?string $host = null): bool
{
    $actorId = $actorId !== null ? rtrim(trim($actorId), '/') : '';
    $host = $host !== null ? strtolower(trim($host)) : '';
    if ($host === '' && $actorId !== '') {
        $parsed = parse_url($actorId, PHP_URL_HOST);
        $host = is_string($parsed) ? strtolower($parsed) : '';
    }
    foreach (ap_block_list_cached() as $b) {
        if (($b['kind'] ?? '') !== 'mute') {
            continue;
        }
        if (($b['scope'] ?? '') === 'actor' && $actorId !== ''
            && rtrim((string) ($b['value'] ?? ''), '/') === $actorId) {
            return true;
        }
        if (($b['scope'] ?? '') === 'domain' && $host !== '') {
            $domain = strtolower((string) ($b['value'] ?? ''));
            if ($domain !== '' && ($host === $domain || str_ends_with($host, '.' . $domain))) {
                return true;
            }
        }
    }
    return false;
}

function ap_is_blocked_inbox(?string $inboxUrl): bool
{
    if ($inboxUrl === null || $inboxUrl === '') {
        return false;
    }
    $host = parse_url($inboxUrl, PHP_URL_HOST);
    return is_string($host) && ap_is_blocked_host(strtolower($host));
}

/**
 * Remove local follow relationships and hide mentions for a new block.
 *
 * @return array{followers_removed:int,following_removed:int,mentions_hidden:int}
 */
function ap_block_apply_side_effects(string $scope, string $value, string $kind = 'block'): array
{
    $db = ap_db();
    $followers = 0;
    $following = 0;
    $mentions = 0;
    $now = ap_db_now();

    if ($scope === 'domain') {
        if ($kind !== 'mute') {
            $st = $db->prepare('DELETE FROM followers WHERE host = ? OR host LIKE ?');
            $st->execute([$value, '%.' . $value]);
            $followers = $st->rowCount();
            $st = $db->prepare('DELETE FROM following WHERE host = ? OR host LIKE ?');
            $st->execute([$value, '%.' . $value]);
            $following = $st->rowCount();
        }
        // Exact host + subdomains
        $st = $db->prepare(
            "UPDATE mentions SET deleted_at = ? WHERE deleted_at IS NULL
             AND (actor_id LIKE ? OR actor_id LIKE ?)"
        );
        $st->execute([$now, 'https://' . $value . '/%', 'https://%.' . $value . '/%']);
        $mentions = $st->rowCount();
    } else {
        $alt = str_ends_with($value, '/') ? rtrim($value, '/') : ($value . '/');
        if ($kind !== 'mute') {
            $st = $db->prepare('DELETE FROM followers WHERE actor_id = ?');
            $st->execute([$value]);
            $followers = $st->rowCount();
            // also try with/without trailing slash variance
            $db->prepare('DELETE FROM followers WHERE actor_id = ?')->execute([$alt]);
            $st = $db->prepare('DELETE FROM following WHERE actor_id = ? OR actor_id = ?');
            $st->execute([$value, $alt]);
            $following = $st->rowCount();
        }
        $st = $db->prepare(
            'UPDATE mentions SET deleted_at = ? WHERE deleted_at IS NULL AND (actor_id = ? OR actor_id = ?)'
        );
        $st->execute([$now, $value, $alt]);
        $mentions = $st->rowCount();
    }

    return [
        'followers_removed' => $followers,
        'following_removed' => $following,
        'mentions_hidden' => $mentions,
    ];
}

/**
 * After unblock: re-show soft-deleted mentions from that domain/actor.
 * Does not restore deleted follow rows (those need a fresh Follow).
 *
 * @return array{mentions_restored:int}
 */
function ap_block_undo_side_effects(string $scope, string $value): array
{
    $db = ap_db();
    $restored = 0;
    try {
        if ($scope === 'domain') {
            $value = strtolower(trim($value));
            $st = $db->prepare(
                "UPDATE mentions SET deleted_at = NULL
                 WHERE deleted_at IS NOT NULL
                   AND (actor_id LIKE ? OR actor_id LIKE ?)"
            );
            $st->execute(['https://' . $value . '/%', 'https://%.' . $value . '/%']);
            $restored = $st->rowCount();
        } elseif ($scope === 'actor') {
            $value = rtrim($value, '/');
            $alt = $value . '/';
            $st = $db->prepare(
                'UPDATE mentions SET deleted_at = NULL
                 WHERE deleted_at IS NOT NULL AND (actor_id = ? OR actor_id = ?)'
            );
            $st->execute([$value, $alt]);
            $restored = $st->rowCount();
        }
    } catch (Throwable $e) {
        error_log('[ap-db] block_undo_side_effects: ' . $e->getMessage());
    }
    return ['mentions_restored' => $restored];
}

/**
 * Build unique inbox URL targets for outbound delivery, skipping blocked actors/hosts.
 *
 * @param iterable<array<string,mixed>> $followerRows
 * @param iterable<string> $extraInboxes
 * @return list<string>
 */
/**
 * Bridgy Fed inboxes that must receive public Creates for Bluesky bridging.
 * Never use https://bsky.brid.gy/inbox (404).
 *
 * @return list<string>
 */
function ap_bridgy_priority_inboxes(): array
{
    return [
        'https://bsky.brid.gy/bsky.brid.gy/inbox', // personal — reliably 202s
        'https://bsky.brid.gy/ap/sharedInbox',
    ];
}

/**
 * True when a URL is a Bridgy Fed host (bsky/ap/web/fed.brid.gy).
 */
function ap_is_bridgy_url(string $url): bool
{
    $host = parse_url(trim($url), PHP_URL_HOST);
    if (!is_string($host) || $host === '') {
        return false;
    }
    $host = strtolower($host);
    return $host === 'brid.gy' || str_ends_with($host, '.brid.gy');
}

/**
 * True when URL is Threads (threads.net / threads.com).
 */
function ap_is_threads_url(string $url): bool
{
    $host = parse_url(trim($url), PHP_URL_HOST);
    if (!is_string($host) || $host === '') {
        return false;
    }
    $host = strtolower($host);
    return $host === 'threads.net' || $host === 'www.threads.net'
        || $host === 'threads.com' || $host === 'www.threads.com';
}

/**
 * Human Threads profile URL from AP actor id + username.
 * AP actors are https://threads.net/ap/users/{numeric} (JSON in browsers).
 * Web profiles live at https://www.threads.com/@{username}.
 */
function ap_threads_profile_web_url(string $actorId, ?string $username = null): ?string
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !ap_is_threads_url($actorId)) {
        return null;
    }
    $username = $username !== null ? trim($username) : '';
    if ($username === '' && function_exists('ap_remote_actor_get')) {
        // Try exact + trailing-slash variants Threads often stores
        foreach ([$actorId, $actorId . '/'] as $key) {
            $meta = ap_remote_actor_get($key);
            if (is_array($meta) && trim((string) ($meta['username'] ?? '')) !== '') {
                $username = trim((string) $meta['username']);
                break;
            }
        }
    }
    // Path /ap/users/123 — username from cache only (numeric path ≠ handle)
    if ($username === '' || ctype_digit($username) || str_starts_with(strtolower($username), 'did:')) {
        return null;
    }
    if (function_exists('ap_remote_actor_username_is_placeholder')
        && ap_remote_actor_username_is_placeholder($username)) {
        return null;
    }
    return 'https://www.threads.com/@' . rawurlencode($username);
}

/**
 * Bluesky web profile URL for a Bridgy actor, or null if not Bridgy Bluesky.
 * Prefer handle (alice.bsky.social / custom domain) over raw did:plc.
 */
function ap_bridgy_bsky_profile_web_url(string $actorId, ?string $username = null): ?string
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '') {
        return null;
    }
    $did = null;
    if (preg_match('#^https://bsky\.brid\.gy/ap/(did:[a-z0-9:]+)$#i', $actorId, $m)) {
        $did = strtolower($m[1]);
    } elseif (preg_match('#^did:[a-z0-9:]+$#i', $actorId)) {
        $did = strtolower($actorId);
    }
    if ($did === null) {
        return null;
    }
    $username = $username !== null ? trim($username) : '';
    if ($username === '' && function_exists('ap_remote_actor_get')) {
        $meta = ap_remote_actor_get($actorId);
        if (is_array($meta)) {
            $username = trim((string) ($meta['username'] ?? ''));
        }
    }
    // Prefer human handle when it isn't a Bridgy placeholder / DID
    if (
        $username !== ''
        && str_contains($username, '.')
        && !str_ends_with(strtolower($username), '.brid.gy')
        && !str_starts_with(strtolower($username), 'did:')
        && !(function_exists('ap_remote_actor_username_is_placeholder')
            && ap_remote_actor_username_is_placeholder($username))
    ) {
        return 'https://bsky.app/profile/' . rawurlencode($username);
    }
    // did:plc:… — keep colons (bsky.app expects them unencoded)
    return 'https://bsky.app/profile/' . $did;
}

/**
 * Return the Bluesky handle associated with a local profile, when known.
 * This is intentionally conservative: the HTML profile uses it only for an
 * additive, client-side count lookup and falls back to local AP counts.
 */
function ap_profile_bsky_handle(string $actorKey, array $profile = []): ?string
{
    $actorKey = strtolower(trim($actorKey));
    // Bridgy's current Bluesky identity for the primary local account.
    if ($actorKey === 'cmdr_nova') {
        return 'cmdr-nova.mkultra.monster.ap.brid.gy';
    }
    $attachments = is_array($profile['attachment'] ?? null) ? $profile['attachment'] : [];
    foreach ($attachments as $att) {
        if (!is_array($att)) {
            continue;
        }
        $value = trim((string) ($att['value'] ?? ''));
        if ($value === '') {
            continue;
        }
        if (preg_match('#(?:https?://)?(?:www\.)?bsky\.app/profile/([^/?#\s]+)#i', $value, $m)) {
            $handle = trim($m[1]);
            if ($handle !== '' && !str_starts_with(strtolower($handle), 'did:')) {
                return $handle;
            }
        }
        if (preg_match('/@([a-z0-9][a-z0-9.-]*\.[a-z]{2,})/i', $value, $m)) {
            return strtolower($m[1]);
        }
    }
    return null;
}

/**
 * Human-facing post URL for a remote object (esp. Bridgy → bsky.app).
 * Bridgy convert/ap/at://… URLs are ActivityPub JSON — browsers show pretty-print junk.
 */
function ap_remote_object_web_url(string $objectId, mixed $urlField = null): string
{
    $objectId = trim($objectId);
    $candidates = [];

    // Prefer AS2 url field(s) when present
    if (is_string($urlField) && str_starts_with($urlField, 'https://')) {
        $candidates[] = $urlField;
    } elseif (is_array($urlField)) {
        foreach ($urlField as $u) {
            if (is_string($u) && str_starts_with($u, 'https://')) {
                $candidates[] = $u;
            } elseif (is_array($u) && isset($u['href']) && is_string($u['href']) && str_starts_with($u['href'], 'https://')) {
                $candidates[] = $u['href'];
            }
        }
    }
    if ($objectId !== '' && str_starts_with($objectId, 'https://')) {
        $candidates[] = $objectId;
    }

    foreach ($candidates as $cand) {
        // Bridgy redirect wrapper → unwrap
        if (preg_match('#^https://bsky\.brid\.gy/r/(https://bsky\.app/.+)$#i', $cand, $m)) {
            return $m[1];
        }
        if (str_starts_with($cand, 'https://bsky.app/')) {
            return $cand;
        }
        // convert/ap/at://did:…/app.bsky.feed.post/rkey
        if (preg_match(
            '~^https://bsky\.brid\.gy/convert/ap/at://(did:[^/]+)/app\.bsky\.feed\.post/([A-Za-z0-9]+)(?:[/?#]|$)~i',
            $cand,
            $m
        )) {
            return 'https://bsky.app/profile/' . $m[1] . '/post/' . rawurlencode($m[2]);
        }
        // Also accept at:// embedded without convert prefix
        if (preg_match('~at://(did:[^/]+)/app\.bsky\.feed\.post/([A-Za-z0-9]+)~i', $cand, $m)) {
            return 'https://bsky.app/profile/' . $m[1] . '/post/' . rawurlencode($m[2]);
        }
        // Threads AP post/actor → author web profile (AP /ap/users/…/post/… is JSON / 404 in browsers)
        if (ap_is_threads_url($cand)) {
            if (preg_match('~^https://(?:www\.)?threads\.(?:net|com)/@([^/?#]+)~i', $cand, $m)) {
                return 'https://www.threads.com/@' . rawurlencode(rawurldecode($m[1]));
            }
            if (preg_match('~^https://(?:www\.)?threads\.net/ap/users/(\d+)~i', $cand, $m)) {
                $actorAp = 'https://threads.net/ap/users/' . $m[1];
                $web = ap_threads_profile_web_url($actorAp);
                if (is_string($web) && $web !== '') {
                    return $web;
                }
            }
        }
    }

    return $objectId !== '' ? $objectId : '';
}

function ap_delivery_targets_filtered(iterable $followerRows, iterable $extraInboxes = []): array
{
    $targets = [];
    foreach ($followerRows as $f) {
        if (!is_array($f)) {
            continue;
        }
        $actorId = isset($f['actor_id']) ? (string) $f['actor_id'] : '';
        if ($actorId !== '' && ap_is_blocked_actor($actorId)) {
            continue;
        }
        $host = strtolower((string) ($f['host'] ?? parse_url($actorId, PHP_URL_HOST) ?: ''));
        $personal = isset($f['inbox']) && is_string($f['inbox']) ? $f['inbox'] : null;
        $shared = isset($f['shared_inbox']) && is_string($f['shared_inbox']) ? $f['shared_inbox'] : null;
        // Bridgy Fed: personal inbox is what actually accepts our signed Creates;
        // shared is secondary. Generic servers prefer sharedInbox when present.
        if ($host !== '' && (str_ends_with($host, 'brid.gy') || $host === 'brid.gy')) {
            $inbox = $personal ?: $shared;
        } else {
            $inbox = $shared ?: $personal;
        }
        if (!is_string($inbox) || !str_starts_with($inbox, 'https://')) {
            continue;
        }
        if (ap_is_blocked_inbox($inbox)) {
            continue;
        }
        $targets[$inbox] = true;
    }
    foreach ($extraInboxes as $inbox) {
        if (!is_string($inbox) || !str_starts_with($inbox, 'https://')) {
            continue;
        }
        if (ap_is_blocked_inbox($inbox)) {
            continue;
        }
        $targets[$inbox] = true;
    }
    return array_keys($targets);
}

/** Whether an events/mentions row should be hidden from admin UI due to blocks. */
function ap_row_is_blocked(?string $actorId, ?string $host = null): bool
{
    if ($actorId && ap_is_blocked_actor($actorId)) {
        return true;
    }
    if ($host && ap_is_blocked_host($host)) {
        return true;
    }
    return false;
}

/* ----------------- Owner helpers (Slice D multi-user) ----------------- */

/**
 * True when this request is bound to a VAAK / OAuth user session.
 * When set, we must NEVER silently fall back to cmdr_nova (hijack risk).
 */
function ap_db_session_bound(): bool
{
    if (!empty($GLOBALS['vaak_owner_id']) && (int) $GLOBALS['vaak_owner_id'] > 0) {
        return true;
    }
    if (!empty($GLOBALS['vaak_user']) && is_array($GLOBALS['vaak_user'])) {
        return true;
    }
    if (!empty($GLOBALS['vaak_actor_key']) || !empty($GLOBALS['vaak_actor_id'])) {
        return true;
    }
    return false;
}

/**
 * Session/token owner id, or 0 if unbound / unusable.
 * Does not invent cmdr_nova.
 */
function ap_db_session_owner_user_id(): int
{
    if (!empty($GLOBALS['vaak_owner_id'])) {
        $id = (int) $GLOBALS['vaak_owner_id'];
        if ($id > 0) {
            return $id;
        }
    }
    if (!empty($GLOBALS['vaak_user']['id'])) {
        $id = (int) $GLOBALS['vaak_user']['id'];
        if ($id > 0) {
            return $id;
        }
    }
    return 0;
}

/**
 * Prefer request-bound VAAK / OAuth token user.
 * Session-bound but missing id → 0 (fail closed).
 * No session (cron / unsigned inbox helpers) → legacy cmdr_nova default.
 */
function ap_db_default_owner_user_id(): int
{
    $sessionId = ap_db_session_owner_user_id();
    if ($sessionId > 0) {
        return $sessionId;
    }
    if (ap_db_session_bound()) {
        error_log('[ap-db] session bound but owner user id missing — refusing cmdr_nova fallback');
        return 0;
    }
    return ap_db_cmdr_nova_user_id();
}

/**
 * Mastodon API owner for the current request (token-bound user).
 * Same fail-closed rules as ap_db_default_owner_user_id().
 */
function ap_db_masto_owner_user_id(): int
{
    return ap_db_default_owner_user_id();
}

/** cmdr_nova's ap_users.id (legacy backfill / default inbox recipient / NULL token). */
function ap_db_cmdr_nova_user_id(): int
{
    static $cached = null;
    if ($cached !== null) {
        return $cached;
    }
    try {
        $row = ap_db()->query("SELECT id FROM ap_users WHERE actor_key = 'cmdr_nova' LIMIT 1")->fetch();
        $cached = (int) ($row['id'] ?? 0);
    } catch (Throwable $e) {
        $cached = 0;
    }
    if ($cached < 1) {
        $cached = 1;
    }
    return $cached;
}

/** Count of non-disabled local ap_users (fallback 1). */
function ap_db_enabled_user_count(): int
{
    try {
        $n = (int) ap_db()->query('SELECT COUNT(*) FROM ap_users WHERE disabled_at IS NULL')->fetchColumn();
        return $n > 0 ? $n : 1;
    } catch (Throwable $e) {
        return 1;
    }
}

/**
 * Resolve ap_users.id for a local actor IRI / key.
 * Unknown / empty → 0 (never invent cmdr_nova; callers that need the
 * operator account must call ap_db_cmdr_nova_user_id() explicitly).
 */
function ap_db_owner_user_id_for_actor(?string $actorIdOrKey): int
{
    $raw = trim((string) $actorIdOrKey);
    if ($raw === '') {
        return 0;
    }
    $actorId = rtrim($raw, '/');
    $key = '';
    if (preg_match('#^https://mkultra\.monster/users/([A-Za-z0-9_]+)$#', $actorId, $m)) {
        $key = strtolower($m[1]);
    } elseif (preg_match('/^[A-Za-z0-9_]+$/', $raw)) {
        $key = strtolower($raw);
        $actorId = 'https://mkultra.monster/users/' . $key;
    }
    try {
        if ($key !== '') {
            $st = ap_db()->prepare(
                'SELECT id FROM ap_users WHERE lower(actor_key) = ? OR actor_id = ? OR actor_id = ? LIMIT 1'
            );
            $st->execute([$key, $actorId, $actorId . '/']);
        } else {
            $st = ap_db()->prepare(
                'SELECT id FROM ap_users WHERE actor_id = ? OR actor_id = ? LIMIT 1'
            );
            $st->execute([$actorId, $actorId . '/']);
        }
        return (int) ($st->fetchColumn() ?: 0);
    } catch (Throwable $e) {
        return 0;
    }
}

/**
 * Actor IRI for an ap_users.id.
 * Unknown / invalid id → '' (never invent cmdr_nova).
 */
function ap_db_owner_actor_id_for_user_id(int $ownerUserId): string
{
    if ($ownerUserId < 1) {
        return '';
    }
    try {
        $st = ap_db()->prepare('SELECT actor_id FROM ap_users WHERE id = ? LIMIT 1');
        $st->execute([$ownerUserId]);
        return rtrim((string) ($st->fetchColumn() ?: ''), '/');
    } catch (Throwable $e) {
        return '';
    }
}

/* ----------------- Mutes (per-user; hide timeline/notifs; keep follows) ----------------- */

/**
 * @return list<array{owner_user_id:int,actor_id:string,created_at:string,notifications:int,host:?string}>
 */
function ap_mutes_list(int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return [];
    }
    $st = ap_db()->prepare(
        'SELECT * FROM ap_mutes WHERE owner_user_id = ? ORDER BY created_at DESC'
    );
    $st->execute([$ownerUserId]);
    return $st->fetchAll() ?: [];
}

/** @return array<string,bool> */
function ap_mutes_set_cached(int $ownerUserId, bool $refresh = false): array
{
    static $cache = [];
    if ($ownerUserId < 1) {
        if ($refresh) {
            $cache = [];
        }
        return [];
    }
    if ($refresh) {
        unset($cache[$ownerUserId]);
    }
    if (!isset($cache[$ownerUserId])) {
        $cache[$ownerUserId] = [];
        foreach (ap_mutes_list($ownerUserId) as $row) {
            $id = rtrim((string) ($row['actor_id'] ?? ''), '/');
            if ($id !== '') {
                $cache[$ownerUserId][$id] = true;
                $cache[$ownerUserId][$id . '/'] = true;
            }
        }
    }
    return $cache[$ownerUserId];
}

function ap_mutes_cache_clear(?int $ownerUserId = null): void
{
    if ($ownerUserId === null || $ownerUserId < 1) {
        ap_mutes_set_cached(0, true);
        return;
    }
    ap_mutes_set_cached($ownerUserId, true);
}

function ap_is_muted_actor(?string $actorId, int $ownerUserId): bool
{
    if ($actorId === null || $actorId === '' || $ownerUserId < 1) {
        return false;
    }
    $actorId = rtrim($actorId, '/');
    $set = ap_mutes_set_cached($ownerUserId);
    return !empty($set[$actorId]) || !empty($set[$actorId . '/']);
}

/**
 * Mute a remote actor (local only — not federated).
 *
 * @return array{ok:bool,error?:string,actor_id?:string,already?:bool}
 */
function ap_mute_upsert(string $actorId, bool $notifications, int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing owner user.'];
    }
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://')) {
        return ['ok' => false, 'error' => 'Mute needs an https actor URL.'];
    }
    try {
        $st = ap_db()->prepare('SELECT actor_id FROM ap_users WHERE id = ? LIMIT 1');
        $st->execute([$ownerUserId]);
        $own = rtrim((string) ($st->fetch()['actor_id'] ?? ''), '/');
        if ($own !== '' && ($actorId === $own || str_starts_with($actorId, $own))) {
            return ['ok' => false, 'error' => 'Cannot mute yourself.'];
        }
    } catch (Throwable $e) {
        // fall through
    }
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : null;
    $now = ap_db_now();
    if (ap_is_muted_actor($actorId, $ownerUserId)) {
        ap_db()->prepare(
            'UPDATE ap_mutes SET notifications = ?
             WHERE owner_user_id = ? AND (actor_id = ? OR actor_id = ?)'
        )->execute([$notifications ? 1 : 0, $ownerUserId, $actorId, $actorId . '/']);
        ap_mutes_cache_clear($ownerUserId);
        return ['ok' => true, 'actor_id' => $actorId, 'already' => true];
    }
    ap_db()->prepare(
        'INSERT INTO ap_mutes (owner_user_id, actor_id, created_at, notifications, host)
         VALUES (?, ?, ?, ?, ?)'
    )->execute([$ownerUserId, $actorId, $now, $notifications ? 1 : 0, $host]);
    ap_mutes_cache_clear($ownerUserId);
    return ['ok' => true, 'actor_id' => $actorId];
}

/**
 * @return array{ok:bool,error?:string,actor_id?:string}
 */
function ap_unmute(string $actorId, int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing owner user.'];
    }
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '') {
        return ['ok' => false, 'error' => 'Missing actor.'];
    }
    $st = ap_db()->prepare(
        'DELETE FROM ap_mutes WHERE owner_user_id = ? AND (actor_id = ? OR actor_id = ?)'
    );
    $st->execute([$ownerUserId, $actorId, $actorId . '/']);
    ap_mutes_cache_clear($ownerUserId);
    if ($st->rowCount() < 1) {
        return ['ok' => false, 'error' => 'Not muted.'];
    }
    return ['ok' => true, 'actor_id' => $actorId];
}

/* ----------------- Anti-AI actor marks (cached-post heuristic) ----------------- */

/** Regex of slang that anti-AI posters tend to lean on. */
function ap_anti_ai_keyword_regex(): string
{
    // Word-ish boundaries; keep list tight to avoid false positives.
    return '/\b(?:'
        . 'slop|clankers?|clanka|'
        . 'ai[\s\-]?slop|generative[\s\-]?slop|'
        . 'prompt(?:ing)?[\s\-]?bros?|ai[\s\-]?bros?'
        . ')\b/iu';
}

function ap_text_looks_anti_ai(string $text): bool
{
    $text = trim(html_entity_decode(strip_tags($text), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
    if ($text === '') {
        return false;
    }
    return (bool) preg_match(ap_anti_ai_keyword_regex(), $text);
}

/** Fast lookup: actor currently carries the anti-AI mark. */
function ap_anti_ai_actor_is_marked(string $actorId, bool $bypassCache = false): bool
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://')) {
        return false;
    }
    // Never mark local instance accounts
    if (preg_match('#^https://mkultra\.monster/users/[A-Za-z0-9_]+$#', $actorId)) {
        return false;
    }
    static $memo = [];
    if (!$bypassCache && array_key_exists($actorId, $memo)) {
        return $memo[$actorId];
    }
    try {
        $st = ap_db()->prepare('SELECT marked FROM ap_anti_ai_actors WHERE actor_id = ? OR actor_id = ? LIMIT 1');
        $st->execute([$actorId, $actorId . '/']);
        $row = $st->fetch();
        return $memo[$actorId] = is_array($row) && !empty($row['marked']);
    } catch (Throwable $e) {
        return $memo[$actorId] = false;
    }
}

/**
 * Record a keyword hit for a remote Create (idempotent per object_id).
 *
 * @return array{ok:bool,inserted?:bool}
 */
function ap_anti_ai_hit_record(string $actorId, string $objectId, ?string $hitAt = null): array
{
    $actorId = rtrim(trim($actorId), '/');
    $objectId = rtrim(trim($objectId), '/');
    if ($actorId === '' || $objectId === '' || !str_starts_with($actorId, 'https://')) {
        return ['ok' => false];
    }
    if (preg_match('#^https://mkultra\.monster/users/[A-Za-z0-9_]+$#', $actorId)) {
        return ['ok' => false];
    }
    $hitAt = $hitAt !== null && $hitAt !== '' ? $hitAt : ap_db_now();
    try {
        $st = ap_db()->prepare(
            'INSERT INTO ap_anti_ai_hits (actor_id, object_id, hit_at) VALUES (?, ?, ?)
             ON CONFLICT(actor_id, object_id) DO NOTHING'
        );
        $st->execute([$actorId, $objectId, $hitAt]);
        return ['ok' => true, 'inserted' => $st->rowCount() > 0];
    } catch (Throwable $e) {
        return ['ok' => false];
    }
}

/**
 * Recompute mark state for one actor (or all with hits).
 * Mark when distinct hits in the retention window >= $threshold.
 * Clear when marked but recent hits drop below threshold (usage fell off).
 *
 * @return array{ok:bool,marked?:bool,hit_count?:int,changed?:bool}
 */
function ap_anti_ai_actor_recompute(
    string $actorId,
    int $threshold = 3,
    int $retentionDays = 90
): array {
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '') {
        return ['ok' => false];
    }
    $threshold = max(2, min(20, $threshold));
    $retentionDays = max(30, min(365, $retentionDays));
    $cutoff = gmdate('c', time() - ($retentionDays * 86400));
    $now = ap_db_now();
    try {
        $db = ap_db();
        $db->prepare('DELETE FROM ap_anti_ai_hits WHERE actor_id = ? AND hit_at < ?')
            ->execute([$actorId, $cutoff]);
        $st = $db->prepare(
            'SELECT COUNT(*) AS c, MAX(hit_at) AS last_hit
             FROM ap_anti_ai_hits WHERE actor_id = ?'
        );
        $st->execute([$actorId]);
        $row = $st->fetch() ?: [];
        $count = (int) ($row['c'] ?? 0);
        $lastHit = isset($row['last_hit']) && is_string($row['last_hit']) ? $row['last_hit'] : null;
        $shouldMark = $count >= $threshold;

        $prev = $db->prepare('SELECT marked, marked_at, cleared_at FROM ap_anti_ai_actors WHERE actor_id = ?');
        $prev->execute([$actorId]);
        $old = $prev->fetch();
        $wasMarked = is_array($old) && !empty($old['marked']);
        $markedAt = is_array($old) && !empty($old['marked_at']) ? (string) $old['marked_at'] : null;
        $clearedAt = is_array($old) && !empty($old['cleared_at']) ? (string) $old['cleared_at'] : null;

        if ($shouldMark) {
            if ($markedAt === null || !$wasMarked) {
                $markedAt = $now;
            }
            $clearedAt = null;
        } elseif ($wasMarked) {
            $clearedAt = $now;
            // Keep marked_at history for debugging; mark flag goes off
        }

        $db->prepare(
            'INSERT INTO ap_anti_ai_actors
               (actor_id, hit_count, marked, marked_at, last_hit_at, cleared_at, updated_at)
             VALUES (?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(actor_id) DO UPDATE SET
               hit_count = excluded.hit_count,
               marked = excluded.marked,
               marked_at = excluded.marked_at,
               last_hit_at = excluded.last_hit_at,
               cleared_at = excluded.cleared_at,
               updated_at = excluded.updated_at'
        )->execute([
            $actorId,
            $count,
            $shouldMark ? 1 : 0,
            $markedAt,
            $lastHit,
            $clearedAt,
            $now,
        ]);

        return [
            'ok' => true,
            'marked' => $shouldMark,
            'hit_count' => $count,
            'changed' => $wasMarked !== $shouldMark,
        ];
    } catch (Throwable $e) {
        return ['ok' => false];
    }
}

/**
 * Scan cached Create events for anti-AI slang and refresh actor marks.
 *
 * @return array{
 *   ok:bool,
 *   scanned:int,
 *   new_hits:int,
 *   actors_touched:int,
 *   newly_marked:int,
 *   cleared:int,
 *   marked_total:int
 * }
 */
function ap_anti_ai_scan_cached_posts(
    int $threshold = 3,
    int $retentionDays = 90,
    int $eventLimit = 50000
): array {
    $threshold = max(2, min(20, $threshold));
    $retentionDays = max(30, min(365, $retentionDays));
    $eventLimit = max(1000, min(200000, $eventLimit));
    $out = [
        'ok' => true,
        'scanned' => 0,
        'new_hits' => 0,
        'actors_touched' => 0,
        'newly_marked' => 0,
        'cleared' => 0,
        'marked_total' => 0,
    ];
    $touched = [];
    try {
        $st = ap_db()->prepare(
            "SELECT actor_id, object_id, created_at, summary
             FROM events
             WHERE type = 'Create'
               AND summary IS NOT NULL AND summary != ''
               AND actor_id IS NOT NULL AND actor_id != ''
               AND object_id IS NOT NULL AND object_id != ''
             ORDER BY id DESC
             LIMIT ?"
        );
        $st->bindValue(1, $eventLimit, PDO::PARAM_INT);
        $st->execute();
        while ($row = $st->fetch()) {
            $out['scanned']++;
            $actorId = rtrim((string) ($row['actor_id'] ?? ''), '/');
            $objectId = rtrim((string) ($row['object_id'] ?? ''), '/');
            $summary = (string) ($row['summary'] ?? '');
            if ($actorId === '' || $objectId === '' || !ap_text_looks_anti_ai($summary)) {
                continue;
            }
            $res = ap_anti_ai_hit_record(
                $actorId,
                $objectId,
                isset($row['created_at']) ? (string) $row['created_at'] : null
            );
            if (!empty($res['ok'])) {
                $touched[$actorId] = true;
                if (!empty($res['inserted'])) {
                    $out['new_hits']++;
                }
            }
        }

        // Also recompute every currently marked actor (so decay works even if
        // they have no matching Creates left in the events window).
        foreach (ap_db()->query('SELECT actor_id FROM ap_anti_ai_actors WHERE marked = 1')->fetchAll() as $r) {
            $aid = rtrim((string) ($r['actor_id'] ?? ''), '/');
            if ($aid !== '') {
                $touched[$aid] = true;
            }
        }
        // Anyone with residual hits
        foreach (ap_db()->query('SELECT DISTINCT actor_id FROM ap_anti_ai_hits')->fetchAll() as $r) {
            $aid = rtrim((string) ($r['actor_id'] ?? ''), '/');
            if ($aid !== '') {
                $touched[$aid] = true;
            }
        }

        $out['actors_touched'] = count($touched);
        foreach (array_keys($touched) as $aid) {
            $prevMarked = ap_anti_ai_actor_is_marked($aid, true);
            $r = ap_anti_ai_actor_recompute($aid, $threshold, $retentionDays);
            if (empty($r['ok'])) {
                continue;
            }
            // Refresh memo after write
            ap_anti_ai_actor_is_marked($aid, true);
            $nowMarked = !empty($r['marked']);
            if (!$prevMarked && $nowMarked) {
                $out['newly_marked']++;
            } elseif ($prevMarked && !$nowMarked) {
                $out['cleared']++;
            }
        }

        $out['marked_total'] = (int) ap_db()->query(
            'SELECT COUNT(*) FROM ap_anti_ai_actors WHERE marked = 1'
        )->fetchColumn();
    } catch (Throwable $e) {
        $out['ok'] = false;
    }
    return $out;
}

/**
 * True when mention/content text clearly addresses $localActorId
 * (@username, actor URL, or acct:user@host).
 */
function ap_content_addresses_local_actor(string $content, string $localActorId): bool
{
    $localActorId = rtrim(trim($localActorId), '/');
    if ($localActorId === '' || $content === '') {
        return false;
    }
    if (str_contains($content, $localActorId)) {
        return true;
    }
    $key = basename($localActorId);
    if ($key === '' || !preg_match('/^[A-Za-z0-9_]+$/', $key)) {
        return false;
    }
    $host = parse_url($localActorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : 'mkultra.monster';
    $plain = html_entity_decode(strip_tags($content), ENT_QUOTES | ENT_HTML5, 'UTF-8');
    if ($plain === '') {
        return false;
    }
    $keyQ = preg_quote($key, '/');
    $hostQ = preg_quote($host, '/');
    if (preg_match('/(^|[^A-Za-z0-9_])@' . $keyQ . '(@' . $hostQ . ')?\b/iu', $plain)) {
        return true;
    }
    if (preg_match('/acct:' . $keyQ . '@' . $hostQ . '\b/iu', $plain)) {
        return true;
    }
    return false;
}

/* ----------------- Post subscriptions (opt-in Create notifications) ----------------- */

function ap_post_subscription_owner_user_id(?int $ownerUserId = null): int
{
    if ($ownerUserId !== null && $ownerUserId > 0) {
        return $ownerUserId;
    }
    return ap_db_default_owner_user_id();
}

/** Whether the owner is subscribed to Creates from $targetActorId. */
function ap_post_subscription_is(string $targetActorId, ?int $ownerUserId = null): bool
{
    $targetActorId = rtrim(trim($targetActorId), '/');
    $ownerUserId = ap_post_subscription_owner_user_id($ownerUserId);
    if ($targetActorId === '' || $ownerUserId < 1 || !str_starts_with($targetActorId, 'https://')) {
        return false;
    }
    try {
        $st = ap_db()->prepare(
            'SELECT 1 FROM ap_post_subscriptions
             WHERE owner_user_id = ? AND (target_actor_id = ? OR target_actor_id = ?)
             LIMIT 1'
        );
        $st->execute([$ownerUserId, $targetActorId, $targetActorId . '/']);
        return (bool) $st->fetchColumn();
    } catch (Throwable $e) {
        return false;
    }
}

/**
 * Subscribe or unsubscribe the owner to Creates from $targetActorId.
 *
 * @return array{ok:bool,error?:string,actor_id?:string,on?:bool,already?:bool}
 */
function ap_post_subscription_set(string $targetActorId, bool $on, ?int $ownerUserId = null): array
{
    $targetActorId = rtrim(trim($targetActorId), '/');
    $ownerUserId = ap_post_subscription_owner_user_id($ownerUserId);
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing owner user.'];
    }
    if ($targetActorId === '' || !str_starts_with($targetActorId, 'https://')) {
        return ['ok' => false, 'error' => 'Need an https actor URL.'];
    }
    try {
        $st = ap_db()->prepare('SELECT actor_id FROM ap_users WHERE id = ? LIMIT 1');
        $st->execute([$ownerUserId]);
        $own = rtrim((string) ($st->fetch()['actor_id'] ?? ''), '/');
        if ($own !== '' && $targetActorId === $own) {
            return ['ok' => false, 'error' => 'Cannot subscribe to your own posts.'];
        }
    } catch (Throwable $e) {
        // fall through
    }
    $already = ap_post_subscription_is($targetActorId, $ownerUserId);
    if ($on) {
        if ($already) {
            return ['ok' => true, 'actor_id' => $targetActorId, 'on' => true, 'already' => true];
        }
        try {
            ap_db()->prepare(
                'INSERT INTO ap_post_subscriptions (owner_user_id, target_actor_id, created_at)
                 VALUES (?, ?, ?)'
            )->execute([$ownerUserId, $targetActorId, ap_db_now()]);
        } catch (Throwable $e) {
            return ['ok' => false, 'error' => 'Could not subscribe.'];
        }
        return ['ok' => true, 'actor_id' => $targetActorId, 'on' => true];
    }
    if (!$already) {
        return ['ok' => true, 'actor_id' => $targetActorId, 'on' => false, 'already' => true];
    }
    try {
        ap_db()->prepare(
            'DELETE FROM ap_post_subscriptions
             WHERE owner_user_id = ? AND (target_actor_id = ? OR target_actor_id = ?)'
        )->execute([$ownerUserId, $targetActorId, $targetActorId . '/']);
    } catch (Throwable $e) {
        return ['ok' => false, 'error' => 'Could not unsubscribe.'];
    }
    return ['ok' => true, 'actor_id' => $targetActorId, 'on' => false];
}

/**
 * @return list<array{owner_user_id:int,target_actor_id:string,created_at:string}>
 */
function ap_post_subscription_list(?int $ownerUserId = null): array
{
    $ownerUserId = ap_post_subscription_owner_user_id($ownerUserId);
    if ($ownerUserId < 1) {
        return [];
    }
    try {
        $st = ap_db()->prepare(
            'SELECT owner_user_id, target_actor_id, created_at
             FROM ap_post_subscriptions
             WHERE owner_user_id = ?
             ORDER BY created_at DESC, target_actor_id ASC'
        );
        $st->execute([$ownerUserId]);
        $out = [];
        foreach ($st->fetchAll() as $row) {
            if (!is_array($row)) {
                continue;
            }
            $out[] = [
                'owner_user_id' => (int) ($row['owner_user_id'] ?? 0),
                'target_actor_id' => rtrim((string) ($row['target_actor_id'] ?? ''), '/'),
                'created_at' => (string) ($row['created_at'] ?? ''),
            ];
        }
        return $out;
    } catch (Throwable $e) {
        return [];
    }
}

/* ----------------- Personal blocks (per-user; timeline hide only) ----------------- */

/**
 * @return list<array<string,mixed>>
 */
function ap_user_blocks_list(int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return [];
    }
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM ap_user_blocks WHERE owner_user_id = ? ORDER BY created_at DESC, id DESC'
        );
        $st->execute([$ownerUserId]);
        return $st->fetchAll() ?: [];
    } catch (Throwable $e) {
        error_log('[ap-db] user_blocks_list: ' . $e->getMessage());
        return [];
    }
}

/** @return list<array<string,mixed>> */
function ap_user_blocks_list_cached(int $ownerUserId, bool $refresh = false): array
{
    static $cache = [];
    if ($ownerUserId < 1) {
        if ($refresh) {
            $cache = [];
        }
        return [];
    }
    if ($refresh) {
        unset($cache[$ownerUserId]);
    }
    if (!isset($cache[$ownerUserId])) {
        $cache[$ownerUserId] = ap_user_blocks_list($ownerUserId);
    }
    return $cache[$ownerUserId];
}

function ap_user_blocks_cache_clear(?int $ownerUserId = null): void
{
    if ($ownerUserId === null || $ownerUserId < 1) {
        ap_user_blocks_list_cached(0, true);
        return;
    }
    ap_user_blocks_list_cached($ownerUserId, true);
}

function ap_user_is_blocked(?string $actorId, ?string $host, int $ownerUserId): bool
{
    if ($ownerUserId < 1) {
        return false;
    }
    $actorId = $actorId !== null ? rtrim($actorId, '/') : null;
    $host = $host !== null && $host !== '' ? strtolower($host) : null;
    if (($host === null || $host === '') && is_string($actorId) && $actorId !== '') {
        $h = parse_url($actorId, PHP_URL_HOST);
        $host = is_string($h) ? strtolower($h) : null;
    }
    foreach (ap_user_blocks_list_cached($ownerUserId) as $b) {
        $scope = (string) ($b['scope'] ?? '');
        $value = (string) ($b['value'] ?? '');
        if ($scope === 'actor' && $actorId !== null && $actorId !== '') {
            $v = rtrim($value, '/');
            if ($v !== '' && ($actorId === $v || $actorId . '/' === $v || $actorId === $v . '/')) {
                return true;
            }
        } elseif ($scope === 'domain' && $host !== null && $host !== '') {
            $blocked = strtolower($value);
            if ($blocked !== '' && ($host === $blocked || str_ends_with($host, '.' . $blocked))) {
                return true;
            }
        }
    }
    return false;
}

/** Return the matching personal actor/domain block row, if present. */
function ap_user_block_find(?string $actorId, ?string $host, int $ownerUserId): ?array
{
    if ($ownerUserId < 1) {
        return null;
    }
    $actorId = $actorId !== null ? rtrim($actorId, '/') : null;
    $host = $host !== null && $host !== '' ? strtolower($host) : null;
    if (($host === null || $host === '') && is_string($actorId) && $actorId !== '') {
        $h = parse_url($actorId, PHP_URL_HOST);
        $host = is_string($h) ? strtolower($h) : null;
    }
    foreach (ap_user_blocks_list_cached($ownerUserId) as $row) {
        $scope = (string) ($row['scope'] ?? '');
        $value = (string) ($row['value'] ?? '');
        if ($scope === 'actor' && $actorId !== null && $actorId !== '') {
            $value = rtrim($value, '/');
            if ($value !== '' && $actorId === $value) {
                return $row;
            }
        } elseif ($scope === 'domain' && $host !== null && $host !== '') {
            $value = strtolower($value);
            if ($value !== '' && ($host === $value || str_ends_with($host, '.' . $value))) {
                return $row;
            }
        }
    }
    return null;
}

/**
 * Personal block — hides from this user's timelines only (no inbox / follow side effects).
 *
 * @return array{ok:bool,error?:string,id?:int,scope?:string,value?:string,already?:bool}
 */
function ap_user_block_add(
    int $ownerUserId,
    string $scope,
    string $value,
    string $kind = 'block',
    ?string $reason = null
): array {
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing owner user.'];
    }
    $scope = $scope === 'domain' ? 'domain' : 'actor';
    $kind = $kind === 'suspend' ? 'suspend' : 'block';
    if ($scope === 'domain') {
        $norm = ap_block_normalize_domain($value);
        if ($norm === null) {
            return ['ok' => false, 'error' => 'Invalid domain (use example.com — not mkultra.monster).'];
        }
        $value = $norm;
    } else {
        $norm = ap_block_normalize_actor($value);
        if ($norm === null) {
            return ['ok' => false, 'error' => 'Invalid actor URL (https://… only; resolve handles before calling).'];
        }
        $value = $norm;
        try {
            $st = ap_db()->prepare('SELECT actor_id FROM ap_users WHERE id = ? LIMIT 1');
            $st->execute([$ownerUserId]);
            $own = rtrim((string) ($st->fetch()['actor_id'] ?? ''), '/');
            if ($own !== '' && rtrim($value, '/') === $own) {
                return ['ok' => false, 'error' => 'Cannot block yourself.'];
            }
        } catch (Throwable $e) {
            // fall through
        }
    }
    $reason = $reason !== null ? mb_substr(trim(ap_fix_utf8($reason)), 0, 500) : null;
    if ($reason === '') {
        $reason = null;
    }
    $now = ap_db_now();
    try {
        $db = ap_db();
        $db->prepare(
            'INSERT INTO ap_user_blocks (owner_user_id, scope, value, kind, reason, created_at)
             VALUES (?, ?, ?, ?, ?, ?)
             ON CONFLICT(owner_user_id, scope, value) DO UPDATE SET
               kind = excluded.kind,
               reason = excluded.reason'
        )->execute([$ownerUserId, $scope, $value, $kind, $reason, $now]);
        ap_user_blocks_cache_clear($ownerUserId);
        $idRow = $db->prepare(
            'SELECT id FROM ap_user_blocks WHERE owner_user_id = ? AND scope = ? AND value = ?'
        );
        $idRow->execute([$ownerUserId, $scope, $value]);
        return [
            'ok' => true,
            'id' => (int) ($idRow->fetch()['id'] ?? 0),
            'scope' => $scope,
            'value' => $value,
        ];
    } catch (Throwable $e) {
        error_log('[ap-db] user_block_add: ' . $e->getMessage());
        return ['ok' => false, 'error' => 'Could not save personal block.'];
    }
}

/**
 * @return array{ok:bool,error?:string,scope?:string,value?:string}
 */
function ap_user_block_remove(int $ownerUserId, int $id): array
{
    if ($ownerUserId < 1 || $id < 1) {
        return ['ok' => false, 'error' => 'Missing block id.'];
    }
    $db = ap_db();
    $st = $db->prepare('SELECT * FROM ap_user_blocks WHERE id = ? AND owner_user_id = ?');
    $st->execute([$id, $ownerUserId]);
    $row = $st->fetch();
    if (!is_array($row)) {
        return ['ok' => false, 'error' => 'Block not found.'];
    }
    $del = $db->prepare('DELETE FROM ap_user_blocks WHERE id = ? AND owner_user_id = ?');
    $del->execute([$id, $ownerUserId]);
    ap_user_blocks_cache_clear($ownerUserId);
    return [
        'ok' => true,
        'scope' => (string) ($row['scope'] ?? ''),
        'value' => (string) ($row['value'] ?? ''),
    ];
}

/**
 * Hide from timelines/notifications: server block OR user mute OR personal block.
 */
function ap_row_is_hidden(?string $actorId, ?string $host = null, ?int $ownerUserId = null): bool
{
    if (ap_row_is_blocked($actorId, $host)) {
        return true;
    }
    if (ap_is_globally_muted_actor($actorId, $host)) {
        return true;
    }
    if ($ownerUserId === null || $ownerUserId < 1) {
        return false;
    }
    if ($actorId !== null && $actorId !== '' && ap_is_muted_actor($actorId, $ownerUserId)) {
        return true;
    }
    return ap_user_is_blocked($actorId, $host, $ownerUserId);
}

/* ----------------- Muted words / phrases (per-user timeline filter) ----------------- */

/**
 * @return list<array{id:int,owner_user_id:int,phrase:string,created_at:string,note:?string}>
 */
function ap_muted_words_list(int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return [];
    }
    try {
        $st = ap_db()->prepare(
            'SELECT id, owner_user_id, phrase, created_at, note FROM ap_muted_words
             WHERE owner_user_id = ? ORDER BY created_at DESC, id DESC'
        );
        $st->execute([$ownerUserId]);
        return $st->fetchAll() ?: [];
    } catch (Throwable $e) {
        error_log('[ap-db] muted_words_list: ' . $e->getMessage());
        return [];
    }
}

/**
 * Cached lowercase phrases for fast substring checks.
 *
 * @return list<string>
 */
function ap_muted_words_phrases_cached(int $ownerUserId, bool $refresh = false): array
{
    static $cache = [];
    if ($ownerUserId < 1) {
        if ($refresh) {
            $cache = [];
        }
        return [];
    }
    if ($refresh) {
        unset($cache[$ownerUserId]);
    }
    if (!isset($cache[$ownerUserId])) {
        $phrases = [];
        foreach (ap_muted_words_list($ownerUserId) as $row) {
            $p = mb_strtolower(trim((string) ($row['phrase'] ?? '')), 'UTF-8');
            if ($p !== '') {
                $phrases[] = $p;
            }
        }
        $cache[$ownerUserId] = array_values(array_unique($phrases));
    }
    return $cache[$ownerUserId];
}

function ap_muted_words_cache_clear(?int $ownerUserId = null): void
{
    if ($ownerUserId === null || $ownerUserId < 1) {
        ap_muted_words_phrases_cached(0, true);
        return;
    }
    ap_muted_words_phrases_cached($ownerUserId, true);
}

/**
 * Normalize free-text before matching (HTML entities, tags, case).
 */
function ap_muted_words_normalize_haystack(string $text): string
{
    $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
    $text = strip_tags($text);
    $text = preg_replace('/\s+/u', ' ', $text) ?? $text;
    return mb_strtolower(trim($text), 'UTF-8');
}

/**
 * First matching muted phrase for owner, or null.
 */
function ap_muted_words_match(int $ownerUserId, string ...$texts): ?string
{
    if ($ownerUserId < 1) {
        return null;
    }
    $phrases = ap_muted_words_phrases_cached($ownerUserId);
    if ($phrases === []) {
        return null;
    }
    $hay = '';
    foreach ($texts as $t) {
        $n = ap_muted_words_normalize_haystack((string) $t);
        if ($n !== '') {
            $hay .= ($hay === '' ? '' : ' ') . $n;
        }
    }
    if ($hay === '') {
        return null;
    }
    foreach ($phrases as $phrase) {
        if ($phrase !== '' && mb_strpos($hay, $phrase, 0, 'UTF-8') !== false) {
            return $phrase;
        }
    }
    return null;
}

/**
 * True when an events / outbox / boost row should be hidden by muted words.
 * Pass any extra body text via $extraTexts (e.g. masto content_text).
 *
 * @param array<string,mixed> $row
 * @param list<string> $extraTexts
 */
function ap_row_matches_muted_words(
    array $row,
    string $kind = 'event',
    array $extraTexts = [],
    ?int $ownerUserId = null
): bool {
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    if ($ownerUserId < 1 || ap_muted_words_phrases_cached($ownerUserId) === []) {
        return false;
    }
    $parts = $extraTexts;
    if ($kind === 'outbox') {
        $parts[] = (string) ($row['content'] ?? '');
        $parts[] = (string) ($row['summary'] ?? '');
        $parts[] = (string) ($row['content_text'] ?? '');
        $parts[] = (string) ($row['spoiler_text'] ?? '');
    } elseif ($kind === 'boost') {
        $parts[] = (string) ($row['content_text'] ?? '');
        $parts[] = (string) ($row['spoiler_text'] ?? '');
        $parts[] = (string) ($row['summary'] ?? '');
        $parts[] = (string) ($row['object_summary'] ?? '');
        $parts[] = (string) ($row['reblog_content'] ?? '');
    } else {
        // event (Create / Announce / Quote…)
        $parts[] = (string) ($row['summary'] ?? '');
        $parts[] = (string) ($row['spoiler_text'] ?? '');
        $parts[] = (string) ($row['content_text'] ?? '');
    }
    return ap_muted_words_match($ownerUserId, ...$parts) !== null;
}

/**
 * @return array{ok:bool,error?:string,id?:int,phrase?:string,already?:bool}
 */
function ap_muted_word_add(string $phrase, string $note, int $ownerUserId): array
{
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing owner user.'];
    }
    $phrase = trim(preg_replace('/\s+/u', ' ', $phrase) ?? $phrase);
    $note = trim($note);
    if ($phrase === '') {
        return ['ok' => false, 'error' => 'Enter a word or phrase to mute.'];
    }
    if (mb_strlen($phrase, 'UTF-8') < 2) {
        return ['ok' => false, 'error' => 'Phrase must be at least 2 characters.'];
    }
    if (mb_strlen($phrase, 'UTF-8') > 200) {
        return ['ok' => false, 'error' => 'Phrase too long (max 200 characters).'];
    }
    if (mb_strlen($note, 'UTF-8') > 300) {
        return ['ok' => false, 'error' => 'Note too long (max 300 characters).'];
    }
    $norm = mb_strtolower($phrase, 'UTF-8');
    foreach (ap_muted_words_list($ownerUserId) as $row) {
        if (mb_strtolower((string) ($row['phrase'] ?? ''), 'UTF-8') === $norm) {
            return [
                'ok' => true,
                'already' => true,
                'id' => (int) ($row['id'] ?? 0),
                'phrase' => (string) ($row['phrase'] ?? $phrase),
            ];
        }
    }
    try {
        $st = ap_db()->prepare(
            'INSERT INTO ap_muted_words (owner_user_id, phrase, created_at, note) VALUES (?, ?, ?, ?)'
        );
        $st->execute([$ownerUserId, $phrase, ap_db_now(), $note !== '' ? $note : null]);
        $id = ap_db_last_insert_id('ap_muted_words');
        ap_muted_words_cache_clear($ownerUserId);
        return ['ok' => true, 'id' => $id, 'phrase' => $phrase];
    } catch (Throwable $e) {
        // UNIQUE race
        if (str_contains($e->getMessage(), 'UNIQUE')) {
            return ['ok' => true, 'already' => true, 'phrase' => $phrase];
        }
        error_log('[ap-db] muted_word_add: ' . $e->getMessage());
        return ['ok' => false, 'error' => 'Could not save muted phrase.'];
    }
}

/**
 * @return array{ok:bool,error?:string}
 */
function ap_muted_word_remove(int $id, int $ownerUserId): array
{
    if ($id < 1 || $ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Missing phrase id.'];
    }
    try {
        $st = ap_db()->prepare('DELETE FROM ap_muted_words WHERE id = ? AND owner_user_id = ?');
        $st->execute([$id, $ownerUserId]);
        ap_muted_words_cache_clear($ownerUserId);
        if ($st->rowCount() < 1) {
            return ['ok' => false, 'error' => 'Phrase not found.'];
        }
        return ['ok' => true];
    } catch (Throwable $e) {
        error_log('[ap-db] muted_word_remove: ' . $e->getMessage());
        return ['ok' => false, 'error' => 'Could not remove phrase.'];
    }
}

/* ----------------- Compose drafts (VAAK composer) ----------------- */

/**
 * @return list<array<string,mixed>>
 */
function ap_drafts_list(int $limit = 100): array
{
    $limit = max(1, min(200, $limit));
    $ownerUserId = ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM ap_drafts
             WHERE owner_user_id = ?
             ORDER BY updated_at DESC, id DESC
             LIMIT ' . (int) $limit
        );
        $st->execute([$ownerUserId]);
        return $st->fetchAll() ?: [];
    } catch (Throwable $e) {
        error_log('[ap-db] drafts_list: ' . $e->getMessage());
        return [];
    }
}

function ap_drafts_count(): int
{
    $ownerUserId = ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('SELECT COUNT(*) FROM ap_drafts WHERE owner_user_id = ?');
        $st->execute([$ownerUserId]);
        return (int) $st->fetchColumn();
    } catch (Throwable $e) {
        return 0;
    }
}

function ap_draft_get(int $id): ?array
{
    if ($id < 1) {
        return null;
    }
    $ownerUserId = ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('SELECT * FROM ap_drafts WHERE id = ? AND owner_user_id = ?');
        $st->execute([$id, $ownerUserId]);
        $row = $st->fetch();
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        return null;
    }
}

/**
 * @return list<int>
 */
function ap_draft_media_ids(array $row): array
{
    $raw = $row['media_ids_json'] ?? '[]';
    if (is_string($raw)) {
        $decoded = json_decode($raw, true);
    } else {
        $decoded = $raw;
    }
    if (!is_array($decoded)) {
        return [];
    }
    return array_values(array_filter(array_map('intval', $decoded), static fn($i) => $i > 0));
}

/**
 * Create or update a draft. Empty drafts (no text/media/reply/quote) are rejected
 * unless $allowEmpty is true (used when clearing via delete instead).
 *
 * @param list<int> $mediaIds
 * @param list<int>|null $replaceMediaIds when set, replaces media list; otherwise merges with existing
 * @return array{ok:bool,error?:string,id?:int,draft?:array,created?:bool}
 */
function ap_draft_save(
    string $content,
    string $spoilerText = '',
    bool $sensitive = false,
    string $visibility = 'public',
    string $inReplyTo = '',
    string $toActor = '',
    string $quoteObject = '',
    array $mediaIds = [],
    int $draftId = 0,
    ?array $replaceMediaIds = null
): array {
    $content = trim($content);
    $spoilerText = mb_substr(trim($spoilerText), 0, 500);
    $visibility = function_exists('ap_normalize_visibility')
        ? ap_normalize_visibility($visibility)
        : 'public';
    $inReplyTo = trim($inReplyTo);
    $toActor = trim($toActor);
    $quoteObject = trim($quoteObject);
    $mediaIds = array_values(array_filter(array_map('intval', $mediaIds), static fn($i) => $i > 0));

    if (mb_strlen($content) > 2000) {
        return ['ok' => false, 'error' => 'Draft text max 2000 chars.'];
    }
    if ($inReplyTo !== '' && !str_starts_with($inReplyTo, 'https://')) {
        return ['ok' => false, 'error' => 'in_reply_to must be an https URL.'];
    }
    if ($quoteObject !== '' && !str_starts_with($quoteObject, 'https://')) {
        return ['ok' => false, 'error' => 'quote_object must be an https URL.'];
    }
    if ($toActor !== '' && !str_starts_with($toActor, 'https://')) {
        return ['ok' => false, 'error' => 'to_actor must be an https URL.'];
    }

    $existing = $draftId > 0 ? ap_draft_get($draftId) : null;
    if ($draftId > 0 && $existing === null) {
        return ['ok' => false, 'error' => 'Draft not found.'];
    }

    if ($replaceMediaIds !== null) {
        $finalMedia = array_values(array_filter(array_map('intval', $replaceMediaIds), static fn($i) => $i > 0));
    } else {
        $prev = $existing ? ap_draft_media_ids($existing) : [];
        $finalMedia = array_values(array_unique(array_merge($prev, $mediaIds)));
    }
    if (count($finalMedia) > 4) {
        $finalMedia = array_slice($finalMedia, 0, 4);
    }

    $hasBody = $content !== '' || $spoilerText !== '' || $finalMedia !== []
        || $inReplyTo !== '' || $quoteObject !== '';
    if (!$hasBody) {
        return ['ok' => false, 'error' => 'Nothing to save — type something or attach media.'];
    }

    $now = ap_db_now();
    $mediaJson = json_encode($finalMedia, JSON_UNESCAPED_SLASHES) ?: '[]';
    $sens = ($sensitive || $spoilerText !== '') ? 1 : 0;
    $ownerUserId = ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Not signed in (refusing cmdr_nova fallback).'];
    }

    try {
        if ($existing) {
            ap_db()->prepare(
                'UPDATE ap_drafts SET updated_at = ?, content = ?, spoiler_text = ?, sensitive = ?,
                 visibility = ?, in_reply_to = ?, to_actor = ?, quote_object = ?, media_ids_json = ?
                 WHERE id = ? AND owner_user_id = ?'
            )->execute([
                $now,
                $content,
                $spoilerText,
                $sens,
                $visibility,
                $inReplyTo !== '' ? $inReplyTo : null,
                $toActor !== '' ? $toActor : null,
                $quoteObject !== '' ? $quoteObject : null,
                $mediaJson,
                $draftId,
                $ownerUserId,
            ]);
            $id = $draftId;
            $created = false;
        } else {
            ap_db()->prepare(
                'INSERT INTO ap_drafts
                 (created_at, updated_at, content, spoiler_text, sensitive, visibility,
                  in_reply_to, to_actor, quote_object, media_ids_json, owner_user_id)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
            )->execute([
                $now,
                $now,
                $content,
                $spoilerText,
                $sens,
                $visibility,
                $inReplyTo !== '' ? $inReplyTo : null,
                $toActor !== '' ? $toActor : null,
                $quoteObject !== '' ? $quoteObject : null,
                $mediaJson,
                $ownerUserId,
            ]);
            $id = ap_db_last_insert_id('ap_drafts');
            $created = true;
        }
        $draft = ap_draft_get($id);
        return ['ok' => true, 'id' => $id, 'draft' => $draft, 'created' => $created];
    } catch (Throwable $e) {
        error_log('[ap-db] draft_save: ' . $e->getMessage());
        return ['ok' => false, 'error' => 'Could not save draft.'];
    }
}

/**
 * @return array{ok:bool,error?:string}
 */
function ap_draft_delete(int $id): array
{
    if ($id < 1) {
        return ['ok' => false, 'error' => 'Missing draft id.'];
    }
    $ownerUserId = ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('DELETE FROM ap_drafts WHERE id = ? AND owner_user_id = ?');
        $st->execute([$id, $ownerUserId]);
        if ($st->rowCount() < 1) {
            return ['ok' => false, 'error' => 'Draft not found.'];
        }
        return ['ok' => true];
    } catch (Throwable $e) {
        error_log('[ap-db] draft_delete: ' . $e->getMessage());
        return ['ok' => false, 'error' => 'Could not delete draft.'];
    }
}

/* ----------------- Mastodon OAuth / app password / status ids ----------------- */

function ap_app_password_is_set(): bool
{
    $row = ap_db()->query('SELECT password_hash FROM app_auth WHERE id = 1')->fetch();
    return is_array($row) && !empty($row['password_hash']);
}

function ap_app_password_set(string $plain): array
{
    $plain = trim($plain);
    if (strlen($plain) < 10) {
        return ['ok' => false, 'error' => 'App password must be at least 10 characters.'];
    }
    if (strlen($plain) > 200) {
        return ['ok' => false, 'error' => 'App password too long.'];
    }
    $hash = password_hash($plain, PASSWORD_DEFAULT);
    if (!is_string($hash)) {
        return ['ok' => false, 'error' => 'Could not hash password.'];
    }
    ap_db()->prepare(
        'INSERT INTO app_auth (id, password_hash, updated_at) VALUES (1, ?, ?)
         ON CONFLICT(id) DO UPDATE SET password_hash = excluded.password_hash, updated_at = excluded.updated_at'
    )->execute([$hash, ap_db_now()]);
    return ['ok' => true];
}

function ap_app_password_verify(string $plain): bool
{
    $row = ap_db()->query('SELECT password_hash FROM app_auth WHERE id = 1')->fetch();
    if (!is_array($row) || empty($row['password_hash'])) {
        return false;
    }
    return password_verify($plain, (string) $row['password_hash']);
}

function ap_oauth_normalize_scopes(string $scopes): string
{
    $parts = preg_split('/\s+/', trim($scopes)) ?: [];
    $out = [];
    foreach ($parts as $p) {
        $p = strtolower(trim($p));
        if ($p === '') {
            continue;
        }
        if (!preg_match('/^[a-z][a-z0-9:_-]{0,63}$/', $p)) {
            continue;
        }
        $out[$p] = true;
    }
    if (!$out) {
        $out = ['read' => true];
    }
    return implode(' ', array_keys($out));
}

function ap_oauth_scopes_allow(string $granted, string $need): bool
{
    $g = preg_split('/\s+/', trim($granted)) ?: [];
    $n = preg_split('/\s+/', trim($need)) ?: [];
    $set = [];
    foreach ($g as $s) {
        if ($s === '') {
            continue;
        }
        $set[$s] = true;
    }
    foreach ($n as $req) {
        if ($req === '') {
            continue;
        }
        // Exact match
        if (!empty($set[$req])) {
            continue;
        }
        // Parent covers child only: granted "write" allows need "write:statuses".
        // Never the reverse (write:statuses must NOT satisfy need "write").
        if (str_contains($req, ':')) {
            $root = explode(':', $req, 2)[0];
            if ($root !== '' && !empty($set[$root])) {
                continue;
            }
        }
        return false;
    }
    return true;
}

/**
 * @return array{ok:bool,error?:string,id?:int,client_id?:string,client_secret?:string,vapid_key?:string}
 */
/**
 * Allow only safe OAuth redirect URIs:
 * - urn:ietf:wg:oauth:2.0:oob
 * - https://…
 * - http://127.0.0.1 / http://localhost (dev)
 * - custom app schemes (e.g. icecubesapp://) — not javascript:/data:/file:/vbscript:
 */
function ap_oauth_redirect_uri_safe(string $uri): bool
{
    $uri = trim($uri);
    if ($uri === '' || strlen($uri) > 2000) {
        return false;
    }
    if ($uri === 'urn:ietf:wg:oauth:2.0:oob') {
        return true;
    }
    if (preg_match('#^(javascript|data|vbscript|file):#i', $uri)) {
        return false;
    }
    if (str_starts_with($uri, 'https://')) {
        $host = parse_url($uri, PHP_URL_HOST);
        return is_string($host) && $host !== '';
    }
    if (str_starts_with($uri, 'http://')) {
        $host = strtolower((string) (parse_url($uri, PHP_URL_HOST) ?? ''));
        return in_array($host, ['127.0.0.1', 'localhost', '[::1]'], true);
    }
    // Native app custom schemes: scheme:… / scheme://… (Ice Cubes: icecubesapp://)
    if (!preg_match('/^[a-z][a-z0-9+.-]*:/i', $uri)) {
        return false;
    }
    // No whitespace / control chars; keep path reasonably constrained
    if (preg_match('/[\x00-\x1f\x7f\s]/', $uri)) {
        return false;
    }
    return true;
}

function ap_oauth_app_create(string $name, string $redirectUris, string $scopes, ?string $website = null): array
{
    $name = mb_substr(trim(ap_fix_utf8($name)), 0, 100);
    if ($name === '') {
        return ['ok' => false, 'error' => 'client_name required'];
    }
    $redirectUris = trim($redirectUris);
    if ($redirectUris === '') {
        return ['ok' => false, 'error' => 'redirect_uris required'];
    }
    $parts = preg_split('/\s+/', $redirectUris) ?: [];
    $safe = [];
    foreach ($parts as $u) {
        $u = trim($u);
        if ($u === '') {
            continue;
        }
        if (!ap_oauth_redirect_uri_safe($u)) {
            return ['ok' => false, 'error' => 'redirect_uri not allowed: ' . mb_substr($u, 0, 80)];
        }
        $safe[] = $u;
    }
    if (!$safe) {
        return ['ok' => false, 'error' => 'redirect_uris required'];
    }
    $redirectUris = implode(' ', $safe);
    $scopes = ap_oauth_normalize_scopes($scopes !== '' ? $scopes : 'read');
    $clientId = bin2hex(random_bytes(16));
    $clientSecret = bin2hex(random_bytes(32));
    $hash = password_hash($clientSecret, PASSWORD_DEFAULT);
    ap_db()->prepare(
        'INSERT INTO oauth_apps (client_name, client_id, client_secret_hash, redirect_uris, scopes, website, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)'
    )->execute([$name, $clientId, $hash, $redirectUris, $scopes, $website, ap_db_now()]);
    $id = ap_db_last_insert_id('oauth_apps');
    return [
        'ok' => true,
        'id' => $id,
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'vapid_key' => (static function (): string {
            if (!function_exists('ap_webpush_vapid_public_key')) {
                $wp = __DIR__ . '/ap-webpush.php';
                if (is_file($wp)) {
                    require_once $wp;
                }
            }
            return function_exists('ap_webpush_vapid_public_key') ? ap_webpush_vapid_public_key() : '';
        })(),
    ];
}

function ap_oauth_app_by_client_id(string $clientId): ?array
{
    $st = ap_db()->prepare('SELECT * FROM oauth_apps WHERE client_id = ?');
    $st->execute([$clientId]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_oauth_app_check_secret(array $app, string $secret): bool
{
    return password_verify($secret, (string) ($app['client_secret_hash'] ?? ''));
}

function ap_oauth_redirect_allowed(array $app, string $redirectUri): bool
{
    if (!ap_oauth_redirect_uri_safe($redirectUri)) {
        return false;
    }
    $allowed = preg_split('/\s+/', trim((string) ($app['redirect_uris'] ?? ''))) ?: [];
    foreach ($allowed as $a) {
        if ($a !== '' && hash_equals($a, $redirectUri)) {
            return true;
        }
    }
    return false;
}

/** Access token lifetime (seconds). Clients refresh via refresh_token. */
function ap_oauth_token_ttl_seconds(): int
{
    return 90 * 86400; // 90 days
}

/** Refresh token lifetime (seconds). Re-authorize if this also expires. */
function ap_oauth_refresh_ttl_seconds(): int
{
    return 180 * 86400; // 180 days
}

/**
 * Whether this authorize request must use PKCE S256.
 *
 * Ice Cubes (and stock Mastodon) do **not** send PKCE on the authorize URL
 * (`icecubesapp://` with only client_id/redirect/scope). Hard-requiring PKCE
 * blocked re-login. Keep PKCE optional; when a challenge is present we still
 * enforce S256 (PLAIN rejected in authorize + token).
 */
function ap_oauth_pkce_required(string $redirectUri): bool
{
    unset($redirectUri);
    return false;
}

function ap_oauth_code_create(
    string $clientId,
    string $scopes,
    string $redirectUri,
    ?string $challenge = null,
    ?string $method = null,
    ?int $userId = null
): string {
    $code = bin2hex(random_bytes(24));
    $hash = hash('sha256', $code); // store only the hash (PK column)
    $exp = gmdate('c', time() + 600);
    $methodNorm = $method !== null && $method !== '' ? strtoupper($method) : null;
    $uid = ($userId !== null && $userId > 0) ? $userId : null;
    ap_db()->prepare(
        'INSERT INTO oauth_codes (code, client_id, scopes, redirect_uri, code_challenge, code_challenge_method, expires_at, user_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
    )->execute([$hash, $clientId, $scopes, $redirectUri, $challenge, $methodNorm, $exp, $uid]);
    return $code; // plaintext returned once to the client
}

function ap_oauth_code_consume(string $code, string $clientId, string $redirectUri, ?string $verifier = null): ?array
{
    $hash = hash('sha256', $code);
    $db = ap_db();
    $db->beginTransaction();
    try {
        $st = $db->prepare('SELECT * FROM oauth_codes WHERE code = ?');
        $st->execute([$hash]);
        $row = $st->fetch();
        if (!is_array($row) || !empty($row['used_at'])) {
            $db->rollBack();
            return null;
        }
        if (($row['client_id'] ?? '') !== $clientId) {
            $db->rollBack();
            return null;
        }
        if (($row['redirect_uri'] ?? '') !== $redirectUri) {
            $db->rollBack();
            return null;
        }
        if (strtotime((string) $row['expires_at']) < time()) {
            $db->rollBack();
            return null;
        }
        $challenge = $row['code_challenge'] ?? null;
        $method = strtoupper((string) ($row['code_challenge_method'] ?? ''));
        // PLAIN never accepted. If authorize stored a challenge, verifier must
        // match (S256). No challenge ⇒ Mastodon/Ice Cubes style (secret + app password).
        if (is_string($challenge) && $challenge !== '') {
            if ($method !== 'S256' || !is_string($verifier) || $verifier === '') {
                $db->rollBack();
                return null;
            }
            $calc = rtrim(strtr(base64_encode(hash('sha256', $verifier, true)), '+/', '-_'), '=');
            if (!hash_equals($challenge, $calc)) {
                $db->rollBack();
                return null;
            }
        }
        $upd = $db->prepare('UPDATE oauth_codes SET used_at = ? WHERE code = ? AND used_at IS NULL');
        $upd->execute([ap_db_now(), $hash]);
        if ($upd->rowCount() !== 1) {
            $db->rollBack();
            return null;
        }
        $db->commit();
        return $row;
    } catch (Throwable $e) {
        if ($db->inTransaction()) {
            $db->rollBack();
        }
        return null;
    }
}

/** Human-readable reason for invalid_grant (no secrets). */
function ap_oauth_code_consume_debug(string $code, string $clientId, string $redirectUri, ?string $verifier = null): string
{
    if ($code === '') {
        return 'missing authorization code';
    }
    $hash = hash('sha256', $code);
    $st = ap_db()->prepare('SELECT client_id, redirect_uri, expires_at, used_at, code_challenge, code_challenge_method FROM oauth_codes WHERE code = ?');
    $st->execute([$hash]);
    $row = $st->fetch();
    if (!is_array($row)) {
        return 'authorization code not recognized';
    }
    if (!empty($row['used_at'])) {
        return 'authorization code already used';
    }
    if (($row['client_id'] ?? '') !== $clientId) {
        return 'authorization code client_id mismatch';
    }
    if (($row['redirect_uri'] ?? '') !== $redirectUri) {
        return 'redirect_uri mismatch (got ' . mb_substr($redirectUri, 0, 80)
            . ', expected ' . mb_substr((string) $row['redirect_uri'], 0, 80) . ')';
    }
    if (strtotime((string) $row['expires_at']) < time()) {
        return 'authorization code expired';
    }
    $challenge = $row['code_challenge'] ?? null;
    if (is_string($challenge) && $challenge !== '') {
        $method = strtoupper((string) ($row['code_challenge_method'] ?? ''));
        if ($method !== 'S256') {
            return 'PKCE method must be S256';
        }
        if (!is_string($verifier) || $verifier === '') {
            return 'missing code_verifier for PKCE';
        }
        $calc = rtrim(strtr(base64_encode(hash('sha256', $verifier, true)), '+/', '-_'), '=');
        if (!hash_equals($challenge, $calc)) {
            return 'PKCE code_verifier mismatch';
        }
    }
    return 'authorization code could not be consumed';
}

/**
 * @return array{access_token:string,token_type:string,scope:string,created_at:int,expires_in:int,refresh_token:string}
 */
function ap_oauth_token_create(string $clientId, string $scopes, ?int $userId = null): array
{
    $token = bin2hex(random_bytes(32));
    $refresh = bin2hex(random_bytes(32));
    $hash = hash('sha256', $token);
    $refreshHash = hash('sha256', $refresh);
    $now = time();
    $ttl = ap_oauth_token_ttl_seconds();
    $refreshTtl = ap_oauth_refresh_ttl_seconds();
    $expiresAt = gmdate('c', $now + $ttl);
    $refreshExpiresAt = gmdate('c', $now + $refreshTtl);
    $uid = ($userId !== null && $userId > 0) ? $userId : null;
    ap_db()->prepare(
        'INSERT INTO oauth_tokens
         (access_token_hash, client_id, scopes, created_at, expires_at, refresh_token_hash, refresh_expires_at, user_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
    )->execute([
        $hash,
        $clientId,
        $scopes,
        gmdate('c', $now),
        $expiresAt,
        $refreshHash,
        $refreshExpiresAt,
        $uid,
    ]);
    return [
        'access_token' => $token,
        'token_type' => 'Bearer',
        'scope' => $scopes,
        'created_at' => $now,
        'expires_in' => $ttl,
        'refresh_token' => $refresh,
    ];
}

/**
 * Exchange a refresh_token for a new access_token (+ rotated refresh_token).
 *
 * @return array{access_token:string,token_type:string,scope:string,created_at:int,expires_in:int,refresh_token:string}|null
 */
function ap_oauth_token_refresh(string $clientId, string $refreshToken): ?array
{
    if ($refreshToken === '') {
        return null;
    }
    $refreshHash = hash('sha256', $refreshToken);
    $db = ap_db();
    $db->beginTransaction();
    try {
        $st = $db->prepare(
            'SELECT * FROM oauth_tokens WHERE refresh_token_hash = ? AND client_id = ? AND revoked_at IS NULL'
        );
        $st->execute([$refreshHash, $clientId]);
        $row = $st->fetch();
        if (!is_array($row)) {
            $db->rollBack();
            return null;
        }
        $rexp = $row['refresh_expires_at'] ?? null;
        if (is_string($rexp) && $rexp !== '') {
            $t = strtotime($rexp);
            if ($t !== false && $t < time()) {
                $db->prepare(
                    'UPDATE oauth_tokens SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL'
                )->execute([ap_db_now(), (int) $row['id']]);
                $db->commit();
                return null;
            }
        }
        $access = bin2hex(random_bytes(32));
        $refresh = bin2hex(random_bytes(32));
        $now = time();
        $ttl = ap_oauth_token_ttl_seconds();
        $refreshTtl = ap_oauth_refresh_ttl_seconds();
        $upd = $db->prepare(
            'UPDATE oauth_tokens
             SET access_token_hash = ?, expires_at = ?, refresh_token_hash = ?, refresh_expires_at = ?
             WHERE id = ? AND revoked_at IS NULL AND refresh_token_hash = ?'
        );
        $upd->execute([
            hash('sha256', $access),
            gmdate('c', $now + $ttl),
            hash('sha256', $refresh),
            gmdate('c', $now + $refreshTtl),
            (int) $row['id'],
            $refreshHash,
        ]);
        if ($upd->rowCount() !== 1) {
            $db->rollBack();
            return null;
        }
        $db->commit();
        return [
            'access_token' => $access,
            'token_type' => 'Bearer',
            'scope' => (string) ($row['scopes'] ?? 'read'),
            'created_at' => $now,
            'expires_in' => $ttl,
            'refresh_token' => $refresh,
        ];
    } catch (Throwable $e) {
        if ($db->inTransaction()) {
            $db->rollBack();
        }
        return null;
    }
}

function ap_oauth_token_lookup(?string $bearer): ?array
{
    if ($bearer === null || $bearer === '') {
        return null;
    }
    if (preg_match('/^Bearer\s+(\S+)$/i', $bearer, $m)) {
        $bearer = $m[1];
    }
    $hash = hash('sha256', $bearer);
    $st = ap_db()->prepare('SELECT * FROM oauth_tokens WHERE access_token_hash = ? AND revoked_at IS NULL');
    $st->execute([$hash]);
    $row = $st->fetch();
    if (!is_array($row)) {
        return null;
    }
    $exp = $row['expires_at'] ?? null;
    if (is_string($exp) && $exp !== '') {
        $t = strtotime($exp);
        if ($t !== false && $t < time()) {
            // Access expired — do NOT revoke the row; refresh_token may still be valid.
            return null;
        }
    }
    return $row;
}

function ap_oauth_token_revoke(string $token): void
{
    $hash = hash('sha256', $token);
    // Accept either access or refresh token value
    ap_db()->prepare(
        'UPDATE oauth_tokens SET revoked_at = ?
         WHERE revoked_at IS NULL AND (access_token_hash = ? OR refresh_token_hash = ?)'
    )->execute([ap_db_now(), $hash, $hash]);
}

/**
 * Revoke a token by id. When $ownerUserId is set, only revoke if the row
 * belongs to that user (NULL user_id legacy rows only for cmdr_nova).
 */
function ap_oauth_token_revoke_by_id(int $id, ?int $ownerUserId = null): bool
{
    if ($id <= 0) {
        return false;
    }
    if ($ownerUserId === null || $ownerUserId < 1) {
        $st = ap_db()->prepare(
            'UPDATE oauth_tokens SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL'
        );
        $st->execute([ap_db_now(), $id]);
        return $st->rowCount() > 0;
    }
    $cmdrId = function_exists('ap_db_cmdr_nova_user_id') ? (int) ap_db_cmdr_nova_user_id() : 0;
    if ($cmdrId > 0 && $ownerUserId === $cmdrId) {
        $st = ap_db()->prepare(
            'UPDATE oauth_tokens SET revoked_at = ?
             WHERE id = ? AND revoked_at IS NULL AND (user_id = ? OR user_id IS NULL)'
        );
        $st->execute([ap_db_now(), $id, $ownerUserId]);
    } else {
        $st = ap_db()->prepare(
            'UPDATE oauth_tokens SET revoked_at = ?
             WHERE id = ? AND revoked_at IS NULL AND user_id = ?'
        );
        $st->execute([ap_db_now(), $id, $ownerUserId]);
    }
    return $st->rowCount() > 0;
}

/**
 * Active (+ recently revoked) tokens for Security UI.
 * When $userId is set, only that user's tokens (legacy NULL user_id rows
 * only appear for cmdr_nova). Revoked older than $revokedKeepDays are omitted.
 *
 * @return list<array<string,mixed>>
 */
function ap_oauth_tokens_list(int $limit = 40, int $revokedKeepDays = 7, ?int $userId = null): array
{
    $limit = max(1, min(100, $limit));
    $revokedKeepDays = max(0, min(180, $revokedKeepDays));
    $cutoff = gmdate('c', time() - ($revokedKeepDays * 86400));
    $params = [$cutoff];
    $ownerSql = '';
    if ($userId !== null && $userId > 0) {
        $cmdrId = function_exists('ap_db_cmdr_nova_user_id') ? (int) ap_db_cmdr_nova_user_id() : 0;
        if ($cmdrId > 0 && $userId === $cmdrId) {
            // Operator sees own tokens + pre-multi-user rows (user_id NULL)
            $ownerSql = ' AND (t.user_id = ? OR t.user_id IS NULL) ';
            $params[] = $userId;
        } else {
            $ownerSql = ' AND t.user_id = ? ';
            $params[] = $userId;
        }
    }
    $st = ap_db()->prepare(
        'SELECT t.id, t.client_id, t.scopes, t.created_at, t.expires_at, t.revoked_at,
                t.refresh_expires_at, t.user_id, a.client_name, a.website
         FROM oauth_tokens t
         LEFT JOIN oauth_apps a ON a.client_id = t.client_id
         WHERE (t.revoked_at IS NULL OR t.revoked_at >= ?)
         ' . $ownerSql . '
         ORDER BY t.id DESC
         LIMIT ' . (int) $limit
    );
    $st->execute($params);
    return $st->fetchAll();
}

/**
 * Delete revoked tokens (and fully expired access+refresh rows).
 * Used by daily maintain and Security "Purge now".
 *
 * @return array{ok:bool,revoked_deleted:int,expired_deleted:int,apps_deleted:int}
 */
function ap_oauth_tokens_purge_stale(int $revokedAfterDays = 7, bool $purgeAllRevoked = false): array
{
    $revokedAfterDays = max(0, min(180, $revokedAfterDays));
    $now = ap_db_now();
    $db = ap_db();
    $revokedDeleted = 0;
    $expiredDeleted = 0;

    if ($purgeAllRevoked) {
        $st = $db->prepare('DELETE FROM oauth_tokens WHERE revoked_at IS NOT NULL');
        $st->execute();
        $revokedDeleted = $st->rowCount();
    } else {
        $cutoff = gmdate('c', time() - ($revokedAfterDays * 86400));
        $st = $db->prepare('DELETE FROM oauth_tokens WHERE revoked_at IS NOT NULL AND revoked_at < ?');
        $st->execute([$cutoff]);
        $revokedDeleted = $st->rowCount();
    }

    // Access + refresh both expired (or no refresh) and not already revoked-deleted
    $st = $db->prepare(
        "DELETE FROM oauth_tokens WHERE revoked_at IS NULL
         AND expires_at IS NOT NULL AND expires_at < ?
         AND (refresh_expires_at IS NULL OR refresh_expires_at < ?)"
    );
    $st->execute([$now, $now]);
    $expiredDeleted = $st->rowCount();

    // OAuth app registrations are durable. Clients such as Buffer retain their
    // client_id and may re-authorize after all tokens have expired or been
    // revoked; deleting the registration makes that valid reconnect fail as
    // "Unknown client_id". Token cleanup remains independent.
    $appsDeleted = 0;

    return [
        'ok' => true,
        'revoked_deleted' => $revokedDeleted,
        'expired_deleted' => $expiredDeleted,
        'apps_deleted' => $appsDeleted,
    ];
}

function ap_masto_status_register(
    string $noteId,
    string $createId,
    string $published,
    string $contentText,
    ?int $replyLocalId = null,
    string $spoilerText = '',
    bool $sensitive = false,
    string $visibility = 'public'
): int {
    $existing = ap_masto_status_by_note_id($noteId);
    if ($existing) {
        return (int) $existing['local_id'];
    }
    $spoilerText = mb_substr(trim(ap_fix_utf8($spoilerText)), 0, 500);
    $visibility = function_exists('ap_normalize_visibility')
        ? ap_normalize_visibility($visibility)
        : 'public';
    ap_db()->prepare(
        'INSERT INTO masto_statuses (note_id, create_id, published, content_text, in_reply_to_local_id, visibility, spoiler_text, sensitive)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)'
    )->execute([
        $noteId,
        $createId,
        $published,
        $contentText,
        $replyLocalId,
        $visibility,
        $spoilerText,
        $sensitive ? 1 : 0,
    ]);
    $localId = ap_db_last_insert_id('masto_statuses', 'local_id');
    if ($localId > 0 && function_exists('ap_search_fts_index_status_row')) {
        ap_search_fts_index_status_row([
            'local_id' => $localId,
            'note_id' => $noteId,
            'published' => $published,
            'content_text' => $contentText,
            'spoiler_text' => $spoilerText,
        ]);
    }
    return $localId;
}

function ap_masto_status_by_local_id(int $id): ?array
{
    $st = ap_db()->prepare('SELECT * FROM masto_statuses WHERE local_id = ?');
    $st->execute([$id]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_masto_status_by_note_id(string $noteId): ?array
{
    $st = ap_db()->prepare('SELECT * FROM masto_statuses WHERE note_id = ?');
    $st->execute([$noteId]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

/**
 * Recent local statuses, optionally bounded by published timestamps (exclusive).
 * When $actorKey is set, only notes under /users/{key}/notes/ are returned.
 *
 * @return list<array<string,mixed>>
 */
function ap_masto_statuses_recent(
    int $limit = 40,
    ?string $beforePublished = null,
    ?string $afterPublished = null,
    ?string $actorKey = null
): array {
    $limit = max(1, min(80, $limit));
    $where = [];
    $params = [];
    $actorKey = strtolower(trim((string) $actorKey));
    $actorKey = preg_replace('/[^a-z0-9_]/', '', $actorKey) ?? '';
    if ($actorKey !== '') {
        $where[] = 'note_id LIKE ?';
        $params[] = 'https://mkultra.monster/users/' . $actorKey . '/notes/%';
    }
    if ($beforePublished !== null && $beforePublished !== '') {
        try {
            $where[] = 'published < ?';
            $params[] = (new DateTimeImmutable($beforePublished))->format('c');
        } catch (Throwable $e) {
            // ignore bad cursor
        }
    }
    if ($afterPublished !== null && $afterPublished !== '') {
        try {
            $where[] = 'published > ?';
            $params[] = (new DateTimeImmutable($afterPublished))->format('c');
        } catch (Throwable $e) {
            // ignore bad cursor
        }
    }
    $params[] = $limit;
    $sql = 'SELECT * FROM masto_statuses'
        . ($where !== [] ? ' WHERE ' . implode(' AND ', $where) : '')
        . ' ORDER BY published DESC, local_id DESC LIMIT ?';
    $st = ap_db()->prepare($sql);
    $st->execute($params);
    return $st->fetchAll();
}

function ap_masto_status_is_pinned(int $localId, ?int $ownerUserId = null): bool
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    if ($localId <= 0 || $ownerUserId < 1) {
        return false;
    }
    $st = ap_db()->prepare('SELECT 1 FROM masto_pins WHERE status_local_id = ? AND owner_user_id = ?');
    $st->execute([$localId, $ownerUserId]);
    return (bool) $st->fetchColumn();
}

/**
 * Pinned masto_statuses rows, newest pin first.
 * When $actorKey is set, only pins for that actor's notes are returned.
 *
 * @return list<array<string,mixed>>
 */
function ap_masto_pinned_statuses(int $limit = 5, ?string $actorKey = null): array
{
    $limit = max(1, min(5, $limit));
    $actorKey = strtolower(trim((string) $actorKey));
    $actorKey = preg_replace('/[^a-z0-9_]/', '', $actorKey) ?? '';
    $ownerUserId = $actorKey !== ''
        ? ap_db_owner_user_id_for_actor($actorKey)
        : ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        return [];
    }
    if ($actorKey !== '') {
        $st = ap_db()->prepare(
            'SELECT s.* FROM masto_pins p
             INNER JOIN masto_statuses s ON s.local_id = p.status_local_id
             WHERE p.owner_user_id = ? AND s.note_id LIKE ?
             ORDER BY p.pinned_at DESC
             LIMIT ?'
        );
        $st->execute([$ownerUserId, 'https://mkultra.monster/users/' . $actorKey . '/notes/%', $limit]);
        return $st->fetchAll() ?: [];
    }
    $st = ap_db()->prepare(
        'SELECT s.* FROM masto_pins p
         INNER JOIN masto_statuses s ON s.local_id = p.status_local_id
         WHERE p.owner_user_id = ?
         ORDER BY p.pinned_at DESC
         LIMIT ?'
    );
    $st->execute([$ownerUserId, $limit]);
    return $st->fetchAll() ?: [];
}

/**
 * Pin a local status. Mastodon-compatible max of 5.
 * Only notes under the session actor (or any local /users/{key}/notes/) may be pinned.
 * @return array{ok:bool,error?:string}
 */
function ap_masto_status_pin(int $localId): array
{
    $ownerUserId = ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Not signed in'];
    }
    $row = ap_masto_status_by_local_id($localId);
    if (!$row) {
        return ['ok' => false, 'error' => 'Record not found'];
    }
    $noteId = (string) ($row['note_id'] ?? '');
    $ownerPrefix = rtrim(ap_local_actor_id(), '/') . '/notes/';
    $isLocalNote = $ownerPrefix !== '' && str_starts_with($noteId, $ownerPrefix);
    if (!$isLocalNote) {
        return ['ok' => false, 'error' => 'Cannot pin a remote status'];
    }
    $vis = (string) ($row['visibility'] ?? 'public');
    if ($vis === 'direct') {
        return ['ok' => false, 'error' => 'Cannot pin direct messages'];
    }
    if (ap_masto_status_is_pinned($localId, $ownerUserId)) {
        return ['ok' => true];
    }
    $db = ap_db();
    try {
        $db->beginTransaction();
        $stc = $db->prepare('SELECT COUNT(*) FROM masto_pins WHERE owner_user_id = ?');
        $stc->execute([$ownerUserId]);
        $count = (int) $stc->fetchColumn();
        if ($count >= 5) {
            $db->rollBack();
            return ['ok' => false, 'error' => 'You cannot pin more than 5 statuses'];
        }
        $db->prepare(
            'INSERT INTO masto_pins (owner_user_id, status_local_id, pinned_at) VALUES (?, ?, ?)'
        )->execute([$ownerUserId, $localId, gmdate('c')]);
        $db->commit();
    } catch (Throwable $e) {
        if ($db->inTransaction()) {
            $db->rollBack();
        }
        return ['ok' => false, 'error' => 'Could not pin'];
    }
    return ['ok' => true];
}

/**
 * @return array{ok:bool,error?:string}
 */
function ap_masto_status_unpin(int $localId): array
{
    $ownerUserId = ap_db_default_owner_user_id();
    if ($localId <= 0 || $ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Record not found'];
    }
    ap_db()->prepare('DELETE FROM masto_pins WHERE status_local_id = ? AND owner_user_id = ?')
        ->execute([$localId, $ownerUserId]);
    return ['ok' => true];
}

/**
 * Request-scoped interaction flags (fav / bookmark / reblog).
 * Prefill via ap_masto_status_flags_prefetch() to avoid N+1 on timelines.
 *
 * @var array{fav?:array<string,bool>,bm?:array<string,bool>,rb?:array<string,bool>}|null
 */
$GLOBALS['ap_masto_flag_memo'] = $GLOBALS['ap_masto_flag_memo'] ?? null;

/**
 * Batch-load fav/bookmark/reblog flags for many Mastodon status ids (one query each).
 *
 * @param list<string|int> $statusIds
 */
function ap_masto_status_flags_prefetch(array $statusIds): void
{
    $ids = [];
    foreach ($statusIds as $sid) {
        $s = trim((string) $sid);
        if ($s !== '' && preg_match('/^\d+$/', $s)) {
            $ids[$s] = true;
        }
    }
    if ($ids === []) {
        return;
    }
    $list = array_keys($ids);
    if (!isset($GLOBALS['ap_masto_flag_memo']) || !is_array($GLOBALS['ap_masto_flag_memo'])) {
        $GLOBALS['ap_masto_flag_memo'] = ['fav' => [], 'bm' => [], 'rb' => []];
    }
    $memo = &$GLOBALS['ap_masto_flag_memo'];
    foreach ($list as $id) {
        if (!isset($memo['fav'][$id])) {
            $memo['fav'][$id] = false;
        }
        if (!isset($memo['bm'][$id])) {
            $memo['bm'][$id] = false;
        }
        if (!isset($memo['rb'][$id])) {
            $memo['rb'][$id] = false;
        }
    }
    $chunks = array_chunk($list, 400);
    $ownerUserId = ap_db_default_owner_user_id();
    try {
        $db = ap_db();
        foreach ($chunks as $chunk) {
            $ph = implode(',', array_fill(0, count($chunk), '?'));
            $params = array_merge([$ownerUserId], $chunk);
            $st = $db->prepare("SELECT status_id FROM masto_favourites WHERE owner_user_id = ? AND status_id IN ($ph)");
            $st->execute($params);
            foreach ($st->fetchAll(PDO::FETCH_COLUMN) ?: [] as $hit) {
                $memo['fav'][(string) $hit] = true;
            }
            $st = $db->prepare("SELECT status_id FROM masto_bookmarks WHERE owner_user_id = ? AND status_id IN ($ph)");
            $st->execute($params);
            foreach ($st->fetchAll(PDO::FETCH_COLUMN) ?: [] as $hit) {
                $memo['bm'][(string) $hit] = true;
            }
            $st = $db->prepare("SELECT status_id FROM masto_reblogs WHERE owner_user_id = ? AND status_id IN ($ph)");
            $st->execute($params);
            foreach ($st->fetchAll(PDO::FETCH_COLUMN) ?: [] as $hit) {
                $memo['rb'][(string) $hit] = true;
            }
        }
    } catch (Throwable $e) {
        // leave defaults (false)
    }
}

function ap_masto_status_is_favourited(string $statusId, ?int $ownerUserId = null): bool
{
    if ($statusId === '') {
        return false;
    }
    $memo = $GLOBALS['ap_masto_flag_memo'] ?? null;
    if (is_array($memo) && isset($memo['fav'][$statusId])) {
        return (bool) $memo['fav'][$statusId];
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('SELECT 1 FROM masto_favourites WHERE owner_user_id = ? AND status_id = ?');
        $st->execute([$ownerUserId, $statusId]);
        $hit = (bool) $st->fetchColumn();
        if (!isset($GLOBALS['ap_masto_flag_memo']) || !is_array($GLOBALS['ap_masto_flag_memo'])) {
            $GLOBALS['ap_masto_flag_memo'] = ['fav' => [], 'bm' => [], 'rb' => []];
        }
        $GLOBALS['ap_masto_flag_memo']['fav'][$statusId] = $hit;
        return $hit;
    } catch (Throwable $e) {
        return false;
    }
}

function ap_masto_status_is_bookmarked(string $statusId, ?int $ownerUserId = null): bool
{
    if ($statusId === '') {
        return false;
    }
    $memo = $GLOBALS['ap_masto_flag_memo'] ?? null;
    if (is_array($memo) && isset($memo['bm'][$statusId])) {
        return (bool) $memo['bm'][$statusId];
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('SELECT 1 FROM masto_bookmarks WHERE owner_user_id = ? AND status_id = ?');
        $st->execute([$ownerUserId, $statusId]);
        $hit = (bool) $st->fetchColumn();
        if (!isset($GLOBALS['ap_masto_flag_memo']) || !is_array($GLOBALS['ap_masto_flag_memo'])) {
            $GLOBALS['ap_masto_flag_memo'] = ['fav' => [], 'bm' => [], 'rb' => []];
        }
        $GLOBALS['ap_masto_flag_memo']['bm'][$statusId] = $hit;
        return $hit;
    } catch (Throwable $e) {
        return false;
    }
}

