/**
 * Idempotent local favourite insert. Keeps the first created_at; fills like_activity_id if new.
 */
function ap_masto_favourite_add(
    string $statusId,
    string $objectId,
    ?string $targetActor,
    ?string $likeActivityId,
    ?int $ownerUserId = null
): void {
    if ($statusId === '') {
        return;
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        error_log('[ap-db] favourite_add refused: no session owner (cmdr fallback blocked)');
        return;
    }
    $ownerActorId = ap_db_owner_actor_id_for_user_id($ownerUserId);
    if ($ownerActorId === '') {
        error_log('[ap-db] favourite_add refused: owner actor unresolved');
        return;
    }
    $objectId = $objectId !== '' ? $objectId : $statusId;
    ap_db()->prepare(
        'INSERT INTO masto_favourites (owner_user_id, owner_actor_id, status_id, object_id, target_actor, like_activity_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(owner_user_id, status_id) DO UPDATE SET
           owner_actor_id = COALESCE(excluded.owner_actor_id, masto_favourites.owner_actor_id),
           object_id = CASE WHEN excluded.object_id != \'\' THEN excluded.object_id ELSE masto_favourites.object_id END,
           target_actor = COALESCE(excluded.target_actor, masto_favourites.target_actor),
           like_activity_id = COALESCE(excluded.like_activity_id, masto_favourites.like_activity_id)'
    )->execute([$ownerUserId, $ownerActorId, $statusId, $objectId, $targetActor, $likeActivityId, gmdate('c')]);
}

/** @return array<string,mixed>|null the removed row, if any */
function ap_masto_favourite_remove(string $statusId, ?int $ownerUserId = null): ?array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $row = ap_masto_favourite_row($statusId, $ownerUserId);
    if ($row) {
        ap_db()->prepare('DELETE FROM masto_favourites WHERE owner_user_id = ? AND status_id = ?')
            ->execute([$ownerUserId, $statusId]);
    }
    return $row;
}

/**
 * Newest-first favourite rows. $maxId is a public status_id for created_at pagination.
 *
 * @return list<array<string,mixed>>
 */
function ap_masto_favourite_rows(int $limit = 40, ?string $maxId = null, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $limit = max(1, min(80, $limit));
    $fetch = min(160, $limit * 2);
    try {
        $before = null;
        if ($maxId !== null && $maxId !== '') {
            $st = ap_db()->prepare(
                'SELECT created_at FROM masto_favourites WHERE owner_user_id = ? AND status_id = ?'
            );
            $st->execute([$ownerUserId, $maxId]);
            $val = $st->fetchColumn();
            $before = is_string($val) && $val !== '' ? $val : null;
        }
        if ($before !== null) {
            $st = ap_db()->prepare(
                'SELECT * FROM masto_favourites WHERE owner_user_id = ? AND created_at < ?
                 ORDER BY created_at DESC LIMIT ?'
            );
            $st->execute([$ownerUserId, $before, $fetch]);
        } else {
            $st = ap_db()->prepare(
                'SELECT * FROM masto_favourites WHERE owner_user_id = ? ORDER BY created_at DESC LIMIT ?'
            );
            $st->execute([$ownerUserId, $fetch]);
        }
        return $st->fetchAll();
    } catch (Throwable $e) {
        return [];
    }
}

