function ap_masto_status_is_reblogged(string $statusId, ?int $ownerUserId = null): bool
{
    if ($statusId === '') {
        return false;
    }
    $memo = $GLOBALS['ap_masto_flag_memo'] ?? null;
    if (is_array($memo) && isset($memo['rb'][$statusId])) {
        return (bool) $memo['rb'][$statusId];
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare('SELECT 1 FROM masto_reblogs WHERE owner_user_id = ? AND status_id = ?');
        $st->execute([$ownerUserId, $statusId]);
        $hit = (bool) $st->fetchColumn();
        if (!isset($GLOBALS['ap_masto_flag_memo']) || !is_array($GLOBALS['ap_masto_flag_memo'])) {
            $GLOBALS['ap_masto_flag_memo'] = ['fav' => [], 'bm' => [], 'rb' => []];
        }
        $GLOBALS['ap_masto_flag_memo']['rb'][$statusId] = $hit;
        return $hit;
    } catch (Throwable $e) {
        return false;
    }
}

