/**
 * @return array{ok:bool,row?:array<string,mixed>,error?:string}
 */
function ap_masto_reblog_add(
    string $statusId,
    string $boostStatusId,
    string $objectId,
    ?string $targetActor,
    string $announceActivityId,
    ?int $ownerUserId = null
): array {
    if ($statusId === '' || $boostStatusId === '' || $objectId === '' || $announceActivityId === '') {
        return ['ok' => false, 'error' => 'invalid reblog fields'];
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    if ($ownerUserId < 1) {
        return ['ok' => false, 'error' => 'Not signed in (refusing cmdr_nova fallback)'];
    }
    $ownerActorId = ap_db_owner_actor_id_for_user_id($ownerUserId);
    if ($ownerActorId === '') {
        return ['ok' => false, 'error' => 'Owner actor unresolved'];
    }
    try {
        ap_db()->prepare(
            'INSERT INTO masto_reblogs (owner_user_id, owner_actor_id, status_id, boost_status_id, object_id, target_actor, announce_activity_id, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?)
             ON CONFLICT(owner_user_id, status_id) DO UPDATE SET
               owner_actor_id = COALESCE(excluded.owner_actor_id, masto_reblogs.owner_actor_id),
               boost_status_id = excluded.boost_status_id,
               object_id = excluded.object_id,
               target_actor = COALESCE(excluded.target_actor, masto_reblogs.target_actor),
               announce_activity_id = excluded.announce_activity_id'
        )->execute([
            $ownerUserId,
            $ownerActorId,
            $statusId,
            $boostStatusId,
            $objectId,
            $targetActor,
            $announceActivityId,
            gmdate('c'),
        ]);
        $row = ap_masto_reblog_row_by_status($statusId, $ownerUserId);
        return $row ? ['ok' => true, 'row' => $row] : ['ok' => false, 'error' => 'reblog missing after insert'];
    } catch (Throwable $e) {
        return ['ok' => false, 'error' => $e->getMessage()];
    }
}

/** @return array<string,mixed>|null removed row */
function ap_masto_reblog_remove(string $statusId, ?int $ownerUserId = null): ?array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $row = ap_masto_reblog_row_by_status($statusId, $ownerUserId);
    if ($row) {
        ap_db()->prepare('DELETE FROM masto_reblogs WHERE owner_user_id = ? AND status_id = ?')
            ->execute([$ownerUserId, $statusId]);
    }
    return $row;
}

/**
 * @return list<array<string,mixed>>
 */
function ap_masto_reblog_rows(int $limit = 40, ?string $maxId = null, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $limit = max(1, min(80, $limit));
    $fetch = min(200, max($limit * 3, $limit));
    try {
        if ($maxId !== null && $maxId !== '') {
            $beforeRow = ap_masto_reblog_row_by_boost_id($maxId, $ownerUserId);
            $before = is_array($beforeRow) ? (string) ($beforeRow['created_at'] ?? '') : '';
            if ($before === '' && function_exists('ap_masto_status_created_at_by_id')) {
                $before = (string) (ap_masto_status_created_at_by_id((int) $maxId) ?? '');
            }
            if ($before === '') {
                $st = ap_db()->prepare(
                    'SELECT * FROM masto_reblogs WHERE owner_user_id = ? ORDER BY created_at DESC LIMIT ?'
                );
                $st->execute([$ownerUserId, $fetch]);
            } else {
                $st = ap_db()->prepare(
                    'SELECT * FROM masto_reblogs WHERE owner_user_id = ? AND created_at < ?
                     ORDER BY created_at DESC LIMIT ?'
                );
                $st->execute([$ownerUserId, $before, $fetch]);
            }
        } else {
            $st = ap_db()->prepare(
                'SELECT * FROM masto_reblogs WHERE owner_user_id = ? ORDER BY created_at DESC LIMIT ?'
            );
            $st->execute([$ownerUserId, $fetch]);
        }
        return $st->fetchAll();
    } catch (Throwable $e) {
        return [];
    }
}

/**
 * Rebuild a public Announce activity from a masto_reblogs row.
 * Remotes fetch /users/cmdr_nova/announces/{id} after inbox delivery; without
 * this document they drop or hide the boost.
 *
 * @param array<string,mixed> $row
 * @return array<string,mixed>|null
 */
function ap_masto_announce_activity_from_row(array $row): ?array
{
    $announceId = trim((string) ($row['announce_activity_id'] ?? ''));
    $objectId = trim((string) ($row['object_id'] ?? ''));
    if ($announceId === '' || !str_starts_with($announceId, 'https://')) {
        return null;
    }
    if ($objectId === '' || !str_starts_with($objectId, 'https://')) {
        return null;
    }
    $actor = 'https://mkultra.monster/users/cmdr_nova';
    $published = (string) ($row['created_at'] ?? gmdate('c'));
    try {
        $published = (new DateTimeImmutable($published))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\\TH:i:s\\Z');
    } catch (Throwable $e) {
        $published = gmdate('Y-m-d\\TH:i:s\\Z');
    }
    $cc = [$actor . '/followers'];
    $target = trim((string) ($row['target_actor'] ?? ''));
    if ($target !== '' && str_starts_with($target, 'https://')) {
        // Prefer AP actor ids over @handle profile URLs when both exist
        $cc[] = rtrim($target, '/');
    }
    $activity = [
        '@context' => 'https://www.w3.org/ns/activitystreams',
        'id' => $announceId,
        'type' => 'Announce',
        'actor' => $actor,
        'published' => $published,
        'to' => ['https://www.w3.org/ns/activitystreams#Public'],
        'cc' => array_values(array_unique($cc)),
        'object' => $objectId,
    ];
    if (function_exists('ap_as2_ensure_top_context')) {
        $activity = ap_as2_ensure_top_context($activity);
    }
    return $activity;
}

/** Look up a stored boost by its Announce activity id. */
function ap_masto_reblog_row_by_announce_id(string $announceActivityId, ?int $ownerUserId = null): ?array
{
    $announceActivityId = trim($announceActivityId);
    if ($announceActivityId === '') {
        return null;
    }
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    try {
        $st = ap_db()->prepare(
            'SELECT * FROM masto_reblogs
             WHERE owner_user_id = ? AND (announce_activity_id = ? OR announce_activity_id = ?)'
        );
        $st->execute([$ownerUserId, $announceActivityId, rtrim($announceActivityId, '/')]);
        $row = $st->fetch();
        return is_array($row) ? $row : null;
    } catch (Throwable $e) {
        return null;
    }
}

/**
 * Event-table backfill for boosts is intentionally a no-op.
 *
 * Older Announce rows only record action_taken=boost_ok — not the real
 * announce activity id — so reconstructing them invented fake boosts (and
 * made accidental test Announces reappear in Ice Cubes). Live boosts already
 * write masto_reblogs with the real announce id.
 *
 * @return int always 0
 */
function ap_masto_backfill_reblogs_from_events(): int
{
    return 0;
}

/**
 * Ensure outbox blog/note (and compose) rows exist in masto_statuses so Ice Cubes
 * profile/timelines see site shares. Idempotent.
 * @return int number of newly registered rows
 */
function ap_masto_backfill_outbox_statuses(): int
{
    $st = ap_db()->query(
        "SELECT id, create_id, published, content, COALESCE(kind, 'compose') AS kind
         FROM outbox_notes
         WHERE COALESCE(kind, 'compose') IN ('compose', 'blog', 'note')
         ORDER BY published ASC"
    );
    $added = 0;
    foreach ($st->fetchAll() as $row) {
        $noteId = (string) ($row['id'] ?? '');
        if ($noteId === '' || ap_masto_status_by_note_id($noteId)) {
            continue;
        }
        $html = (string) ($row['content'] ?? '');
        $text = trim(html_entity_decode(strip_tags($html), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        $text = preg_replace('/\s+/u', ' ', $text) ?? $text;
        if ($text === '') {
            $text = '(shared post)';
        }
        ap_masto_status_register(
            $noteId,
            (string) ($row['create_id'] ?? ''),
            (string) ($row['published'] ?? gmdate('c')),
            $text
        );
        $added++;
    }
    return $added;
}

/** @return array{blog_posts:int,notes:int} */
function ap_site_content_counts(): array
{
    $defaults = ['blog_posts' => 0, 'notes' => 0];
    $path = dirname(__DIR__) . '/assets/data/site-counts.json';
    if (!is_readable($path)) {
        return $defaults;
    }
    $j = json_decode((string) file_get_contents($path), true);
    if (!is_array($j)) {
        return $defaults;
    }
    return [
        'blog_posts' => max(0, (int) ($j['blog_posts'] ?? 0)),
        'notes' => max(0, (int) ($j['notes'] ?? 0)),
    ];
}

function ap_compose_post_count(): int
{
    try {
        // Public discovery count: fully public compose notes only (exclude unlisted/private)
        $row = ap_db()->query(
            "SELECT COUNT(*) AS c FROM outbox_notes
             WHERE COALESCE(kind, 'compose') = 'compose'
               AND COALESCE(visibility, 'public') = 'public'"
        )->fetch();
        return (int) ($row['c'] ?? 0);
    } catch (Throwable $e) {
        return 0;
    }
}

/** Public “Posts” stat: site blogs + notes + AP compose (no archives, no double-count). */
function ap_public_post_count(): int
{
    $c = ap_site_content_counts();
    return (int) $c['blog_posts'] + (int) $c['notes'] + ap_compose_post_count();
}

/** JSON-LD context fragment for FEP-044f / GTS quote policies (Mastodon-compatible). */
function ap_quote_ld_context(): array
{
    return [
        'gts' => 'https://gotosocial.org/ns#',
        'interactionPolicy' => ['@id' => 'gts:interactionPolicy', '@type' => '@id'],
        'canQuote' => ['@id' => 'gts:canQuote', '@type' => '@id'],
        'automaticApproval' => ['@id' => 'gts:automaticApproval', '@type' => '@id'],
        'QuoteAuthorization' => 'https://w3id.org/fep/044f#QuoteAuthorization',
        'QuoteRequest' => 'https://w3id.org/fep/044f#QuoteRequest',
        'interactingObject' => ['@id' => 'gts:interactingObject', '@type' => '@id'],
        'interactionTarget' => ['@id' => 'gts:interactionTarget', '@type' => '@id'],
        'quote' => ['@id' => 'https://w3id.org/fep/044f#quote', '@type' => '@id'],
        'quoteAuthorization' => ['@id' => 'https://w3id.org/fep/044f#quoteAuthorization', '@type' => '@id'],
    ];
}

/** Anyone can quote (Mastodon “public” policy). */
function ap_note_interaction_policy_public(): array
{
    return [
        'canQuote' => [
            'automaticApproval' => ['https://www.w3.org/ns/activitystreams#Public'],
        ],
    ];
}

/**
 * Unwrap single-element arrays on AS2 scalar fields.
 * Bridgy Fed rejects content/published/url when they are arrays (often from
 * nested @context + JSON-LD expansion, or accidental wrapping).
 *
 * @param array<string,mixed> $obj
 * @return array<string,mixed>
 */
function ap_as2_normalize_scalars(array $obj): array
{
    $scalarKeys = [
        'content', 'published', 'updated', 'url', 'summary', 'name',
        'attributedTo', 'inReplyTo', 'mediaType', 'sensitive',
    ];
    foreach ($scalarKeys as $key) {
        if (!array_key_exists($key, $obj)) {
            continue;
        }
        $v = $obj[$key];
        // url may legitimately be a Link object — leave objects alone
        if (is_array($v) && $v !== [] && array_is_list($v) && count($v) === 1) {
            $only = $v[0];
            if (is_string($only) || is_int($only) || is_float($only) || is_bool($only) || $only === null) {
                $obj[$key] = $only;
            }
        }
    }
    return $obj;
}

/**
 * Ensure top-level AS2 document has AS + quote LD context (never nest this on
 * Create.object — Bridgy Fed / JSON-LD expanders turn scalars into arrays).
 *
 * @param array<string,mixed> $doc
 * @return array<string,mixed>
 */
function ap_as2_ensure_top_context(array $doc): array
{
    $ctx = $doc['@context'] ?? null;
    if ($ctx === null || $ctx === '') {
        $doc['@context'] = [
            'https://www.w3.org/ns/activitystreams',
            ap_quote_ld_context(),
        ];
        return $doc;
    }
    if (is_string($ctx)) {
        $doc['@context'] = [$ctx, ap_quote_ld_context()];
        return $doc;
    }
    if (is_array($ctx)) {
        $hasGts = false;
        foreach ($ctx as $c) {
            if (is_array($c) && (isset($c['gts']) || isset($c['interactionPolicy']))) {
                $hasGts = true;
                break;
            }
        }
        if (!$hasGts) {
            $ctx[] = ap_quote_ld_context();
            $doc['@context'] = $ctx;
        }
    }
    return $doc;
}

/**
 * Advertise public quote policy on a Note. Does NOT attach @context — call
 * ap_as2_ensure_top_context only on the outer Create/Note document you serve.
 *
 * @param array<string,mixed> $note
 * @return array<string,mixed>
 */
function ap_note_ensure_quote_policy(array $note): array
{
    unset($note['@context']); // never embed context on nested objects
    if (empty($note['interactionPolicy'])) {
        $note['interactionPolicy'] = ap_note_interaction_policy_public();
    }
    return ap_as2_normalize_scalars($note);
}

/**
 * Finalize a Create activity for storage/delivery: top-level context only,
 * nested Note without @context, scalar fields as strings.
 *
 * @param array<string,mixed> $create
 * @return array<string,mixed>
 */
function ap_create_finalize(array $create): array
{
    $create = ap_as2_normalize_scalars($create);
    if (isset($create['object']) && is_array($create['object'])) {
        $create['object'] = ap_note_ensure_quote_policy($create['object']);
    }
    $create = ap_as2_ensure_top_context($create);
    return $create;
}

/**
 * @return array{ok:bool,id?:string,error?:string}
 */
function ap_quote_auth_create(string $quotedNoteId, string $quotingObjectId, string $requesterActor): array
{
    $quotedNoteId = rtrim($quotedNoteId, '/');
    $quotingObjectId = rtrim($quotingObjectId, '/');
    if (!preg_match('#^https://mkultra\.monster/users/([A-Za-z0-9_]+)/notes/#', $quotedNoteId, $qm)) {
        return ['ok' => false, 'error' => 'Not a local note'];
    }
    $ownerActor = 'https://mkultra.monster/users/' . $qm[1];
    // Reuse existing stamp for same pair
    $st = ap_db()->prepare(
        'SELECT id FROM quote_authorizations WHERE quoted_note_id = ? AND quoting_object_id = ? AND deleted_at IS NULL'
    );
    $st->execute([$quotedNoteId, $quotingObjectId]);
    $existing = $st->fetch();
    if ($existing) {
        return ['ok' => true, 'id' => (string) $existing['id']];
    }
    $id = $ownerActor . '/quote_auth/' . bin2hex(random_bytes(8));
    try {
        ap_db()->prepare(
            'INSERT INTO quote_authorizations (id, created_at, quoted_note_id, quoting_object_id, requester_actor)
             VALUES (?, ?, ?, ?, ?)'
        )->execute([$id, ap_db_now(), $quotedNoteId, $quotingObjectId, $requesterActor]);
    } catch (Throwable $e) {
        return ['ok' => false, 'error' => $e->getMessage()];
    }
    return ['ok' => true, 'id' => $id];
}

function ap_quote_auth_get(string $id): ?array
{
    $st = ap_db()->prepare('SELECT * FROM quote_authorizations WHERE id = ? AND deleted_at IS NULL');
    $st->execute([$id]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_quote_auth_document(array $row): array
{
    $quoted = (string) ($row['quoted_note_id'] ?? '');
    $attributedTo = 'https://mkultra.monster/users/cmdr_nova';
    if (preg_match('#^(https://mkultra\.monster/users/[A-Za-z0-9_]+)/#', $quoted, $am)) {
        $attributedTo = $am[1];
    }
    return [
        '@context' => [
            'https://www.w3.org/ns/activitystreams',
            ap_quote_ld_context(),
        ],
        'type' => 'QuoteAuthorization',
        'id' => (string) $row['id'],
        'attributedTo' => $attributedTo,
        'interactingObject' => (string) $row['quoting_object_id'],
        'interactionTarget' => (string) $row['quoted_note_id'],
    ];
}

/* ----------------- Direct messages (private) ----------------- */

function ap_dm_peer_key(string $actorId): string
{
    return rtrim(trim($actorId), '/');
}

/**
 * Allowlist tags and strip all attributes except https href on <a>.
 * Use for any HTML echoed into VAAK / public profile pages.
 */
function ap_html_sanitize_allowlist(string $html, string $allowedTags = '<p><br><br/><ul><ol><li><em><i><strong><b><a><code><span>'): string
{
    $html = function_exists('ap_fix_utf8') ? ap_fix_utf8($html) : $html;
    if ($html === '') {
        return '';
    }
    $html = strip_tags($html, $allowedTags);
    $html = preg_replace_callback(
        '/<\/?([a-z0-9]+)(\s[^>]*)?>/i',
        static function (array $m): string {
            $tag = strtolower($m[1]);
            $isClose = str_starts_with($m[0], '</');
            if ($isClose) {
                return '</' . $tag . '>';
            }
            if ($tag === 'br') {
                return '<br>';
            }
            if ($tag === 'a') {
                $attrs = (string) ($m[2] ?? '');
                $href = '';
                if (preg_match('/href\s*=\s*([\'"])(https?:\/\/[^\'"]+)\1/i', $attrs, $hm)) {
                    $href = $hm[2];
                } elseif (preg_match('/href\s*=\s*(https?:\/\/[^\s>]+)/i', $attrs, $hm)) {
                    $href = $hm[1];
                }
                $href = html_entity_decode(trim($href), ENT_QUOTES | ENT_HTML5, 'UTF-8');
                if ($href === '' || !preg_match('#^https://#i', $href)) {
                    return '<a>';
                }
                $safe = htmlspecialchars($href, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                return '<a href="' . $safe . '" rel="nofollow noopener noreferrer">';
            }
            return '<' . $tag . '>';
        },
        $html
    ) ?? $html;
    return preg_replace('#<a>(.*?)</a>#isu', '$1', $html) ?? $html;
}

/**
 * Keep Bridgy/Mastodon DM HTML usable: allow formatting + https links only.
 */
function ap_dm_sanitize_html(string $html): string
{
    $html = ap_html_sanitize_allowlist(
        $html,
        '<p><br><br/><ul><ol><li><em><i><strong><b><a><span>'
    );
    // Bridgy pretty_link truncates URL labels (… / ...); expand from full href
    $html = preg_replace_callback(
        '#<a href="(https://[^"]+)"([^>]*)>(.*?)</a>#isu',
        static function (array $m): string {
            $href = html_entity_decode($m[1], ENT_QUOTES | ENT_HTML5, 'UTF-8');
            $inner = $m[3];
            $plain = trim(html_entity_decode(strip_tags($inner), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
            $trunc = str_ends_with($plain, '...') || str_ends_with($plain, '…');
            $urlish = (bool) preg_match('#^(https?://|[a-z0-9.-]+\.[a-z]{2,}/)#i', $plain);
            if ($trunc && $urlish && $href !== '') {
                $label = preg_replace('#^https://#i', '', $href) ?? $href;
                $inner = htmlspecialchars($label, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            }
            $safe = htmlspecialchars($href, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            return '<a href="' . $safe . '" target="_blank" rel="noopener noreferrer nofollow">' . $inner . '</a>';
        },
        $html
    ) ?? $html;
    return mb_substr($html, 0, 20000);
}

/**
 * Pull Bridgy Fed bf:respond / bf:like / bf:repost / bf:reply / bf:block URLs
 * from AS2 attachment objects and return sanitized action-link HTML.
 *
 * @param mixed $attachments
 */
function ap_dm_action_links_html(mixed $attachments): string
{
    if (!is_array($attachments)) {
        return '';
    }
    if (isset($attachments['type']) || isset($attachments['url']) || isset($attachments['href'])) {
        $attachments = [$attachments];
    }
    $blocks = [];
    foreach ($attachments as $att) {
        if (!is_array($att)) {
            continue;
        }
        $map = [
            'respond' => null,
            'reply' => null,
            'like' => null,
            'repost' => null,
            'block' => null,
        ];
        foreach ($att as $k => $v) {
            if (!is_string($k) || !is_string($v) || !str_starts_with($v, 'https://')) {
                continue;
            }
            $lk = strtolower($k);
            foreach (array_keys($map) as $action) {
                if ($lk === $action || $lk === 'bf:' . $action || str_ends_with($lk, ':' . $action)) {
                    $map[$action] = $v;
                }
            }
            // Path-based fallback: …/respond/like?…
            if (preg_match('#/respond/(reply|like|repost|block)(?:\?|$)#i', $v, $mm)) {
                $map[strtolower($mm[1])] = $map[strtolower($mm[1])] ?? $v;
            } elseif (preg_match('#/respond(?:\?|$)#i', $v)) {
                $map['respond'] = $map['respond'] ?? $v;
            }
        }
        $parts = [];
        foreach (['respond', 'reply', 'like', 'repost', 'block'] as $action) {
            $url = $map[$action];
            if (!is_string($url) || $url === '') {
                continue;
            }
            $safe = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $parts[] = '<a href="' . $safe . '" target="_blank" rel="noopener noreferrer nofollow">' . $action . '</a>';
        }
        if ($parts) {
            $blocks[] = '<p class="dm-actions">' . implode(' · ', $parts) . '</p>';
        }
    }
    return implode("\n", $blocks);
}

/**
 * Autolink bare https:// and common host/path URLs inside DM HTML without
 * touching existing tags/anchors. Used for Ice Cubes + admin when content was
 * stored as plain text (legacy Bridgy strip_tags) or Mastodon plain DMs.
 */
function ap_dm_linkify_html(string $html): string
{
    $html = ap_fix_utf8($html);
    if ($html === '') {
        return '';
    }

    $makeLink = static function (string $href, string $label): string {
        $href = html_entity_decode($href, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $href = rtrim($href, '.,;:!?)]}\'"');
        $label = rtrim($label, '.,;:!?)]}\'"');
        if ($href === '' || !preg_match('#^https://#i', $href)) {
            return htmlspecialchars($label, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        // Truncated leftovers are not real links
        if (str_ends_with($label, '...') || str_ends_with($label, '…')
            || str_contains($label, '...') || str_contains($label, '…')
            || str_ends_with($href, '...') || str_contains($href, '...')) {
            return htmlspecialchars($label, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        $safe = htmlspecialchars($href, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $labSrc = $label !== '' ? $label : (preg_replace('#^https://#i', '', $href) ?? $href);
        $lab = htmlspecialchars($labSrc, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        return '<a href="' . $safe . '" target="_blank" rel="noopener noreferrer nofollow">' . $lab . '</a>';
    };

    $linkifyText = static function (string $text) use ($makeLink): string {
        if ($text === '' || (!str_contains($text, 'http') && !str_contains($text, '/'))) {
            return $text;
        }
        $text = preg_replace_callback(
            '#https://[^\s<]+#iu',
            static function (array $m) use ($makeLink): string {
                $raw = html_entity_decode($m[0], ENT_QUOTES | ENT_HTML5, 'UTF-8');
                if (str_contains($raw, '...')) {
                    return $m[0];
                }
                return $makeLink($raw, $raw);
            },
            $text
        ) ?? $text;
        // Only linkify after https pass; skip inside any anchors we just added
        $parts = preg_split('#(<a\b[^>]*>.*?</a>)#isu', $text, -1, PREG_SPLIT_DELIM_CAPTURE);
        if (!is_array($parts)) {
            return $text;
        }
        $out = '';
        foreach ($parts as $part) {
            if ($part === '' || str_starts_with($part, '<a ')) {
                $out .= $part;
                continue;
            }
            $out .= preg_replace_callback(
                '#\b((?:bsky\.app|bluesky\.social|[a-z0-9-]+(?:\.[a-z0-9-]+)+)/(?:[^\s<]+))#iu',
                static function (array $m) use ($makeLink): string {
                    $path = html_entity_decode($m[1], ENT_QUOTES | ENT_HTML5, 'UTF-8');
                    if (str_contains($path, '...') || str_contains($path, '…') || str_contains($path, '..')) {
                        return $m[0];
                    }
                    return $makeLink('https://' . $path, $path);
                },
                $part
            ) ?? $part;
        }
        return $out;
    };

    // Split into tags vs text so we never rewrite inside href="..."
    $parts = preg_split('#(<[^>]+>)#u', $html, -1, PREG_SPLIT_DELIM_CAPTURE);
    if (!is_array($parts)) {
        return $html;
    }
    $out = '';
    $inAnchor = false;
    foreach ($parts as $part) {
        if ($part === '') {
            continue;
        }
        if (str_starts_with($part, '<')) {
            if (preg_match('#^<a\b#i', $part)) {
                $inAnchor = true;
            } elseif (preg_match('#^</a\b#i', $part)) {
                $inAnchor = false;
            }
            $out .= $part;
            continue;
        }
        $out .= $inAnchor ? $part : $linkifyText($part);
    }
    return $out;
}

/**
 * @param array{activity_id?:?string,object_id:string,peer_actor_id:string,direction:string,content?:?string,in_reply_to?:?string,media_urls?:?list<string>|string,attachments?:mixed,created_at?:?string,read_at?:?string,owner_user_id?:int,owner_actor_id?:string} $row
 * @return array{ok:bool,error?:string,id?:int}
 */
function ap_dm_store(array $row): array
{
    $objectId = trim((string) ($row['object_id'] ?? ''));
    $peer = ap_dm_peer_key((string) ($row['peer_actor_id'] ?? ''));
    $direction = (($row['direction'] ?? '') === 'out') ? 'out' : 'in';
    if ($objectId === '' || $peer === '' || !str_starts_with($peer, 'https://')) {
        return ['ok' => false, 'error' => 'Invalid DM fields'];
    }
    if (ap_is_blocked_actor($peer)) {
        return ['ok' => false, 'error' => 'Peer is blocked'];
    }
    $ownerUserId = (int) ($row['owner_user_id'] ?? 0);
    if ($ownerUserId < 1) {
        $ownerHint = (string) ($row['owner_actor_id'] ?? '');
        if ($ownerHint === '' && function_exists('ap_local_actor_id')) {
            $ownerHint = ap_local_actor_id();
        }
        $ownerUserId = $ownerHint !== ''
            ? ap_db_owner_user_id_for_actor($ownerHint)
            : ap_db_default_owner_user_id();
    }
    $ownerActorId = rtrim((string) ($row['owner_actor_id'] ?? ''), '/');
    if ($ownerActorId === '') {
        $ownerActorId = ap_db_owner_actor_id_for_user_id($ownerUserId);
    }
    $rawContent = isset($row['content']) ? ap_fix_utf8((string) $row['content']) : '';
    $actionHtml = '';
    if (array_key_exists('attachments', $row)) {
        $actionHtml = ap_dm_action_links_html($row['attachments']);
    }
    // Prefer HTML (Bridgy digest links); fall back to Mastodon-style <p>/<br>.
    // Never nl2br a whole blob into one <p> — Ice Cubes treats <br><br> (and often
    // even single <br>) as huge vertical gaps in the DM thread view.
    if ($rawContent !== '' && (str_contains($rawContent, '<a ') || str_contains($rawContent, '<p>') || str_contains($rawContent, '<ul'))) {
        $content = ap_dm_sanitize_html($rawContent);
        if (function_exists('ap_normalize_status_html')) {
            $content = ap_normalize_status_html($content);
        }
    } elseif ($rawContent !== '') {
        $plain = trim(html_entity_decode(strip_tags($rawContent), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        if ($plain !== '') {
            $content = function_exists('ap_plain_text_to_html')
                ? ap_plain_text_to_html($plain)
                : ('<p>' . htmlspecialchars($plain, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</p>');
            if (function_exists('ap_normalize_status_html')) {
                $content = ap_normalize_status_html($content);
            }
            $content = ap_dm_sanitize_html($content);
        } else {
            $content = null;
        }
    } else {
        $content = null;
    }
    if ($actionHtml !== '') {
        // Bridgy body already has a /respond href — still append like/repost/block
        // unless we already injected the dm-actions row.
        $hasActions = is_string($content) && str_contains($content, 'class="dm-actions"');
        if (!$hasActions) {
            $content = trim((string) $content . "\n" . $actionHtml);
            $content = ap_dm_sanitize_html($content);
        }
    }
    if ($content === '') {
        $content = null;
    }
    $attachmentsJson = null;
    if (array_key_exists('attachments', $row) && $row['attachments'] !== null) {
        $enc = json_encode($row['attachments'], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if (is_string($enc) && strlen($enc) < 100000) {
            $attachmentsJson = $enc;
        }
    }
    $mediaUrls = null;
    if (!empty($row['media_urls'])) {
        if (is_string($row['media_urls'])) {
            $decoded = json_decode($row['media_urls'], true);
            $list = is_array($decoded) ? $decoded : [];
        } else {
            $list = is_array($row['media_urls']) ? $row['media_urls'] : [];
        }
        $clean = [];
        foreach ($list as $u) {
            $s = ap_profile_sanitize_https_url($u);
            if ($s !== null) {
                $clean[] = $s;
            }
            if (count($clean) >= 4) {
                break;
            }
        }
        if ($clean) {
            $mediaUrls = json_encode($clean, JSON_UNESCAPED_SLASHES);
        }
    }
    $created = (string) ($row['created_at'] ?? ap_db_now());
    $readAt = $direction === 'out' ? $created : ($row['read_at'] ?? null);
    try {
        ap_db()->prepare(
            'INSERT INTO direct_messages (owner_user_id, owner_actor_id, created_at, activity_id, object_id, peer_actor_id, direction, content, in_reply_to, media_urls, read_at, deleted_at, attachments_json)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?)
             ON CONFLICT(owner_user_id, object_id) DO UPDATE SET
               owner_actor_id = COALESCE(excluded.owner_actor_id, direct_messages.owner_actor_id),
               content = COALESCE(excluded.content, direct_messages.content),
               media_urls = COALESCE(excluded.media_urls, direct_messages.media_urls),
               attachments_json = COALESCE(excluded.attachments_json, direct_messages.attachments_json),
               deleted_at = NULL'
        )->execute([
            $ownerUserId,
            $ownerActorId,
            $created,
            $row['activity_id'] ?? null,
            $objectId,
            $peer,
            $direction,
            $content,
            $row['in_reply_to'] ?? null,
            $mediaUrls,
            $readAt,
            $attachmentsJson,
        ]);
        $st = ap_db()->prepare(
            'SELECT id FROM direct_messages WHERE owner_user_id = ? AND object_id = ?'
        );
        $st->execute([$ownerUserId, $objectId]);
        $id = (int) ($st->fetch()['id'] ?? 0);
        return ['ok' => true, 'id' => $id];
    } catch (Throwable $e) {
        return ['ok' => false, 'error' => $e->getMessage()];
    }
}

function ap_dm_soft_delete_by_object(string $objectId, ?int $ownerUserId = null): void
{
    if ($ownerUserId !== null && $ownerUserId > 0) {
        ap_db()->prepare(
            'UPDATE direct_messages SET deleted_at = ? WHERE owner_user_id = ? AND object_id = ? AND deleted_at IS NULL'
        )->execute([ap_db_now(), $ownerUserId, $objectId]);
        return;
    }
    ap_db()->prepare('UPDATE direct_messages SET deleted_at = ? WHERE object_id = ? AND deleted_at IS NULL')
        ->execute([ap_db_now(), $objectId]);
}

function ap_dm_by_id(int $id, ?int $ownerUserId = null): ?array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $st = ap_db()->prepare(
        'SELECT * FROM direct_messages WHERE id = ? AND owner_user_id = ? AND deleted_at IS NULL'
    );
    $st->execute([$id, $ownerUserId]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_dm_by_object_id(string $objectId, ?int $ownerUserId = null): ?array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $st = ap_db()->prepare(
        'SELECT * FROM direct_messages WHERE owner_user_id = ? AND object_id = ? AND deleted_at IS NULL'
    );
    $st->execute([$ownerUserId, $objectId]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

/** @return list<array<string,mixed>> */
function ap_dm_list_recent(int $limit = 80, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $limit = max(1, min(200, $limit));
    $st = ap_db()->prepare(
        'SELECT * FROM direct_messages WHERE owner_user_id = ? AND deleted_at IS NULL ORDER BY id DESC LIMIT ?'
    );
    $st->execute([$ownerUserId, $limit]);
    $out = [];
    foreach ($st->fetchAll() as $row) {
        if (ap_is_blocked_actor((string) ($row['peer_actor_id'] ?? ''))) {
            continue;
        }
        $out[] = $row;
    }
    return $out;
}

/** @return list<array<string,mixed>> */
function ap_dm_thread(string $peerActorId, int $limit = 100, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $peer = ap_dm_peer_key($peerActorId);
    $limit = max(1, min(200, $limit));
    $st = ap_db()->prepare(
        'SELECT * FROM direct_messages
         WHERE owner_user_id = ? AND deleted_at IS NULL AND peer_actor_id = ?
         ORDER BY id ASC LIMIT ?'
    );
    $st->execute([$ownerUserId, $peer, $limit]);
    return $st->fetchAll();
}

/**
 * Conversation list for Mastodon API / admin.
 * @return list<array{peer_actor_id:string,last:array,unread:int}>
 */
function ap_dm_conversations(int $limit = 40, ?int $ownerUserId = null): array
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $limit = max(1, min(80, $limit));
    $st = ap_db()->prepare(
        'SELECT peer_actor_id, MAX(id) AS last_id, SUM(CASE WHEN direction = \'in\' AND read_at IS NULL THEN 1 ELSE 0 END) AS unread
         FROM direct_messages
         WHERE owner_user_id = ? AND deleted_at IS NULL
         GROUP BY peer_actor_id
         ORDER BY last_id DESC
         LIMIT 200'
    );
    $st->execute([$ownerUserId]);
    $out = [];
    foreach ($st->fetchAll() as $row) {
        $peer = (string) $row['peer_actor_id'];
        if (ap_is_blocked_actor($peer)) {
            continue;
        }
        $last = ap_dm_by_id((int) $row['last_id'], $ownerUserId);
        if (!$last) {
            continue;
        }
        $out[] = [
            'peer_actor_id' => $peer,
            'last' => $last,
            'unread' => (int) ($row['unread'] ?? 0),
            'last_id' => (int) $row['last_id'],
        ];
        if (count($out) >= $limit) {
            break;
        }
    }
    return $out;
}

function ap_dm_mark_peer_read(string $peerActorId, ?int $ownerUserId = null): void
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $peer = ap_dm_peer_key($peerActorId);
    if ($peer === '' || !str_starts_with($peer, 'https://')) {
        return;
    }
    $now = ap_db_now();
    $sql = 'UPDATE direct_messages SET read_at = ?
            WHERE owner_user_id = ? AND peer_actor_id = ? AND direction = \'in\'
              AND read_at IS NULL AND deleted_at IS NULL';
    $last = null;
    for ($attempt = 0; $attempt < 8; $attempt++) {
        try {
            ap_db()->prepare($sql)->execute([$now, $ownerUserId, $peer]);
            return;
        } catch (Throwable $e) {
            $last = $e;
            $msg = $e->getMessage();
            // SQLITE_BUSY / "database is locked" — inbox writers win briefly
            if (!str_contains($msg, 'database is locked') && !str_contains($msg, 'SQLITE_BUSY')) {
                throw $e;
            }
            usleep(100000 * ($attempt + 1)); // 100ms … ~3.6s total
        }
    }
    if ($last instanceof Throwable) {
        throw $last;
    }
}

function ap_dm_unread_count(?int $ownerUserId = null): int
{
    $ownerUserId = $ownerUserId ?? ap_db_default_owner_user_id();
    $st = ap_db()->prepare(
        "SELECT COUNT(*) AS c FROM direct_messages
         WHERE owner_user_id = ? AND deleted_at IS NULL AND direction = 'in' AND read_at IS NULL"
    );
    $st->execute([$ownerUserId]);
    $row = $st->fetch();
    return (int) ($row['c'] ?? 0);
}

function ap_dm_conversation_id(string $peerActorId): string
{
    return (string) (500000000 + ((int) sprintf('%u', crc32(ap_dm_peer_key($peerActorId))) % 400000000));
}

function ap_dm_peer_from_conversation_id(string $id, ?int $ownerUserId = null): ?string
{
    $want = (int) $id;
    foreach (ap_dm_conversations(200, $ownerUserId) as $c) {
        if ((int) ap_dm_conversation_id($c['peer_actor_id']) === $want) {
            return $c['peer_actor_id'];
        }
    }
    return null;
}

/* ----------------- Remote actor + media cache metadata ----------------- */

function ap_remote_actor_get(string $actorId): ?array
{
    $actorId = rtrim(trim($actorId), '/');
    $st = ap_db()->prepare('SELECT * FROM remote_actors WHERE actor_id = ?');
    $st->execute([$actorId]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

/** True when a cached username is useless (path DID, empty, etc.). */
function ap_remote_actor_username_is_placeholder(?string $username): bool
{
    $username = trim((string) $username);
    if ($username === '' || $username === 'user') {
        return true;
    }
    if (str_starts_with(strtolower($username), 'did:')) {
        return true;
    }
    // Raw path segment leftovers
    if (preg_match('/^did%3a/i', $username)) {
        return true;
    }
    return false;
}

/**
 * @param array{username?:?string,display_name?:?string,host?:?string,icon_source_url?:?string,image_source_url?:?string} $fields
 */
function ap_remote_actor_upsert(string $actorId, array $fields): void
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://')) {
        return;
    }
    $existing = ap_remote_actor_get($actorId);
    $incomingUser = isset($fields['username']) && is_string($fields['username']) ? trim($fields['username']) : null;
    if ($incomingUser !== null && ap_remote_actor_username_is_placeholder($incomingUser)) {
        $incomingUser = null; // don't write DIDs over real handles
    }
    $existingUser = is_array($existing) && isset($existing['username']) ? (string) $existing['username'] : null;
    if ($existingUser !== null && ap_remote_actor_username_is_placeholder($existingUser)) {
        $existingUser = null;
    }
    $username = $incomingUser ?? $existingUser;

    $incomingDisplay = isset($fields['display_name']) && is_string($fields['display_name']) ? trim($fields['display_name']) : null;
    if ($incomingDisplay === '') {
        $incomingDisplay = null;
    }
    $display = $incomingDisplay ?? (is_array($existing) ? ($existing['display_name'] ?? null) : null);

    $host = $fields['host'] ?? ($existing['host'] ?? null);
    $icon = $fields['icon_source_url'] ?? ($existing['icon_source_url'] ?? null);
    $image = $fields['image_source_url'] ?? ($existing['image_source_url'] ?? null);
    if (is_string($icon)) {
        $icon = ap_profile_sanitize_https_url($icon);
    }
    if (is_string($image)) {
        $image = ap_profile_sanitize_https_url($image);
    }
    $sql = 'INSERT INTO remote_actors (actor_id, username, display_name, host, icon_source_url, image_source_url, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(actor_id) DO UPDATE SET
           username = COALESCE(excluded.username, remote_actors.username),
           display_name = COALESCE(excluded.display_name, remote_actors.display_name),
           host = COALESCE(excluded.host, remote_actors.host),
           icon_source_url = COALESCE(excluded.icon_source_url, remote_actors.icon_source_url),
           image_source_url = COALESCE(excluded.image_source_url, remote_actors.image_source_url),
           updated_at = excluded.updated_at';
    // Best-effort cache write: never take down admin HTML mid-render on lock.
    if (ap_db_execute_retry($sql, [$actorId, $username, $display, $host, $icon, $image, ap_db_now()]) === false) {
        error_log('[ap-db] remote_actor_upsert skipped (locked): ' . $actorId);
    }
}

/**
 * Ensure we have a human username for an actor (esp. Bridgy Fed Bluesky DIDs).
 * Fetches the AS2 actor doc when cache is missing or still a did:plc placeholder.
 *
 * @return array{actor_id:string,username:?string,display_name:?string,host:?string,icon_source_url:?string,image_source_url:?string}|null
 */
function ap_remote_actor_ensure(string $actorId, bool $allowFetch = true): ?array
{
    $actorId = rtrim(trim($actorId), '/');
    if ($actorId === '' || !str_starts_with($actorId, 'https://')) {
        return null;
    }
    static $memo = [];
    if (isset($memo[$actorId])) {
        return $memo[$actorId];
    }
    $row = ap_remote_actor_get($actorId);
    // Refresh profile metadata periodically even when a usable row exists.
    // Timeline requests pass allowFetch=false, while background warmers and
    // profile views can keep names/bios/media source URLs current.
    $updatedAt = is_array($row) ? (strtotime((string) ($row['updated_at'] ?? '')) ?: 0) : 0;
    $needsFetch = $allowFetch && (
        $row === null
        || ap_remote_actor_username_is_placeholder($row['username'] ?? null)
        || (str_contains($actorId, 'bsky.brid.gy/ap/did:') && ap_remote_actor_username_is_placeholder($row['username'] ?? null))
        || $updatedAt < (time() - 12 * 3600)
    );
    if ($needsFetch && function_exists('ap_fetch_as2_object')) {
        try {
            $doc = ap_fetch_as2_object($actorId);
            if (is_array($doc)) {
                $uname = null;
                if (!empty($doc['preferredUsername']) && is_string($doc['preferredUsername'])) {
                    $uname = trim($doc['preferredUsername']);
                }
                $dname = null;
                if (!empty($doc['name']) && is_string($doc['name'])) {
                    $dname = trim($doc['name']);
                }
                $icon = null;
                if (isset($doc['icon'])) {
                    if (is_array($doc['icon']) && !empty($doc['icon']['url']) && is_string($doc['icon']['url'])) {
                        $icon = $doc['icon']['url'];
                    } elseif (is_string($doc['icon'])) {
                        $icon = $doc['icon'];
                    }
                }
                $image = null;
                if (isset($doc['image'])) {
                    if (is_array($doc['image']) && !empty($doc['image']['url']) && is_string($doc['image']['url'])) {
                        $image = $doc['image']['url'];
                    } elseif (is_string($doc['image'])) {
                        $image = $doc['image'];
                    }
                }
                $host = parse_url($actorId, PHP_URL_HOST);
                ap_remote_actor_upsert($actorId, [
                    'username' => ($uname !== null && $uname !== '') ? $uname : null,
                    'display_name' => ($dname !== null && $dname !== '') ? $dname : null,
                    'host' => is_string($host) ? strtolower($host) : null,
                    'icon_source_url' => $icon,
                    'image_source_url' => $image,
                ]);
                if (function_exists('ap_remote_emoji_ingest_actor_doc')) {
                    ap_remote_emoji_ingest_actor_doc($actorId, $doc);
                }
                $row = ap_remote_actor_get($actorId);
            }
        } catch (Throwable $e) {
            error_log('[ap-db] remote_actor_ensure: ' . $e->getMessage());
        }
    }
    // Display names with :shortcodes: → ensure we have emoji URLs (actor tags or instance API)
    if (
        $allowFetch
        && is_array($row)
        && function_exists('ap_remote_emoji_ensure_for_display')
        && !empty($row['display_name'])
        && str_contains((string) $row['display_name'], ':')
    ) {
        ap_remote_emoji_ensure_for_display($actorId, (string) $row['display_name']);
    }
    $memo[$actorId] = $row;
    return $row;
}

/**
 * Human-friendly label bits for timelines.
 *
 * @return array{username:string,display_name:string,host:string,handle:string,acct:string}
 */
function ap_remote_actor_label(string $actorId, bool $allowFetch = true): array
{
    $actorId = rtrim(trim($actorId), '/');
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : '';
    $path = trim((string) (parse_url($actorId, PHP_URL_PATH) ?? ''), '/');
    $seg = $path !== '' ? (basename($path) ?: 'user') : 'user';
    $username = $seg;
    $display = $seg;

    $row = ap_remote_actor_ensure($actorId, $allowFetch);
    if (is_array($row)) {
        if (!ap_remote_actor_username_is_placeholder($row['username'] ?? null)) {
            $username = (string) $row['username'];
        }
        if (!empty($row['display_name']) && trim((string) $row['display_name']) !== '') {
            $display = (string) $row['display_name'];
        } else {
            $display = $username;
        }
        if (!empty($row['host'])) {
            $host = strtolower((string) $row['host']);
        }
    }

    // Bridgy Fed: preferredUsername is already alice.bsky.social — avoid @alice.bsky.social@bsky.brid.gy when possible
    $acctHost = $host;
    $handleUser = $username;
    if ($host !== '' && (str_ends_with($host, 'brid.gy') || $host === 'brid.gy')
        && str_contains($username, '.')
        && !str_starts_with(strtolower($username), 'did:')) {
        // Show @alice.bsky.social (Bluesky handle) as the primary handle text
        $handle = '@' . $username;
        $acct = $username . '@' . $host; // still unique for AP
    } else {
        $handle = ($host !== '') ? ('@' . $username . '@' . $host) : ('@' . $username);
        $acct = ($host !== '') ? ($username . '@' . $host) : $username;
    }

    return [
        'username' => $username,
        'display_name' => $display,
        'host' => $host,
        'handle' => $handle,
        'acct' => $acct,
    ];
}

/* ----------------- Remote custom emojis (:shortcode: → image URL) ----------------- */

/**
 * @param list<array{shortcode:string,url:string,static_url?:?string}> $items
 */
function ap_remote_emoji_upsert_batch(string $host, array $items): void
{
    $host = strtolower(trim($host));
    if ($host === '' || !$items) {
        return;
    }
    $now = ap_db_now();
    $st = ap_db()->prepare(
        'INSERT INTO remote_custom_emojis (host, shortcode, url, static_url, updated_at)
         VALUES (?, ?, ?, ?, ?)
         ON CONFLICT(host, shortcode) DO UPDATE SET
           url = excluded.url,
           static_url = COALESCE(excluded.static_url, remote_custom_emojis.static_url),
           updated_at = excluded.updated_at'
    );
    foreach ($items as $it) {
        $code = trim((string) ($it['shortcode'] ?? ''), ": \t\n\r");
        $url = ap_profile_sanitize_https_url($it['url'] ?? null);
        if ($code === '' || $url === null) {
            continue;
        }
        if (!preg_match('/^[A-Za-z0-9_-]{1,80}$/', $code)) {
            continue;
        }
        $static = ap_profile_sanitize_https_url($it['static_url'] ?? null);
        $st->execute([$host, $code, $url, $static, $now]);
    }
    ap_remote_emoji_map_for_host($host, true);
}

/** Pull Emoji tags from an AS2 actor/Note document into the host emoji cache. */
function ap_remote_emoji_ingest_actor_doc(string $actorId, array $doc): int
{
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : '';
    if ($host === '') {
        return 0;
    }
    $tags = $doc['tag'] ?? [];
    if (!is_array($tags)) {
        return 0;
    }
    if (isset($tags['type'])) {
        $tags = [$tags];
    }
    $items = [];
    foreach ($tags as $tag) {
        if (!is_array($tag)) {
            continue;
        }
        $type = (string) ($tag['type'] ?? '');
        if ($type !== 'Emoji' && !str_ends_with($type, 'Emoji')) {
            continue;
        }
        $name = (string) ($tag['name'] ?? '');
        $icon = $tag['icon'] ?? null;
        $url = null;
        if (is_array($icon) && !empty($icon['url']) && is_string($icon['url'])) {
            $url = $icon['url'];
        } elseif (is_string($icon)) {
            $url = $icon;
        }
        if ($name === '' || $url === null) {
            continue;
        }
        $items[] = ['shortcode' => $name, 'url' => $url, 'static_url' => $url];
    }
    if (!$items) {
        return 0;
    }
    ap_remote_emoji_upsert_batch($host, $items);
    return count($items);
}

/** @return array<string,string> shortcode => url */
function ap_remote_emoji_map_for_host(string $host, bool $refresh = false): array
{
    $host = strtolower(trim($host));
    if ($host === '') {
        return [];
    }
    static $memo = [];
    if ($refresh) {
        unset($memo[$host]);
    }
    if (isset($memo[$host])) {
        return $memo[$host];
    }
    $map = [];
    $st = ap_db()->prepare('SELECT shortcode, url FROM remote_custom_emojis WHERE host = ?');
    $st->execute([$host]);
    foreach ($st->fetchAll() as $row) {
        $code = (string) ($row['shortcode'] ?? '');
        $url = (string) ($row['url'] ?? '');
        if ($code !== '' && str_starts_with($url, 'https://')) {
            $map[$code] = $url;
        }
    }
    $memo[$host] = $map;
    return $map;
}

/** Best-effort GET JSON (HTTPS only, short timeout). */
function ap_remote_emoji_http_json(string $url): ?array
{
    if (!str_starts_with($url, 'https://') || !function_exists('curl_init')) {
        return null;
    }
    $ch = curl_init($url);
    if ($ch === false) {
        return null;
    }
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_MAXREDIRS => 3,
        CURLOPT_TIMEOUT => 6,
        CURLOPT_CONNECTTIMEOUT => 3,
        CURLOPT_USERAGENT => 'mkultra.monster-emoji-cache/1.0 (+https://mkultra.monster)',
        CURLOPT_HTTPHEADER => ['Accept: application/json'],
        CURLOPT_PROTOCOLS => CURLPROTO_HTTPS,
        CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTPS,
    ]);
    $body = curl_exec($ch);
    $code = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    if (!is_string($body) || $body === '' || $code < 200 || $code >= 300) {
        return null;
    }
    $json = json_decode($body, true);
    return is_array($json) ? $json : null;
}

/**
 * Fetch Mastodon-compatible /api/v1/custom_emojis for a host (cached ~7d).
 * Wafrn etc. return 404 — actor tag ingest covers those.
 */
function ap_remote_emoji_ensure_host(string $host, bool $force = false, bool $allowFetch = false): void
{
    $host = strtolower(trim($host));
    if ($host === '' || str_contains($host, '/')) {
        return;
    }
    static $done = [];
    $doneKey = $host . ':' . ($allowFetch || $force ? '1' : '0');
    if (!$force && isset($done[$doneKey])) {
        return;
    }
    $done[$doneKey] = true;

    $meta = ap_db()->prepare('SELECT fetched_at, source FROM remote_emoji_host_meta WHERE host = ?');
    $meta->execute([$host]);
    $row = $meta->fetch();
    if (!$force && is_array($row) && !empty($row['fetched_at'])) {
        $age = time() - (strtotime((string) $row['fetched_at']) ?: 0);
        if ($age >= 0 && $age < 86400 * 7) {
            return; // fresh enough
        }
    }
    // Timeline/admin render must stay offline-fast (Federated was 30–50s on emoji HTTP).
    if (!$allowFetch && !$force) {
        return;
    }

    $json = ap_remote_emoji_http_json('https://' . $host . '/api/v1/custom_emojis');
    $source = 'none';
    if (is_array($json) && $json !== [] && array_is_list($json)) {
        $items = [];
        foreach ($json as $em) {
            if (!is_array($em)) {
                continue;
            }
            $items[] = [
                'shortcode' => (string) ($em['shortcode'] ?? ''),
                'url' => (string) ($em['url'] ?? ''),
                'static_url' => (string) ($em['static_url'] ?? $em['url'] ?? ''),
            ];
        }
        if ($items) {
            ap_remote_emoji_upsert_batch($host, $items);
            $source = 'masto';
        }
    }
    ap_db()->prepare(
        'INSERT INTO remote_emoji_host_meta (host, fetched_at, source) VALUES (?, ?, ?)
         ON CONFLICT(host) DO UPDATE SET fetched_at = excluded.fetched_at, source = excluded.source'
    )->execute([$host, ap_db_now(), $source]);
}

/**
 * Ensure shortcodes in a display name are resolvable (instance API + actor AS2 tags).
 */
function ap_remote_emoji_ensure_for_display(string $actorId, string $displayName, bool $allowFetch = false): void
{
    $actorId = rtrim(trim($actorId), '/');
    $host = parse_url($actorId, PHP_URL_HOST);
    $host = is_string($host) ? strtolower($host) : '';
    if ($host === '' || !preg_match_all('/:([A-Za-z0-9_-]{1,80}):/', $displayName, $mm)) {
        return;
    }
    $needed = array_unique($mm[1]);
    ap_remote_emoji_ensure_host($host, false, $allowFetch);
    $map = ap_remote_emoji_map_for_host($host);
    $missing = [];
    foreach ($needed as $code) {
        if (!isset($map[$code])) {
            $missing[] = $code;
        }
    }
    if (!$missing) {
        return;
    }
    if (!$allowFetch) {
        return;
    }
    // Actor document often carries exactly the Emoji tags used in the name (Wafrn, etc.)
    static $fetchedActors = [];
    if (isset($fetchedActors[$actorId])) {
        return;
    }
    $fetchedActors[$actorId] = true;
    if (!function_exists('ap_fetch_as2_object')) {
        if (!defined('AP_INBOX_LIB_ONLY')) {
            define('AP_INBOX_LIB_ONLY', true);
        }
        @require_once __DIR__ . '/ap-inbox.php';
    }
    if (!function_exists('ap_fetch_as2_object')) {
        return;
    }
    try {
        $doc = ap_fetch_as2_object($actorId);
        if (is_array($doc)) {
            ap_remote_emoji_ingest_actor_doc($actorId, $doc);
            ap_remote_emoji_map_for_host($host, true);
        }
    } catch (Throwable $e) {
        error_log('[ap-db] emoji actor fetch: ' . $e->getMessage());
    }
}

/**
 * HTML-escape text and replace :shortcode: with <img class="custom-emoji"> when known.
 */
function ap_emoji_html(string $text, ?string $actorId = null): string
{
    if ($text === '') {
        return '';
    }
    $host = null;
    if (is_string($actorId) && $actorId !== '') {
        $h = parse_url($actorId, PHP_URL_HOST);
        $host = is_string($h) ? strtolower($h) : null;
        if ($host && str_contains($text, ':')) {
            // Fetch the host emoji map once when a display name introduces an
            // unfamiliar shortcode; subsequent renders use the local cache.
            ap_remote_emoji_ensure_for_display($actorId, $text, true);
        }
    }
    $map = $host ? ap_remote_emoji_map_for_host($host) : [];
    if ($map === [] || !preg_match('/:[A-Za-z0-9_-]{1,80}:/', $text)) {
        return htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }

    $out = '';
    $offset = 0;
    if (!preg_match_all('/:([A-Za-z0-9_-]{1,80}):/', $text, $mm, PREG_OFFSET_CAPTURE)) {
        return htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }
    foreach ($mm[0] as $i => $full) {
        $start = (int) $full[1];
        $token = $full[0];
        $code = $mm[1][$i][0];
        if ($start > $offset) {
            $out .= htmlspecialchars(substr($text, $offset, $start - $offset), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        $url = $map[$code] ?? null;
        if (is_string($url) && str_starts_with($url, 'https://')) {
            $safeUrl = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $safeAlt = htmlspecialchars(':' . $code . ':', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $out .= '<img class="custom-emoji" src="' . $safeUrl . '" alt="' . $safeAlt . '" title="'
                . $safeAlt . '" width="20" height="20" loading="lazy" decoding="async" referrerpolicy="no-referrer">';
        } else {
            $out .= htmlspecialchars($token, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        $offset = $start + strlen($token);
    }
    if ($offset < strlen($text)) {
        $out .= htmlspecialchars(substr($text, $offset), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }
    return $out;
}

function ap_remote_media_get(string $actorId, string $kind): ?array
{
    $actorId = rtrim(trim($actorId), '/');
    $kind = $kind === 'header' ? 'header' : 'avatar';
    $st = ap_db()->prepare('SELECT * FROM remote_media_cache WHERE actor_id = ? AND kind = ?');
    $st->execute([$actorId, $kind]);
    $row = $st->fetch();
    return is_array($row) ? $row : null;
}

function ap_remote_media_touch(string $actorId, string $kind): void
{
    $actorId = rtrim(trim($actorId), '/');
    $kind = $kind === 'header' ? 'header' : 'avatar';
    // Throttle writes: updating last_used_at on every timeline/notif avatar
    // lookup caused SQLite lock storms under concurrent inbox delivery.
    try {
        $st = ap_db()->prepare(
            'UPDATE remote_media_cache SET last_used_at = ?
             WHERE actor_id = ? AND kind = ?
               AND (last_used_at IS NULL OR last_used_at < ?)'
        );
        $st->execute([
            ap_db_now(),
            $actorId,
            $kind,
            gmdate('c', time() - 3600), // at most once per hour per avatar/header
        ]);
    } catch (Throwable $e) {
        // Never fail a page render over LRU bookkeeping
    }
}

/**
 * @return list<array<string,mixed>>
 */
function ap_remote_media_expired(int $unusedDays = 7, int $limit = 200): array
{
    $unusedDays = max(1, min(365, $unusedDays));
    $limit = max(1, min(1000, $limit));
    $cutoff = gmdate('c', time() - ($unusedDays * 86400));
    $st = ap_db()->prepare(
        'SELECT * FROM remote_media_cache WHERE last_used_at < ? ORDER BY last_used_at ASC LIMIT ?'
    );
    $st->execute([$cutoff, $limit]);
    return $st->fetchAll();
}

function ap_remote_media_delete_row(int $id): void
{
    ap_db()->prepare('DELETE FROM remote_media_cache WHERE id = ?')->execute([$id]);
}
